INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他思辨着很久，才做出选择。", "corrected_sentence": "他思辨了很久，才做出选择。", "error_description": "体标错误：“很久”是时量补语，表示动作已经持续了一段时间，后面还有“才做出选择”，所以“思辨”后要用完成体“了”，不能用表示持续状态的“着”。应说“思辨了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们认真思辨一只问题。", "corrected_sentence": "他们认真思辨一个问题。", "error_description": "错误在量词：“问题”应用“个”计量，“只”多用于动物或成对事物中的单个，不能用于“问题”。正确形式为“认真思辨一个问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27590, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "来", "is_correct": true, "explanation": "“来”与“去”相对，表示朝说话人所在处移动。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”表示进食，与“去”不构成反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”表示书写，与“去”不构成反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”表示入睡，与“去”不构成反义关系。"}], "correct_answer": "来", "explanations": {"来": "“来”与“去”相对，表示朝说话人所在处移动。", "吃": "“吃”表示进食，与“去”不构成反义关系。", "写": "“写”表示书写，与“去”不构成反义关系。", "睡": "“睡”表示入睡，与“去”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
