INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27590, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从自己这里到别的地方。", "primary_collocate": null, "pronunciation": "qù", "ipa": "tɕʰy˥˩", "syllable_count": 1, "sentences": [{"text": "我明天去学校。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去超市买水果。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候去北京？", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们周末去公园玩吧。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她昨天去了医院。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去过上海两次。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟每天骑车去学校。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期六你去不去看电影？", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈去商店给我买书了。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有个公园，我常去那儿散步。", "target_word": "去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去了", "label": "完成体"}, {"form": "去过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "从自己所在之处前往别的地方（泛指移动、前往）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9421cf6-24de-499f-a0bb-a94d3893ac19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27590, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "去", "is_correct": true, "explanation": "去 qù：从自己所在之处到别的地方，是本词的读音和义项。"}, {"text": "取", "is_correct": false, "explanation": "取 qǔ（第三声）与 qù（第四声）声调不同，意思是拿、取。"}, {"text": "区", "is_correct": false, "explanation": "区 qū（第一声）与 qù（第四声）声调不同，意思是地区。"}, {"text": "句", "is_correct": false, "explanation": "句 jù 与 qù 声母不同（j 与 q），声调相同，意思是句子。"}, {"text": "聚", "is_correct": false, "explanation": "聚 jù 与 qù 声母不同（j 与 q），声调相同，意思是聚集。"}], "explanations": {"去": "去 qù：从自己所在之处到别的地方，是本词的读音和义项。", "取": "取 qǔ（第三声）与 qù（第四声）声调不同，意思是拿、取。", "区": "区 qū（第一声）与 qù（第四声）声调不同，意思是地区。", "句": "句 jù 与 qù 声母不同（j 与 q），声调相同，意思是句子。", "聚": "聚 jù 与 qù 声母不同（j 与 q），声调相同，意思是聚集。"}, "sentence_index": null, "correct_answer": "去"}, "level_3": {"options": [{"text": "去", "is_correct": true, "explanation": "“去”表示从这里前往学校，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣服鞋子，不能说“穿学校”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃学校”。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的宾语应是声音、音乐，不能说“听学校”。"}], "explanations": {"去": "“去”表示从这里前往学校，符合句意。", "穿": "搭配：“穿”的宾语应是衣服鞋子，不能说“穿学校”。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃学校”。", "听": "搭配：“听”的宾语应是声音、音乐，不能说“听学校”。"}, "sentence_index": 0, "correct_answer": "去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在家等你，你快去这儿。", "explanation": "这里应该用〈来〉。说话人在“这儿”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "我在车站等你，你快去车站。", "explanation": "这里应该用〈来〉。说话人在“车站”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "我在教室等你，你快去教室。", "explanation": "这里应该用〈来〉。说话人在“教室”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27590, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "去", "is_correct": true, "explanation": "去 qù：从自己所在之处到别的地方，是本词的读音和义项。"}, {"text": "娶", "is_correct": false, "explanation": "娶 qǔ（第三声）与 qù（第四声）声调不同，意思是娶妻。"}, {"text": "曲", "is_correct": false, "explanation": "曲 qǔ（第三声）与 qù（第四声）声调不同，意思是歌曲、曲线。"}, {"text": "据", "is_correct": false, "explanation": "据 jù 与 qù 声母不同（j 与 q），声调相同，意思是根据。"}, {"text": "屈", "is_correct": false, "explanation": "屈 qū（第一声）与 qù（第四声）声调不同，意思是弯曲、屈服。"}], "explanations": {"去": "去 qù：从自己所在之处到别的地方，是本词的读音和义项。", "娶": "娶 qǔ（第三声）与 qù（第四声）声调不同，意思是娶妻。", "曲": "曲 qǔ（第三声）与 qù（第四声）声调不同，意思是歌曲、曲线。", "据": "据 jù 与 qù 声母不同（j 与 q），声调相同，意思是根据。", "屈": "屈 qū（第一声）与 qù（第四声）声调不同，意思是弯曲、屈服。"}, "sentence_index": null, "correct_answer": "去"}, "level_3": {"options": [{"text": "去", "is_correct": true, "explanation": "“去”表示骑车前往学校，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应是衣服鞋子，不能说“骑车穿学校”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能说“喝学校”。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语应是字、文章，不能说“骑车写学校”。"}], "explanations": {"去": "“去”表示骑车前往学校，符合句意。", "穿": "搭配：“穿”的宾语应是衣服鞋子，不能说“骑车穿学校”。", "喝": "搭配：“喝”的宾语应是饮品，不能说“喝学校”。", "写": "搭配：“写”的宾语应是字、文章，不能说“骑车写学校”。"}, "sentence_index": 6, "correct_answer": "去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在操场等你，你快去操场。", "explanation": "这里应该用〈来〉。说话人在“操场”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "我在门口等你，你快去门口。", "explanation": "这里应该用〈来〉。说话人在“门口”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}, {"text": "我在办公室等你，你快去办公室。", "explanation": "这里应该用〈来〉。说话人在“办公室”，对方朝说话人所在处移动要用“来”，“去”表示离开说话人所在之处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96959d08-6ad6-4952-b312-83e10f288f75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used =