INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27594, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或身体碰到东西。", "primary_collocate": null, "pronunciation": "chù jí", "ipa": "tʂʰu˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "小孩的手刚好触及桌子的边。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他伸出手，终于触及了那盏灯。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要触及展览的画。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的头发轻轻触及我的肩膀。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脚尖刚触及水面，他就觉得冷。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手指触及了冰冷的门。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机的轮子触及地面时很平稳。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踮起脚，却触及不到书架顶。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的鼻子触及了我的手。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别让手触及热锅。", "target_word": "触及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "触及了", "label": "完成体"}, {"form": "触及过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "手或身体具体地碰到物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。触及（chù jí）意思是用手或身体碰到东西。"}, {"text": "初级", "is_correct": false, "explanation": "chū jí（第一声）与 chù jí（第四声）第一音节声调不同，意思是初级。"}, {"text": "除籍", "is_correct": false, "explanation": "chú jí（第二声）与 chù jí（第四声）第一音节声调不同，意思是除去名籍。"}, {"text": "出击", "is_correct": false, "explanation": "chū jī（第一声）与 chù jí 两个音节声调都不同，意思是主动发起攻击。"}], "explanations": {"触及": "正确答案。触及（chù jí）意思是用手或身体碰到东西。", "初级": "chū jí（第一声）与 chù jí（第四声）第一音节声调不同，意思是初级。", "除籍": "chú jí（第二声）与 chù jí（第四声）第一音节声调不同，意思是除去名籍。", "出击": "chū jī（第一声）与 chù jí 两个音节声调都不同，意思是主动发起攻击。"}, "sentence_index": null, "correct_answer": "触及"}, "level_3": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。“手刚好触及桌子的边”表示手碰到桌子边缘。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤指用火加热，不能用来描述手碰到桌子。"}, {"text": "搞", "is_correct": false, "explanation": "语域：口语色彩很重，与本句的书面语域不合。"}, {"text": "熨烫", "is_correct": false, "explanation": "语义：熨烫指用熨斗使衣物平整，不能用于手碰桌子。"}], "explanations": {"触及": "正确答案。“手刚好触及桌子的边”表示手碰到桌子边缘。", "烘烤": "语义：烘烤指用火加热，不能用来描述手碰到桌子。", "搞": "语域：口语色彩很重，与本句的书面语域不合。", "熨烫": "语义：熨烫指用熨斗使衣物平整，不能用于手碰桌子。"}, "sentence_index": 0, "correct_answer": "触及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他狠狠触及了孩子。", "explanation": "这里应该用〈打〉。触及只是轻轻碰到，不表示用力击打。"}, {"text": "他紧紧触及了绳子。", "explanation": "这里应该用〈抓住〉。触及只表示碰到，不表示握紧。"}, {"text": "她远远地触及了那本书。", "explanation": "这里应该用〈看见〉。触及需要用手或身体碰到东西，“远远地”说明没有接触，不能用触及，远远看见那本书才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "触及", "is_correct": true, "explanation": "正确答案。“飞机的轮子触及地面”表示轮子碰到地面。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮用于食物，不能用来描述飞机轮子与地面的接触。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：挥霍指浪费财物，与飞机轮子碰地面无关。"}, {"text": "弄", "is_correct": false, "explanation": "语域：口语色彩较重，与本句的书面语域不合。"}], "explanations": {"触及": "正确答案。“飞机的轮子触及地面”表示轮子碰到地面。", "煮": "语义：煮用于食物，不能用来描述飞机轮子与地面的接触。", "挥霍": "语义：挥霍指浪费财物，与飞机轮子碰地面无关。", "弄": "语域：口语色彩较重，与本句的书面语域不合。"}, "sentence_index": 6, "correct_answer": "触及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经常触及那个下午。", "explanation": "这里应该用〈度过〉。触及表示用手或身体碰到东西，不能支配“下午”这类时间名词，度过那个下午才是正确搭配。"}, {"text": "我在街上触及老师。", "explanation": "这里应该用〈碰到〉。遇见某人要用碰到，触及不用于遇见人。"}, {"text": "她在晚会上触及了一首歌。", "explanation": "这里应该用〈唱〉。触及表示用手或身体碰到东西，不能用于唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她伸手终于触及着门把手。", "corrected_sentence": "她伸手终于触及了门把手。", "error_description": "错误在体标：“终于”表示动作已经完成，应与完成体“了”搭配，持续体“着”与之不合。正确形式为“终于触及了门把手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他却触及不墙上的画。", "corrected_sentence": "他却触及不到墙上的画。", "error_description": "错误在补语：可能补语“触及不到”少了“到”，应说“触及不到墙上的画”，不能只说“触及不墙上的画”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "变弱", "is_correct": true, "explanation": "正确：“变弱”与“变强”互为反义，指变得没有以前厉害，与本句的语境相对。"}, {"text": "散步", "is_correct": false, "explanation": "不构成反义：“散步”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "画画", "is_correct": false, "explanation": "不构成反义：“画画”与“变强”没有对立关系，只是不相关的动词。"}, {"text": "跳舞", "is_correct": false, "explanation": "不构成反义：“跳舞”与“变强”没有对立关系，只是不相关的动词。"}], "correct_answer": "变弱", "explanations": {"变弱": "正确：“变弱”与“变强”互为反义，指变得没有以前厉害，与本句的语境相对。", "散步": "不构成反义：“散步”与“变强”没有对立关系，只是不相关的动词。", "画画": "不构成反义：“画画”与“变强”没有对立关系，只是不相关的动词。", "跳舞": "不构成反义：“跳舞”与“变强”没有对立关系，只是不相关的动词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5dafca81-709f-4144-9629-505a8f340f5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
