INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27598, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "你周围的一切，比如你住的房子外面的东西。", "primary_collocate": null, "pronunciation": "wài bù huán jìng", "ipa": "wai˥˩ pu˥˩ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "我家的外部环境很安静，我睡得很好。", "target_word": "外部环境", "complexity_tier": "T3", "furigana": "wài bù huán jìng", "sentence_source": "generated"}, {"text": "这个城市的外部环境很干净。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要好的外部环境才能健康长大。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部环境太吵，他没办法学习。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我还不习惯这里的外部环境。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小花在新的外部环境里长得很快。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园附近的外部环境对老人很好。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先看看学校的外部环境怎么样。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部环境很吵，晚上很难睡觉。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这里，因为外部环境又安全又干净。", "target_word": "外部环境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部环境因素", "label": "复合"}], "register": "中性", "sense_fingerprint": "人周围、住处外面的一切", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27598, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外部环境", "is_correct": true, "explanation": "正确。“我家的外部环境很安静，我睡得很好”，外部环境指住处外面、周围的事物，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不能用“很安静”来形容，也不能说“我家的数学”。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”描述人的面部气色，与“我家”和“安静”的搭配不通。"}, {"text": "俗语", "is_correct": false, "explanation": "语义：“俗语”是一句流传的话，不能说“我家的俗语很安静”。"}], "explanations": {"外部环境": "正确。“我家的外部环境很安静，我睡得很好”，外部环境指住处外面、周围的事物，符合句意。", "数学": "语义：“数学”是学科，不能用“很安静”来形容，也不能说“我家的数学”。", "脸色": "体貌：“脸色”描述人的面部气色，与“我家”和“安静”的搭配不通。", "俗语": "语义：“俗语”是一句流传的话，不能说“我家的俗语很安静”。"}, "sentence_index": 0, "correct_answer": "外部环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的外部环境很普通，大家都记不住。", "explanation": "这里应该用〈外貌〉。“外貌”指人的外表，形容人的样子要说“外貌”；“外部环境”指住处外面的东西，不能用来形容人。"}, {"text": "我们把外部环境装进了箱子里。", "explanation": "这里应该用〈行李〉。外部环境指周围的情况，不是具体的物体，不能装进箱子；装箱的东西要用“行李”。"}, {"text": "这套房子有一条很好的外部环境。", "explanation": "量词错误：“外部环境”不能用〈条〉（〈条〉用于细长的物体）；这里可以直接说“很好的外部环境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部环境", "is_correct": true, "explanation": "正确。“公园附近的外部环境对老人很好”，外部环境指周围的情况，符合句意。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”是付款的记录，与公园附近的环境好坏无关。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是人或物的称呼，不能说“对老人很好”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描述人的身体，不能用来指公园周围的情况。"}], "explanations": {"外部环境": "正确。“公园附近的外部环境对老人很好”，外部环境指周围的情况，符合句意。", "账单": "语义：“账单”是付款的记录，与公园附近的环境好坏无关。", "名字": "语义：“名字”是人或物的称呼，不能说“对老人很好”。", "身高": "体貌：“身高”描述人的身体，不能用来指公园周围的情况。"}, "sentence_index": 6, "correct_answer": "外部环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的外部环境很漂亮，颜色也好。", "explanation": "这里应该用〈外形〉。“外形”指物体的样子，说车的样子要用“外形”；“外部环境”指周围的情况，不能用来说车的样子。"}, {"text": "我把外部环境放进了冰箱里。", "explanation": "这里应该用〈剩菜〉。外部环境指周围的情况，不是具体的东西，不能放进冰箱。"}, {"text": "这位外部环境很干净，我很喜欢。", "explanation": "量词错误：“外部环境”不是人，不能用〈位〉（〈位〉用于人）；这里可以说“这里的外部环境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们找到了一只安静的外部环境。", "corrected_sentence": "我们找到了一个安静的外部环境。", "error_description": "量词错误：“外部环境”应搭配量词“个”，不能用“只”（“只”多用于动物或成对物件中的一个）。正确说法是：一个安静的外部环境。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校有一件很好的外部环境。", "corrected_sentence": "我们学校有一个很好的外部环境。", "error_description": "量词错误：“外部环境”应搭配量词“个”，不能用“件”（“件”用于衣服、事情等）。正确说法是：一个很好的外部环境。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
