INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27600, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据知道的事情想出答案。", "primary_collocate": null, "pronunciation": "tuī lǐ", "ipa": "tʰweɪ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察根据线索推理出了小偷是谁。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能推理出下一个数字是几吗？", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢动脑筋，常常自己推理答案。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我根据桌上的杯子，推理出他刚走。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们正在推理谁拿走了蛋糕。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先想一想，再推理答案。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题只要推理一下，就能做对。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用已知的信息推理，很快找到了答案。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没看见他，但可以根据这些情况推理出他不在家。", "target_word": "推理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有线索放在一起推理。", "target_word": "推理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "推理了", "label": "体标"}, {"form": "推理过", "label": "体标"}], "register": "中性", "sense_fingerprint": "推理：根据已知的事情想出答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指做点心，与找出小偷无关。"}, {"text": "嘟囔", "is_correct": false, "explanation": "语义：“嘟囔”是小声说话或自言自语，不能表示根据线索推断出结论。"}, {"text": "鞠躬", "is_correct": false, "explanation": "配价：“鞠躬”是不及物动词，不能带结果补语“出”和后面的宾语。"}, {"text": "推理", "is_correct": true, "explanation": "正确：推理指根据已知的线索想出答案，“推理出”即由线索得出结论。"}], "explanations": {"烘焙": "语义：“烘焙”指做点心，与找出小偷无关。", "嘟囔": "语义：“嘟囔”是小声说话或自言自语，不能表示根据线索推断出结论。", "鞠躬": "配价：“鞠躬”是不及物动词，不能带结果补语“出”和后面的宾语。", "推理": "正确：推理指根据已知的线索想出答案，“推理出”即由线索得出结论。"}, "sentence_index": 0, "correct_answer": "推理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我只是推理他刚走，并没有依据。", "explanation": "这里应该用〈猜测〉。推理需要依据，说“并没有依据”的想法应说猜测。"}, {"text": "他在纸上推理出了一只猫。", "explanation": "这里应该用〈画〉。画是用笔描绘出形象，推理是思维活动，不能用来在纸上画东西。"}, {"text": "他把课文推理得很熟。", "explanation": "这里应该用〈背诵〉。背诵是记住原文，推理不能用来把课文记熟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跳跃", "is_correct": false, "explanation": "语义：跳跃与做题无关，“做对”需要的是思考。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽不能帮助人把题目做对。"}, {"text": "唠嗑", "is_correct": false, "explanation": "语义：“唠嗑”是闲聊，闲聊不能帮人把题做对。"}, {"text": "推理", "is_correct": true, "explanation": "正确：推理指根据已知信息想出答案，“推理一下”即想一想就能做对。"}], "explanations": {"跳跃": "语义：跳跃与做题无关，“做对”需要的是思考。", "咳嗽": "语义：咳嗽不能帮助人把题目做对。", "唠嗑": "语义：“唠嗑”是闲聊，闲聊不能帮人把题做对。", "推理": "正确：推理指根据已知信息想出答案，“推理一下”即想一想就能做对。"}, "sentence_index": 6, "correct_answer": "推理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书包推理好了，准备上学。", "explanation": "这里应该用〈收拾〉。收拾是整理物品，推理是思维活动，不能用来整理书包。"}, {"text": "她在教室里推理一朵花。", "explanation": "这里应该用〈摘〉。摘是把花从植物上取下，推理是思维活动，不能用来取花。"}, {"text": "我们推理教室。", "explanation": "这里应该用〈打扫〉。打扫是清理环境，推理不能用来清理教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我推理过过这道题。", "corrected_sentence": "我推理过这道题。", "error_description": "体标重复错误：“过”只用一次，应说“推理过这道题”，不能说“推理过过这道题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我推理一个，就知道答案。", "corrected_sentence": "我推理一下，就知道答案。", "error_description": "动量词错误：“推理”后的动量词应用“一下”，不能用表示事物的“一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
