INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西说好了怎么连在一起用的规则。", "primary_collocate": null, "pronunciation": "jiē kǒu xié yì", "ipa": "tɕjɛ˥ kʰoʊ˨˩˦ ɕjɛ˧˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "两个设备连在一起，要有接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "接口协议就是连接的规则。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有接口协议，两个软件不能一起工作。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "充电器和手机用同一个接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们先看接口协议再写程序。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个接口协议很简单，一看就懂。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司约好了接口协议，才开始合作。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在网上查到了新的接口协议。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "接口协议不对，机器就连不上。", "target_word": "接口协议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个接口协议都说明怎么连接和传数据。", "target_word": "接口协议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接口協議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "接口协议：两个东西约定好怎么连在一起使用的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2e370e-2ea2-4fb6-b66c-628b6aedac9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27604, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与两个设备能否连在一起无关，不是连接所需的条件。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：“相貌”指人的容貌，不能用来形容设备。"}, {"text": "套路", "is_correct": false, "explanation": "语域：“套路”是口语，与这句的技术语境不合。"}, {"text": "接口协议", "is_correct": true, "explanation": "正确：接口协议正是两个东西连在一起用时需要事先约定好的规则。"}], "explanations": {"颜色": "语义：“颜色”与两个设备能否连在一起无关，不是连接所需的条件。", "相貌": "语义：“相貌”指人的容貌，不能用来形容设备。", "套路": "语域：“套路”是口语，与这句的技术语境不合。", "接口协议": "正确：接口协议正是两个东西连在一起用时需要事先约定好的规则。"}, "sentence_index": 0, "correct_answer": "接口协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一把接口协议规定了两个设备的连接方式。", "explanation": "这里应该用〈份〉。协议属于文件，用“份”计量，不能用“把”。"}, {"text": "他拔下了手机的接口协议。", "explanation": "这里应该用〈接口〉。接口是可以拔下来的实物插口；接口协议是双方约定的规则，不能被拔下来。"}, {"text": "他会说三种接口协议。", "explanation": "这里应该用〈语言〉。人说的是语言；接口协议是机器之间的规则，不能用“说”来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能由两家公司约定，与合作无关。"}, {"text": "窍门", "is_correct": false, "explanation": "语域：“窍门”是口语，与这句书面化的叙述不合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，两家公司约好的不可能是脾气。"}, {"text": "接口协议", "is_correct": true, "explanation": "正确：接口协议是双方约定的连接规则，约好之后才能开始合作。"}], "explanations": {"天气": "语义：天气不能由两家公司约定，与合作无关。", "窍门": "语域：“窍门”是口语，与这句书面化的叙述不合。", "脾气": "语义：“脾气”指人的性情，两家公司约好的不可能是脾气。", "接口协议": "正确：接口协议是双方约定的连接规则，约好之后才能开始合作。"}, "sentence_index": 6, "correct_answer": "接口协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司签了一份接口协议，然后把它喝了下去。", "explanation": "这里应该用〈读〉。接口协议是文件，可以读，不能喝。"}, {"text": "这场棋赛的接口协议很严格。", "explanation": "这里应该用〈规则〉。规则约束棋赛、比赛等活动；接口协议只约束机器之间的数据交换。"}, {"text": "奶奶说一口流利的客家接口协议。", "explanation": "这里应该用〈方言〉。方言是人说的话；接口协议是机器之间的约定，不能用“说”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司签了一只接口协议。", "corrected_sentence": "两家公司签了一份接口协议。", "error_description": "量词错误：“只”用于动物，接口协议是文件，应说“份”，不能说“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在网上查到了一匹新的接口协议。", "corrected_sentence": "他在网上查到了一份新的接口协议。", "error_description": "量词错误：“匹”用于马等动物或布，接口协议是文件，应说“一份”，不能说“一匹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec9c7671-f8e6-4a19-9d02-eb896a1b505d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
