INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "这个东西可以方便地换到别的电脑上使用。", "primary_collocate": null, "pronunciation": "kě yí zhí xìng", "ipa": "kʰɤ˨˩˦ i˧˥ ʈʂɨ˧˥ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个小工具的可移植性很好，换台电脑就能用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买软件以前，我会先看看它的可移植性。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的游戏可移植性不好，不能换电脑玩。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可移植性高，说明换电脑时不用重新安装。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，好程序要有可移植性。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办公软件的可移植性让同事们很满意。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为可移植性差，这个软件只能在旧电脑上用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这个软件，主要是它的可移植性好。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想提高软件的可移植性，方便用户换电脑。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的可移植性怎么样，试一试就知道了。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "东西能方便地换到别的电脑上使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f7f17ff-c32d-47a8-bf1e-867aef9f7341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：指东西能方便地换到别的电脑上使用，与“换台电脑就能用”相符。"}, {"text": "防水性", "is_correct": false, "explanation": "语义：句末说“换台电脑就能用”，与防水无关，句意不通。"}, {"text": "续航力", "is_correct": false, "explanation": "语义：续航与换到哪台电脑上使用无关，与句中的因果不符。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度与软件能否换到别的电脑上使用无关，句意不通。"}], "explanations": {"可移植性": "正确：指东西能方便地换到别的电脑上使用，与“换台电脑就能用”相符。", "防水性": "语义：句末说“换台电脑就能用”，与防水无关，句意不通。", "续航力": "语义：续航与换到哪台电脑上使用无关，与句中的因果不符。", "亮度": "语义：亮度与软件能否换到别的电脑上使用无关，句意不通。"}, "sentence_index": 0, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的可移植性很强，居民生活很方便。", "explanation": "这里应该用〈宜居性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说城市是否适合居住。"}, {"text": "这栋楼的可移植性很好，地震时也很安全。", "explanation": "这里应该用〈稳定性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说建筑承受外力的能力。"}, {"text": "他跳舞的可移植性很好，动作很整齐。", "explanation": "这里应该用〈协调性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说人动作配合得是否协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：说明软件换到新电脑上用不了，与“只能在旧电脑上用”相符。"}, {"text": "透气性", "is_correct": false, "explanation": "搭配：“透气性”多用于布料和衣物，不用来说明软件能否换机使用。"}, {"text": "耐寒性", "is_correct": false, "explanation": "搭配：“耐寒性”指材料耐低温，不用来说明软件的使用范围。"}, {"text": "耐磨性", "is_correct": false, "explanation": "语义：“耐磨性”指物体经受磨损的能力，与软件能在哪台电脑上运行无关。"}], "explanations": {"可移植性": "正确：说明软件换到新电脑上用不了，与“只能在旧电脑上用”相符。", "透气性": "搭配：“透气性”多用于布料和衣物，不用来说明软件能否换机使用。", "耐寒性": "搭配：“耐寒性”指材料耐低温，不用来说明软件的使用范围。", "耐磨性": "语义：“耐磨性”指物体经受磨损的能力，与软件能在哪台电脑上运行无关。"}, "sentence_index": 6, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的可移植性很高，蛋白质很丰富。", "explanation": "这里应该用〈营养价值〉。可移植性指东西能方便地换到别的电脑上使用，不用来说食物的营养。"}, {"text": "这所学校的可移植性很高，老师都很认真。", "explanation": "这里应该用〈教学质量〉。可移植性指东西能方便地换到别的电脑上使用，不用来说学校的教学水平。"}, {"text": "这位老师对学生的可移植性很好，讲题讲了很多遍。", "explanation": "这里应该用〈耐心〉。可移植性指东西能方便地换到别的电脑上使用，不用来说老师对学生是否有耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小工具有很好可移植性，换电脑很方便。", "corrected_sentence": "这个小工具有很好的可移植性，换电脑很方便。", "error_description": "缺少“的”：“很好”修饰名词“可移植性”时中间要加“的”。正确说法是“很好的可移植性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件的可移植性的很好，换台电脑就能直接用。", "corrected_sentence": "这个软件的可移植性很好，换台电脑就能直接用。", "error_description": "多余的“的”：“可移植性”后直接接“很好”作谓语，不能加“的”。正确说法是“这个软件的可移植性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c165fc5-8ecb-4d31-a2d9-19aa7e835074') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把带子、绳子扎紧，与“解开”的意思相反。"}, {"text": "量", "is_correct": false, "explanation": "“量”指测量长短大小，与“解”不构成反义关系。"}, {"text": "找", "is_correct": false, "explanation": "“找”指寻求、寻找，与“解”不构成反义关系。"}, {"text": "捡", "is_correct": false, "explanation": "“捡”指拾取，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把带子、绳子扎紧，与“解开”的意思相反。", "量": "“量”指测量长短大小，与“解”不构成反义关系。", "找": "“找”指寻求、寻找，与“解”不构成反义关系。", "捡": "“捡”指拾取，与“解”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把红绳、带子扎紧，与“解一下红绳”的动作相反。"}, {"text": "搬", "is_correct": false, "explanation": "“搬”指移动物体的位置，与“解”不构成反义关系。"}, {"text": "敲", "is_correct": false, "explanation": "“敲”指用物体撞击，与“解”不构成反义关系。"}, {"text": "扛", "is_correct": false, "explanation": "“扛”指把东西架在肩上，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把红绳、带子扎紧，与“解一下红绳”的动作相反。", "搬": "“搬”指移动物体的位置，与“解”不构成反义关系。", "敲": "“敲”指用物体撞击，与“解”不构成反义关系。", "扛": "“扛”指把东西架在肩上，与“解”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西打开或分开。", "primary_collocate": null, "pronunciation": "jiě", "ipa": "tɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他回到家，先解包裹上的带子。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发上的绳子解了，头发散下来。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫坐在船边解网。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷慢慢解袋子口的线。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天热了，他解围巾，放进包里。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你解一下腰带，会舒服一点。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子急着解礼物上的丝带。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解书包上的拉绳，拿出本子。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人解口袋里的小布包，拿出钱。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你解一下这个盒子上的红绳。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解了", "label": "体标：了"}, {"form": "解过", "label": "体标：过"}, {"form": "解开", "label": "复合"}], "register": "中性", "sense_fingerprint": "把捆着或合着的东西打开、分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。", "借": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。", "结": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。", "接": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。", "介": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指打开包裹上的带子，与“先”和“包裹上的带子”搭配，句子通顺。"}, {"text": "舔", "is_correct": false, "explanation": "语义：“舔”是用舌头接触，与打开带子的动作不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于清洁，不能说洗包裹上的带子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与包裹和带子无关。"}], "explanations": {"解": "“解”指打开包裹上的带子，与“先”和“包裹上的带子”搭配，句子通顺。", "舔": "语义：“舔”是用舌头接触，与打开带子的动作不符。", "洗": "搭配：“洗”用于清洁，不能说洗包裹上的带子。", "吃": "语义：“吃”指进食，与包裹和带子无关。"}, "sentence_index": 0, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈解开那碗汤，慢慢喝了下去。", "explanation": "这里应该用〈端〉。解开指打开捆着或合着的东西，碗里的汤不是这类东西，应说“端”。"}, {"text": "她解开橘子皮，递给我一瓣。", "explanation": "这里应该用〈剥〉。橘子皮包在果肉外面，去皮要用“剥”，不用“解开”。"}, {"text": "他解开那杯牛奶，喝了一口。", "explanation": "这里应该用〈倒〉。解开指打开捆着或合着的东西，杯中的牛奶不能用“解开”，应说“倒”出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}, {"text": "戒", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。"}, {"text": "界", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。", "节": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。", "街": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。", "戒": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。", "界": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指打开礼物上的丝带，与“急着”和“礼物上的丝带”搭配，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与丝带无关。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”用于烹饪食物，不能用于丝带。"}, {"text": "梳", "is_correct": false, "explanation": "搭配：“梳”多用于头发，不说梳礼物上的丝带。"}], "explanations": {"解": "“解”指打开礼物上的丝带，与“急着”和“礼物上的丝带”搭配，句子通顺。", "唱": "语义：“唱”指发出歌声，与丝带无关。", "煎": "语义：“煎”用于烹饪食物，不能用于丝带。", "梳": "搭配：“梳”多用于头发，不说梳礼物上的丝带。"}, "sentence_index": 6, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈解了一锅粥，给全家人盛好。", "explanation": "这里应该用〈煮〉。解指打开或松开，不能表示烹饪，煮粥要用“煮”。"}, {"text": "这个小孩解了一杯果汁，一口气喝光了。", "explanation": "这里应该用〈端〉。解指打开或分开捆着、合着的东西，果汁不是这类东西，应说“端”。"}, {"text": "这道数学题他解了半天，终于解出来了。", "explanation": "这里的〈解〉是解答难题的意思，不是“打开或分开东西”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前解了过这条腰带。", "corrected_sentence": "他以前解过这条腰带。", "error_description": "错误：“解了过”；正确：“解过”。“过”表示曾经有过这样的经历，不能与表示完成的“了”同用，动词后只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她开解了红绳。", "corrected_sentence": "她解开了红绳。", "error_description": "错误：“开解”；正确：“解开”。“开”是结果补语，必须紧跟动词之后，应说“解开”，表示红绳被打开。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
