INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27612, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（人或事物）新旧交替，轮流更换。", "primary_collocate": null, "pronunciation": "gēng dié", "ipa": "kɤŋ˥ tjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "店里的商品更迭很快，旧款很快就没有了。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班级干部每年更迭一次。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的经理经常更迭。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的节目更迭得很快。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板更迭了三次。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服的款式每年都在更迭。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏秋更迭之时，天气很舒服。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的校长不常更迭。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新旧版本更迭时，用户要更新软件。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的领导人更迭得很平稳。", "target_word": "更迭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更迭了", "label": "体标：了"}], "register": "书面", "sense_fingerprint": "旧的换成新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fabc475-dc5d-4670-9ae4-ea63fd54f0fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27612, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更迭", "is_correct": true, "explanation": "“更迭”指商品旧的换成新的，与“旧款很快就没有了”相合。"}, {"text": "保留", "is_correct": false, "explanation": "语义：“保留”表示留存，与“旧款很快就没有了”相矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：商品不会生长，“生长”不能用来说商品的变化。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“呼吸”的主语要求是生物，不能说“商品呼吸”。"}], "explanations": {"更迭": "“更迭”指商品旧的换成新的，与“旧款很快就没有了”相合。", "保留": "语义：“保留”表示留存，与“旧款很快就没有了”相矛盾。", "生长": "搭配：商品不会生长，“生长”不能用来说商品的变化。", "呼吸": "配价：“呼吸”的主语要求是生物，不能说“商品呼吸”。"}, "sentence_index": 0, "correct_answer": "更迭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都更迭营养。", "explanation": "这里应该用〈补充〉。更迭指旧的换成新的，不用于给身体增加养分。"}, {"text": "我们为这道题更迭了半天，也没有想出答案。", "explanation": "这里应该用〈想〉。更迭指一个东西换成另一个东西，不指反复思考。"}, {"text": "我们更迭了教室。", "explanation": "这里应该用〈打扫〉。更迭指替换，不指把教室清理干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27612, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更迭", "is_correct": true, "explanation": "“更迭”指旧的换成新的，与“夏秋之时”的季节变化相合。"}, {"text": "凝固", "is_correct": false, "explanation": "搭配：“夏秋”是时间，不能说“凝固”，搭配不成立。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”意味着寒冷，与“天气很舒服”的语境相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人或物聚在一起，不能用来形容季节。"}], "explanations": {"更迭": "“更迭”指旧的换成新的，与“夏秋之时”的季节变化相合。", "凝固": "搭配：“夏秋”是时间，不能说“凝固”，搭配不成立。", "结冰": "语义：“结冰”意味着寒冷，与“天气很舒服”的语境相矛盾。", "拥挤": "语义：“拥挤”指人或物聚在一起，不能用来形容季节。"}, "sentence_index": 6, "correct_answer": "更迭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都更迭一个小时英语。", "explanation": "这里应该用〈学习〉。更迭指新旧交替，不指学习知识。"}, {"text": "大家在更迭风景。", "explanation": "这里应该用〈欣赏〉。更迭指替换，不指观看美景。"}, {"text": "小明每天早上都更迭一次呼吸。", "explanation": "这里不能用〈更迭〉。更迭指一样东西换成另一样，呼吸是持续的身体活动，不存在被替换的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27612, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "衣服的款式更迭的很快。", "corrected_sentence": "衣服的款式更迭得很快。", "error_description": "错误：“的”应为“得”。动词后表示程度的补语要用“得”连接，“更迭的很快”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27612, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的老板更迭了过三次。", "corrected_sentence": "这家店的老板更迭过三次。", "error_description": "错误：“更迭了过”；正确：“更迭过”。“过”表示曾经的经历，不能与“了”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35a7657b-ca48-4030-874b-933f99995abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
