INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "管事情的权利。", "primary_collocate": null, "pronunciation": "kòng zhì quán", "ipa": "kʰʊŋ˥˩ ʈʂɻ̩˥˩ tɕʰɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这家店的控制权在王先生手里。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想要公司的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把家里财务的控制权交给了我。", "target_word": "控制权", "complexity_tier": "T3", "furigana": "mā ma bǎ jiā lǐ cái wù de kòng zhì quán jiāo gěi le wǒ.", "sentence_source": "generated"}, {"text": "小明不愿意放弃游戏的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁拿到了控制权，谁就能做决定。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个股东在争公司的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板老了，把控制权交给女儿。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的控制权在经理手里。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有手机的控制权，可以关掉这个功能。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，想要自己生活的控制权。", "target_word": "控制权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控制", "label": "词根（动词）"}], "register": "中性", "sense_fingerprint": "管理、决定某件事的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控制权", "is_correct": true, "explanation": "正确。“这家店的控制权在王先生手里”表示管理这家店的权利属于王先生。"}, {"text": "味道", "is_correct": false, "explanation": "语义：店的“味道”不能放在某人手里，与“控制权”所表达的管理权不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或物的高度，不能说“这家店的身高”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能“在王先生手里”，句子无法成立。"}], "explanations": {"控制权": "正确。“这家店的控制权在王先生手里”表示管理这家店的权利属于王先生。", "味道": "语义：店的“味道”不能放在某人手里，与“控制权”所表达的管理权不符。", "身高": "搭配：“身高”只用于人或物的高度，不能说“这家店的身高”。", "天气": "语义：“天气”不能“在王先生手里”，句子无法成立。"}, "sentence_index": 0, "correct_answer": "控制权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找不到电视的控制权。", "explanation": "这里应该用〈遥控器〉。遥控器是操控电视的装置，控制权指管理事情的权利，不能指实物装置。"}, {"text": "他的开车控制权很强。", "explanation": "这里应该用〈控制力〉。控制力指操控的能力，控制权指管理事情的权利，不能说“控制权很强”。"}, {"text": "这把剪刀的控制权很好，剪纸很顺手。", "explanation": "这里应该用〈手感〉。手感是握在手里操作时的感觉，控制权指管理事情的权利，不能用来说剪刀用起来顺不顺手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控制权", "is_correct": true, "explanation": "正确。“老板老了，把控制权交给女儿”表示把管理权转交给女儿。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不能交给别人，与“老板老了”的交接语境不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能用“交给”来转让，句子无法成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或动物，不能说“把体重交给女儿”。"}], "explanations": {"控制权": "正确。“老板老了，把控制权交给女儿”表示把管理权转交给女儿。", "天空": "语义：“天空”不能交给别人，与“老板老了”的交接语境不符。", "颜色": "语义：“颜色”不能用“交给”来转让，句子无法成立。", "体重": "搭配：“体重”只用于人或动物，不能说“把体重交给女儿”。"}, "sentence_index": 6, "correct_answer": "控制权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子长大了，想要承担自己生活的控制权。", "explanation": "这里应该用〈责任〉。承担的是责任，“控制权”指管理事情的权利，不能说“承担控制权”。"}, {"text": "他的画画控制权很强，作品很多。", "explanation": "这里应该用〈能力〉。画画能力指技能，控制权指管理事情的权利，不能用来形容画画的本事。"}, {"text": "这件衣服的控制权很漂亮。", "explanation": "这里应该用〈颜色〉。说衣服好不好看要用颜色等外观，控制权指管理事情的权利，不能用“漂亮”形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这家店的一件控制权交给了朋友。", "corrected_sentence": "他把这家店的一项控制权交给了朋友。", "error_description": "错误：“一件控制权”；正确：“一项控制权”。“控制权”是抽象的权利，量词应用“项”，“件”用于具体的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板终于被公司的控制权交给了儿子。", "corrected_sentence": "老板终于把公司的控制权交给了儿子。", "error_description": "错误：“被公司的控制权交给”；正确：“把公司的控制权交给”。老板是主动交出控制权的人，应该用“把”字句，不能用“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
