INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27620, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "喜欢这个，不喜欢那个。", "primary_collocate": null, "pronunciation": "piān hào", "ipa": "pʰjɛn˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我偏好喝茶，不太喝咖啡。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他偏好安静的地方。", "target_word": "偏好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹偏好甜的东西。", "target_word": "偏好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多年轻人偏好网上购物。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她偏好穿浅色的衣服。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸偏好看新闻，不爱看电视剧。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我偏好早上学习。", "target_word": "偏好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板偏好简单的办法。", "target_word": "偏好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他偏好坐在窗边。", "target_word": "偏好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们都偏好住在小城市。", "target_word": "偏好", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "更喜欢某一个，不太喜欢另一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27620, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏好", "is_correct": true, "explanation": "正确。“偏好喝茶，不太喝咖啡”表示更喜欢某一个，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所、展览等，不能与“喝茶”搭配作谓语。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是器物，不能说“修理喝茶”，与句意不符。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”的对象是语言或文字，不能用来表达喝茶的习惯。"}], "explanations": {"偏好": "正确。“偏好喝茶，不太喝咖啡”表示更喜欢某一个，符合句意。", "参观": "搭配：“参观”的对象是场所、展览等，不能与“喝茶”搭配作谓语。", "修理": "语义：“修理”的对象是器物，不能说“修理喝茶”，与句意不符。", "翻译": "语义：“翻译”的对象是语言或文字，不能用来表达喝茶的习惯。"}, "sentence_index": 0, "correct_answer": "偏好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的偏好是三千元。", "explanation": "这里应该用〈价格〉。说商品的价钱要用价格，偏好指对事物的倾向，不能用来表示金额。"}, {"text": "这碗面的偏好是两百克。", "explanation": "这里应该用〈分量〉。说食物的重量要用分量，偏好指对事物的倾向，不能用来表示重量。"}, {"text": "这本书的偏好有三百页。", "explanation": "这里应该用〈页数〉。说书有多少页要用页数，偏好指对事物的倾向，不能用来表示数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27620, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏好", "is_correct": true, "explanation": "正确。“我偏好早上学习”表示更喜欢在早上学习，符合句意。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”是迁移住所的行为，不能表示更喜欢在早上学习，与句意不符。"}, {"text": "洗车", "is_correct": false, "explanation": "语义：“洗车”指清洗车辆，与“早上学习”的安排没有关系。"}, {"text": "种树", "is_correct": false, "explanation": "语义：“种树”是种植活动，不能表示学习时间的倾向，与句意不符。"}], "explanations": {"偏好": "正确。“我偏好早上学习”表示更喜欢在早上学习，符合句意。", "搬家": "语义：“搬家”是迁移住所的行为，不能表示更喜欢在早上学习，与句意不符。", "洗车": "语义：“洗车”指清洗车辆，与“早上学习”的安排没有关系。", "种树": "语义：“种树”是种植活动，不能表示学习时间的倾向，与句意不符。"}, "sentence_index": 6, "correct_answer": "偏好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的偏好是两百块。", "explanation": "这里应该用〈价格〉。说商品的价钱要用价格，偏好指对事物的倾向，不能用来表示金额。"}, {"text": "这间房的偏好是二十平方米。", "explanation": "这里应该用〈面积〉。说房间有多大要用面积，偏好指对事物的倾向，不能用来表示大小。"}, {"text": "这座桥的偏好是一公里。", "explanation": "这里应该用〈长度〉。说桥有多长要用长度，偏好指对事物的倾向，不能用来表示长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27620, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人偏好对清淡的饭菜。", "corrected_sentence": "老人偏好清淡的饭菜。", "error_description": "介词误加：偏好是及物动词，直接带宾语，不能在“偏好”后面加“对”，应说“偏好清淡的饭菜”；“对……有偏好”是另一种结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27620, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他偏好了清淡的饮食。", "corrected_sentence": "他偏好清淡的饮食。", "error_description": "时态助词误加：偏好表示长期稳定的倾向，是状态动词，不能带“了”；应说“他偏好清淡的饮食”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
