INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数学中的函数：一种规则，每放进一个数，就对应得到另一个数。", "primary_collocate": null, "pronunciation": "hán shù", "ipa": "xan˧˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "函数像一个盒子，放进去一个数，就出来另一个数。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数把每个数都加上五。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放进二，这个函数会给你四。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，函数就是一种规则。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小红画了一个函数的图。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个函数的输入是年龄。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个输入只能对应一个输出，这才是函数。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得函数就像一个魔法盒子。", "target_word": "函数", "complexity_tier": "T3", "furigana": "wǒ jué de hán shù jiù xiàng yí gè mó fǎ hé zi.", "sentence_source": "generated"}, {"text": "我用这个函数算出了答案。", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪一个图表示函数？", "target_word": "函数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次函数", "label": "复合"}, {"form": "函數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "函数：像魔法盒子，放进一个数就变出另一个数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27624, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：函数（hán shù）指一种规则，放进一个数，就得到另一个数。"}, {"text": "行数", "is_correct": false, "explanation": "háng（第二声）与 hán（第二声）声母相同，韵母 ang 与 an 不同，意思是行的数目，不是函数。"}, {"text": "韩式", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是韩国式的，不是函数。"}, {"text": "含税", "is_correct": false, "explanation": "shuì（第四声）与 shù（第四声）韵母不同，意思是包含税款，不是函数。"}, {"text": "寒暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是寒冷与炎热，不是函数。"}], "explanations": {"函数": "正确：函数（hán shù）指一种规则，放进一个数，就得到另一个数。", "行数": "háng（第二声）与 hán（第二声）声母相同，韵母 ang 与 an 不同，意思是行的数目，不是函数。", "韩式": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是韩国式的，不是函数。", "含税": "shuì（第四声）与 shù（第四声）韵母不同，意思是包含税款，不是函数。", "寒暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是寒冷与炎热，不是函数。"}, "sentence_index": null, "correct_answer": "函数"}, "level_3": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：函数像一个盒子，放进一个数，就出来另一个数，符合语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎不是可以放进一个数、再变出另一个数的装置，比喻不成立。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲没有“放进一个数就变出另一个数”的功能，句子不通。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语，不适合用来比喻数学概念。"}], "explanations": {"函数": "正确：函数像一个盒子，放进一个数，就出来另一个数，符合语境。", "老虎": "语义：老虎不是可以放进一个数、再变出另一个数的装置，比喻不成立。", "歌曲": "语义：歌曲没有“放进一个数就变出另一个数”的功能，句子不通。", "哥们": "语域：“哥们”是口语，不适合用来比喻数学概念。"}, "sentence_index": 0, "correct_answer": "函数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜的函数很大。", "explanation": "这里应该用〈个头〉。函数是数学概念，不能用来说水果的大小。"}, {"text": "他的函数有一米八。", "explanation": "这里应该用〈身高〉。函数不能用来说人的高矮。"}, {"text": "今天我的函数很好。", "explanation": "这里应该用〈心情〉。函数是数学概念，不能用来说人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "函数", "is_correct": true, "explanation": "正确：这句说的是函数的定义，句末应当落在“函数”上。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“这才是游戏”与前面关于输入和输出的定义毫无关系，句子不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜与“一个输入只能对应一个输出”的定义无关，句子不通。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土与“输入对应输出”的定义无关，句子不通。"}], "explanations": {"函数": "正确：这句说的是函数的定义，句末应当落在“函数”上。", "游戏": "语义：“这才是游戏”与前面关于输入和输出的定义毫无关系，句子不通。", "蔬菜": "语义：蔬菜与“一个输入只能对应一个输出”的定义无关，句子不通。", "泥土": "语义：泥土与“输入对应输出”的定义无关，句子不通。"}, "sentence_index": 6, "correct_answer": "函数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "期末函数很理想。", "explanation": "这里应该用〈成绩〉。函数是数学概念，不能用来说考试的分数。"}, {"text": "这次函数很严重。", "explanation": "这里应该用〈感冒〉。函数不能用来说疾病的轻重。"}, {"text": "这道菜的函数很好。", "explanation": "这里应该用〈味道〉。函数不能用来评价菜的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天学了一条函数。", "corrected_sentence": "我今天学了一个函数。", "error_description": "量词错误：“函数”应用量词“个”；“条”多用于细长的东西，不能用于函数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在坐标纸上画出了函数了图像。", "corrected_sentence": "同学们在坐标纸上画出了函数图像。", "error_description": "体标误用：「了」只能加在动词后表示完成，不能插在「函数」与「图像」之间。应说「画出了函数图像」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
