INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得有规律、有条理。", "primary_collocate": null, "pronunciation": "jié gòu huà", "ipa": "tɕjɛ˧˥ kou˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "学习前，先把知识结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一周的计划结构化，每天都有安排。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结构化以后，复习轻松多了。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，笔记要结构化，不能乱写。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把杂乱的想法结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把任务结构化，工作就不会乱了。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份合同条款很多，他先把它结构化，再逐条研究。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些资料太乱，需要先结构化。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把书本内容结构化成了一张图。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想法结构化之后，说话更有条理。", "target_word": "结构化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "结构化了", "label": "完成体"}, {"form": "结构化过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "让东西变得有规律、有条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79065f31-2ba5-42e7-956e-ce5a49842aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结构化", "is_correct": true, "explanation": "正确：结构化指使知识有条理，符合“先把知识……”的用法。"}, {"text": "冰镇", "is_correct": false, "explanation": "语义：冰镇指降温，知识不能被冰镇。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：缝补用于布料，不说缝补知识。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干指去除水分，与使知识有条理无关。"}], "explanations": {"结构化": "正确：结构化指使知识有条理，符合“先把知识……”的用法。", "冰镇": "语义：冰镇指降温，知识不能被冰镇。", "缝补": "搭配：缝补用于布料，不说缝补知识。", "烘干": "语义：烘干指去除水分，与使知识有条理无关。"}, "sentence_index": 0, "correct_answer": "结构化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黑板脏了，要结构化干净。", "explanation": "这里应该用〈擦〉。结构化指使事物有条理，不用于清洁表面。"}, {"text": "妈妈把衣服结构化成了红色。", "explanation": "这里应该用〈染〉。结构化不指给物品上色，衣服变成红色要用染。"}, {"text": "裁缝把布结构化成了一块块。", "explanation": "这里应该用〈剪〉。结构化不指切割，布剪成一块块要用剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结构化", "is_correct": true, "explanation": "正确：结构化指使条款有条理，符合“先把它……”的用法。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指低温保存，与让条款有条理的意思不符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸指用高温烧开液体，与让条款有条理的意思无关，句意荒谬。"}, {"text": "染色", "is_correct": false, "explanation": "语义：染色指给物体上色，与让条款有条理的意思无关，句意荒谬。"}], "explanations": {"结构化": "正确：结构化指使条款有条理，符合“先把它……”的用法。", "冷冻": "语义：冷冻指低温保存，与让条款有条理的意思不符。", "煮沸": "语义：煮沸指用高温烧开液体，与让条款有条理的意思无关，句意荒谬。", "染色": "语义：染色指给物体上色，与让条款有条理的意思无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "结构化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "设计师把房间结构化成了花园。", "explanation": "这里应该用〈装饰〉。结构化不指美化空间，房间变成花园要用装饰。"}, {"text": "孩子用泥巴结构化成了小人。", "explanation": "这里应该用〈捏〉。结构化不指用手塑形，泥巴做成小人要用捏。"}, {"text": "厨师把鸡蛋结构化成了饼。", "explanation": "这里应该用〈煎〉。结构化不指烹饪加热，鸡蛋做成饼要用煎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些想法很乱，我们先它结构化了，再讨论。", "corrected_sentence": "这些想法很乱，我们先把它结构化了，再讨论。", "error_description": "错误：漏掉了“把”。“它”是被处置的对象，结构化它需要用“把”字句，应说“先把它结构化了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些资料昨天已经结构化着了。", "corrected_sentence": "这些资料昨天已经结构化了。", "error_description": "体标错误：“已经”表示动作完成，应用“了”，不能用表示持续的“着”，应说“已经结构化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88edf621-0fbe-434f-9a87-490831766f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
