INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用东西或做事的人。", "primary_collocate": null, "pronunciation": "shǐ yòng zhě", "ipa": "ʂɻ̩˨˩ jʊŋ˥˩ ʈʂɤ˨˩", "syllable_count": 3, "sentences": [{"text": "这支笔的使用者是我哥哥。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共自行车的使用者要先交钱。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的使用者请关灯。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑的使用者要爱护它。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这台车的第一个使用者。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用者越多，这个地方越热闹。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工具的使用者要先学会安全使用。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用者可以选择不同的颜色。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的使用者请看这里。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "使用者要在门口写下自己的名字。", "target_word": "使用者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用某样东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83dd7b11-4fd5-4148-b4dd-c5c3bc797d29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "使用者", "is_correct": true, "explanation": "正确：“使用者”指用这支笔的人，与句意相符。"}, {"text": "读者", "is_correct": false, "explanation": "语义：笔不是书，没有“读者”；“读者”指阅读书报的人。"}, {"text": "听众", "is_correct": false, "explanation": "搭配：“听众”指听讲话、听演出的人，不与“笔”搭配。"}, {"text": "观众", "is_correct": false, "explanation": "语义：“观众”指观看演出或比赛的人，与“笔”无关。"}], "explanations": {"使用者": "正确：“使用者”指用这支笔的人，与句意相符。", "读者": "语义：笔不是书，没有“读者”；“读者”指阅读书报的人。", "听众": "搭配：“听众”指听讲话、听演出的人，不与“笔”搭配。", "观众": "语义：“观众”指观看演出或比赛的人，与“笔”无关。"}, "sentence_index": 0, "correct_answer": "使用者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店里有很多使用者在洗碗。", "explanation": "这里应该用〈员工〉。“使用者”指使用某物或做事的人，在饭店工作的人要说“员工”。"}, {"text": "这场讲座有很多使用者。", "explanation": "这里应该用〈听众〉。“使用者”指使用某物的人，听讲座的人要说“听众”。"}, {"text": "这家医院里有很多使用者在偷东西。", "explanation": "这里应该用〈小偷〉。“使用者”指使用某物或做事的人，偷东西的人要说“小偷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "使用者", "is_correct": true, "explanation": "正确：“使用者”指使用工具、需要学会安全使用的人，与句意相符。"}, {"text": "观赏者", "is_correct": false, "explanation": "语义：“观赏者”指欣赏事物的人，与“学会安全使用”不符。"}, {"text": "旁观者", "is_correct": false, "explanation": "搭配：“旁观者”多用于事件，“工具的旁观者”搭配不当。"}, {"text": "旅游者", "is_correct": false, "explanation": "语义：“旅游者”指出游观光的人，与“工具”无关。"}], "explanations": {"使用者": "正确：“使用者”指使用工具、需要学会安全使用的人，与句意相符。", "观赏者": "语义：“观赏者”指欣赏事物的人，与“学会安全使用”不符。", "旁观者": "搭配：“旁观者”多用于事件，“工具的旁观者”搭配不当。", "旅游者": "语义：“旅游者”指出游观光的人，与“工具”无关。"}, "sentence_index": 6, "correct_answer": "使用者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的使用者是谁？", "explanation": "这里应该用〈作者〉。“使用者”指使用某物的人，写文章的人要说“作者”。"}, {"text": "这位教练的使用者很有经验。", "explanation": "这里应该用〈学员〉。“使用者”指使用某物的人，接受教练指导的人要说“学员”。"}, {"text": "这位歌星的使用者很多。", "explanation": "这里应该用〈歌迷〉。“使用者”指使用某物的人，喜爱歌星的人要说“歌迷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间教室有三间使用者。", "corrected_sentence": "这间教室有三位使用者。", "error_description": "错误在量词：“间”应改为“位”。“间”用于房间，“使用者”指人，应用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每只使用者都要签字确认。", "corrected_sentence": "每位使用者都要签字确认。", "error_description": "错误在量词：“只”应改为“位”。“只”多用于动物或小件物品，“使用者”指人，应用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470457ff-8ca5-4931-bee1-68929096080a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慢", "is_correct": true, "explanation": "“慢”与“快”构成反义，都指速度的高低。"}, {"text": "大", "is_correct": false, "explanation": "“大”与“快”不构成反义，说的是体积或程度。"}, {"text": "远", "is_correct": false, "explanation": "“远”说距离，与速度的高低不构成反义。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说声音或环境，与速度不构成反义。"}], "correct_answer": "慢", "explanations": {"慢": "“慢”与“快”构成反义，都指速度的高低。", "大": "“大”与“快”不构成反义，说的是体积或程度。", "远": "“远”说距离，与速度的高低不构成反义。", "安静": "“安静”说声音或环境，与速度不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "慢", "is_correct": true, "explanation": "“慢”与“快”构成反义，都指速度的高低。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”说坚实的程度，与速度不构成反义。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”说重量，与速度不构成反义。"}, {"text": "暗", "is_correct": false, "explanation": "“暗”说光线，与速度不构成反义。"}], "correct_answer": "慢", "explanations": {"慢": "“慢”与“快”构成反义，都指速度的高低。", "硬": "“硬”说坚实的程度，与速度不构成反义。", "轻": "“轻”说重量，与速度不构成反义。", "暗": "“暗”说光线，与速度不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示速度高，做事情用的时间少。", "primary_collocate": null, "pronunciation": "kuài", "ipa": "kʰuaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "他跑得很快。", "target_word": "快", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这辆车开得真快。", "target_word": "快", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟吃饭很快，五分钟就吃完了。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵车，地铁比公共汽车快多了。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说得太快了，我没听清楚。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网速很快，电影一会儿就下载好了。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写字很快，一节课写了三页。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时间过得真快，一年又过去了。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机比火车快得多，所以我坐飞机去。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请走快一点，我们要迟到了。", "target_word": "快", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "快快", "label": "重叠"}, {"form": "快速", "label": "复合"}], "register": "中性", "sense_fingerprint": "速度高、用时少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb662756-0b78-4edf-9c5e-051c04c57dff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "快", "is_correct": true, "explanation": "正确答案。快（kuài）表示速度高，做事用的时间少。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 kuài 只差声母（h 与 k），意思是不好。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 kuài 只差声母（g 与 k），意思是奇怪。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 kuài 只差声母（sh 与 k），意思是好看。"}], "explanations": {"快": "正确答案。快（kuài）表示速度高，做事用的时间少。", "坏": "huài 与 kuài 只差声母（h 与 k），意思是不好。", "怪": "guài 与 kuài 只差声母（g 与 k），意思是奇怪。", "帅": "shuài 与 kuài 只差声母（sh 与 k），意思是好看。"}, "sentence_index": null, "correct_answer": "快"}, "level_3": {"options": [{"text": "快", "is_correct": true, "explanation": "正确答案。“快”指跑的速度高，与“跑得很”搭配。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”说身高或身材，不能描述跑步的速度。"}, {"text": "大", "is_correct": false, "explanation": "语义：“大”说体积或程度，不能说跑的快慢。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“跑得很深”不成立，“深”不能描述动作的速度。"}], "explanations": {"快": "正确答案。“快”指跑的速度高，与“跑得很”搭配。", "高": "体貌：“高”说身高或身材，不能描述跑步的速度。", "大": "语义：“大”说体积或程度，不能说跑的快慢。", "深": "搭配：“跑得很深”不成立，“深”不能描述动作的速度。"}, "sentence_index": 0, "correct_answer": "快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座楼很快，站在楼下都看不到顶。", "explanation": "这里应该用〈高〉。“快”表示速度高，不能用来形容楼房的高矮。"}, {"text": "他的身体很快，每天都能跑十公里。", "explanation": "这里应该用〈强壮〉。“快”表示速度高，不能用来形容人的体格强弱。"}, {"text": "这件大衣很快，我买的时候花了不少钱。", "explanation": "这里应该用〈贵〉。“快”表示速度高，不能用来形容价格的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "快", "is_correct": true, "explanation": "正确答案。快（kuài）表示速度高，做事用的时间少。"}, {"text": "跨", "is_correct": false, "explanation": "kuà（第四声）与 kuài 韵母不同（a 与 ai），意思是跨越。"}, {"text": "外", "is_correct": false, "explanation": "wài 与 kuài 只差声母，意思是外面。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 kuài 只差声母（g 与 k），意思是奇怪。"}], "explanations": {"快": "正确答案。快（kuài）表示速度高，做事用的时间少。", "跨": "kuà（第四声）与 kuài 韵母不同（a 与 ai），意思是跨越。", "外": "wài 与 kuài 只差声母，意思是外面。", "怪": "guài 与 kuài 只差声母（g 与 k），意思是奇怪。"}, "sentence_index": null, "correct_answer": "快"}, "level_3": {"options": [{"text": "快", "is_correct": true, "explanation": "正确答案。“快”指写字的速度高，与“一节课写了三页”相符。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”说温度，不能用来形容写字的速度。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价钱高，“写字很贵”不成立。"}, {"text": "厚", "is_correct": false, "explanation": "体貌：“厚”说物体的厚度，不能形容写字的快慢。"}], "explanations": {"快": "正确答案。“快”指写字的速度高，与“一节课写了三页”相符。", "烫": "搭配：“烫”说温度，不能用来形容写字的速度。", "贵": "语义：“贵”说价钱高，“写字很贵”不成立。", "厚": "体貌：“厚”说物体的厚度，不能形容写字的快慢。"}, "sentence_index": 6, "correct_answer": "快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天很快，心情特别好。", "explanation": "这里应该用〈开心〉。“快”表示速度高，不能单独用来说心情愉快。"}, {"text": "这条快公路下个月就通车了。", "explanation": "这里应该用〈高速〉。“快”不修饰“公路”这类道路，说车速高要用“高速”。"}, {"text": "这个快房间很宽敞，窗户也很大。", "explanation": "“快”表示速度高，只能修饰动作、过程或速度相关的事物，不能修饰“房间”这类静止的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐游地很快，拿到了第一名。", "corrected_sentence": "姐姐游得很快，拿到了第一名。", "error_description": "补语标记错误：动词后表示程度或结果的补语须用结构助词“得”，“地”用于动词前作状语，应说“游得很快”，不能说“游地很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近走路比以前了快。", "corrected_sentence": "他最近走路比以前快了。", "error_description": "了的位置错误：“快了”表示变化，“了”应放在“快”之后，不能放在“快”之前，正确为“比以前快了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02ba7baf-aaec-45a2-9742-dd8089de9ec9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
