INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "休息时间就是可以停下来玩或睡觉的时间。", "primary_collocate": null, "pronunciation": "xiū xi shí jiān", "ipa": "ɕjoʊ˥ ɕi˧ ʂɻ̩˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "休息时间，孩子们在操场上玩。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的休息时间到了，它趴着睡觉。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后有十分钟休息时间。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我的休息时间，我想睡一会儿。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息时间，我们可以玩游戏。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫一天有很多休息时间，常常睡觉。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说休息时间不要看手机。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息时间过了，我们要回教室。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的休息时间是几点到几点？", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午饭后有一段休息时间，我睡了一会儿。", "target_word": "休息时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段休息时间", "label": "量词"}, {"form": "休息時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "休息时间:可以停下来玩或睡觉的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e27744d-182f-47c3-87f2-2fd95c884f94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "休息时间", "is_correct": true, "explanation": "正确：“休息时间”作句首的时间状语，指可以停下来玩的时间，与“在操场上玩”相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不是可以玩耍的时段，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：句首的时间状语要用时间词，“书包”不能这样作时间状语。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是读书的地方，与“在操场上玩”的场景冲突。"}], "explanations": {"休息时间": "正确：“休息时间”作句首的时间状语，指可以停下来玩的时间，与“在操场上玩”相符。", "数学": "语义：数学是学科，不是可以玩耍的时段，句意不通。", "书包": "搭配：句首的时间状语要用时间词，“书包”不能这样作时间状语。", "图书馆": "语义：图书馆是读书的地方，与“在操场上玩”的场景冲突。"}, "sentence_index": 0, "correct_answer": "休息时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班每天下午有一条休息时间，我们可以玩。", "explanation": "这里应该用〈段〉。“休息时间”指一段时间，量词不能用“条”。"}, {"text": "这间卧室是我的休息时间，我想睡一会儿。", "explanation": "“休息时间”指时段，卧室是地方，不能这样说。"}, {"text": "他是我的休息时间，我想睡一会儿。", "explanation": "“休息时间”指时段，人不能被称作时间，这里误用了这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "休息时间", "is_correct": true, "explanation": "正确：“休息时间”在妈妈说的话里作时间状语，指可以停下来玩或睡觉的时间，“休息时间不要看手机”句意通顺。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：袜子不能看手机，句子说的是人的行为，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能看手机，句子说的是人的行为，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头没有眼睛和屏幕，不能看手机。"}], "explanations": {"休息时间": "正确：“休息时间”在妈妈说的话里作时间状语，指可以停下来玩或睡觉的时间，“休息时间不要看手机”句意通顺。", "袜子": "语义：袜子不能看手机，句子说的是人的行为，句意不通。", "雨伞": "语义：雨伞不能看手机，句子说的是人的行为，句意不通。", "石头": "体貌：石头没有眼睛和屏幕，不能看手机。"}, "sentence_index": 6, "correct_answer": "休息时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱是我午饭后的休息时间，我很喜欢它。", "explanation": "“休息时间”指时段，冰箱是物品，不能这样指代它。"}, {"text": "这辆汽车是我午饭后的休息时间，我开它去公园。", "explanation": "“休息时间”指时段，汽车是交通工具，这里误用了这个词。"}, {"text": "这条河流是我午饭后的休息时间，我在河边散步。", "explanation": "“休息时间”指时段，河流是自然地理事物，不能这样称呼它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下午的课间有一本休息时间，我们可以玩。", "corrected_sentence": "下午的课间有一段休息时间，我们可以玩。", "error_description": "量词错误：“本”用于书籍等，不能用于时间段；表示一段时间应用“段”。正确说法是“下午的课间有一段休息时间，我们可以玩。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校每天有一小时地休息时间。", "corrected_sentence": "我们学校每天有一小时的休息时间。", "error_description": "助词错误：修饰名词“休息时间”的定语应用“的”，不能用“地”。正确说法是“我们学校每天有一小时的休息时间。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ca0217-3edd-42bd-960a-febe13752150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
