INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不要的东西拿掉。", "primary_collocate": null, "pronunciation": "pái chú", "ipa": "pʰaɪ˧˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "工人正在排除地下室的积水。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅很快排除了汽车的故障。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手术排除了肚子里的异物。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器会自动排除废气。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗户，可以排除房间里的湿气。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先排除管道里的空气。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药能帮你排除体内的毒素。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员排除了路上的障碍物。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泵很快排除了田里的积水。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着工具排除了水管里的堵塞。", "target_word": "排除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排除了", "label": "体标"}, {"form": "排除着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把积水、故障、障碍物等不要的东西除掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acfc61dd-6a36-42c2-919d-a796ba291367') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除（pái chú）是本词，意思是把不要的东西拿掉。"}, {"text": "摆出", "is_correct": false, "explanation": "摆出（bǎi chū）与排除（pái chú）声母、声调都相近但不同，意思是把东西摆放出来。"}, {"text": "派出", "is_correct": false, "explanation": "派出（pài chū）与排除（pái chú）声调不同，意思是派遣。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出（pāi chū）与排除（pái chú）声调不同，意思是拍卖得到，如拍出高价。"}], "explanations": {"排除": "排除（pái chú）是本词，意思是把不要的东西拿掉。", "摆出": "摆出（bǎi chū）与排除（pái chú）声母、声调都相近但不同，意思是把东西摆放出来。", "派出": "派出（pài chū）与排除（pái chú）声调不同，意思是派遣。", "拍出": "拍出（pāi chū）与排除（pái chú）声调不同，意思是拍卖得到，如拍出高价。"}, "sentence_index": null, "correct_answer": "排除"}, "level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除：积水被除去，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象不能是积水，这句话语义不通。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”的对象是东西、技术，不能说发明积水。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”针对场所、展览，不能用于积水。"}], "explanations": {"排除": "排除：积水被除去，符合句意。", "欣赏": "语义：“欣赏”的对象不能是积水，这句话语义不通。", "发明": "搭配：“发明”的对象是东西、技术，不能说发明积水。", "参观": "搭配：“参观”针对场所、展览，不能用于积水。"}, "sentence_index": 0, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花园里的植物排除了充足的阳光。", "explanation": "这里应该用〈吸收〉。排除表示把不要的东西去掉，植物需要的阳光要说吸收。"}, {"text": "大家排除了新同学的到来。", "explanation": "这里应该用〈欢迎〉。排除表示去掉不要的东西，对来人的态度要说欢迎。"}, {"text": "妈妈排除了哭泣的孩子。", "explanation": "这里应该用〈拥抱〉。排除是去掉东西，不能用于对孩子的亲昵动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排除", "is_correct": true, "explanation": "排除：毒素被去掉，符合句意。"}, {"text": "制造", "is_correct": false, "explanation": "语义：药物不会制造毒素，这句话与“帮你”的意思相反。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”的对象是身体、健康，不能说保护毒素。"}, {"text": "迎接", "is_correct": false, "explanation": "语义：“迎接”的对象不能是毒素，这句话语义不通。"}], "explanations": {"排除": "排除：毒素被去掉，符合句意。", "制造": "语义：药物不会制造毒素，这句话与“帮你”的意思相反。", "保护": "搭配：“保护”的对象是身体、健康，不能说保护毒素。", "迎接": "语义：“迎接”的对象不能是毒素，这句话语义不通。"}, "sentence_index": 6, "correct_answer": "排除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他排除了老师的鼓励，继续努力。", "explanation": "这里应该用〈接受〉。排除表示去掉障碍或不要的东西，老师的鼓励是应当接受的，不能说排除。"}, {"text": "妈妈排除了孩子的笑容。", "explanation": "这里应该用〈欣赏〉。排除表示去掉障碍或不要的东西，笑容不是要去掉的东西，应说欣赏。"}, {"text": "我排除了那份友情，继续向前走。", "explanation": "这里应该用〈放下〉。排除表示去掉障碍或不要的东西，友情不是要去掉的东西，应说放下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人屋里的积水排除了。", "corrected_sentence": "工人把屋里的积水排除了。", "error_description": "漏掉“把”：“把”字句中“把”引出受处置的宾语，此处缺少“把”，“工人屋里的积水”连成一个名词短语，句子结构断裂；应为“工人把屋里的积水排除了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把地面的积水排除很干净。", "corrected_sentence": "工人把地面的积水排除得很干净。", "error_description": "表示程度要用“得”，应说“排除得很干净”；“排除很干净”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef947ae9-1856-42e1-a9dc-1717b60f8334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
