INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "从一个国家到另一个国家。", "primary_collocate": null, "pronunciation": "kuà guó", "ipa": "kʰua˥˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他在一家跨国公司工作。", "target_word": "跨国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是一次跨国旅行。", "target_word": "跨国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸爸常常做跨国生意。", "target_word": "跨国", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "跨国公司在很多国家都有办公室。", "target_word": "跨国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和一个外国人有一段跨国婚姻。", "target_word": "跨国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跨国电话很贵，所以我们用手机发消息。", "target_word": "跨国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种跨国合作对两个公司都有好处。", "target_word": "跨国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐常常寄跨国快递。", "target_word": "跨国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是跨国夫妻，一个在中国，一个在法国。", "target_word": "跨国", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家跨国公司的老板去过很多地方。", "target_word": "跨国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨国公司", "label": "复合"}, {"form": "跨國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "涉及两个或多个国家的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跨国", "is_correct": true, "explanation": "正确：“一家跨国公司”指在多个国家经营的公司，“跨国”修饰“公司”最自然。"}, {"text": "英俊", "is_correct": false, "explanation": "体貌：“英俊”形容人的相貌，不能修饰公司。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与公司的性质毫无关系。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高度，不能说“矮公司”。"}], "explanations": {"跨国": "正确：“一家跨国公司”指在多个国家经营的公司，“跨国”修饰“公司”最自然。", "英俊": "体貌：“英俊”形容人的相貌，不能修饰公司。", "甜": "语义：“甜”说味道，与公司的性质毫无关系。", "矮": "搭配：“矮”说高度，不能说“矮公司”。"}, "sentence_index": 0, "correct_answer": "跨国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去北京和西安玩了一趟，这次跨国旅行很开心。", "explanation": "这里应该用〈国内〉。跨国指跨越国界，北京和西安都在国内，应说国内旅行。"}, {"text": "我妈妈在厨房里跨国做饭。", "explanation": "这里应该用〈在家〉。“跨国”指跨越国界，在厨房做饭不涉及国界，应说在家做饭。"}, {"text": "我每周坐的是跨国火车，只在本省跑。", "explanation": "这里应该用〈省内〉。跨国指跨越国界，只在本省跑的火车应说省内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跨国", "is_correct": true, "explanation": "正确：“这种跨国合作”指涉及多个国家的合作，与“两个公司”的语境相符。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”说颜色，不能修饰“合作”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不能修饰“合作”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”说形状，与合作的性质毫无关系。"}], "explanations": {"跨国": "正确：“这种跨国合作”指涉及多个国家的合作，与“两个公司”的语境相符。", "红": "语义：“红”说颜色，不能修饰“合作”。", "瘦": "体貌：“瘦”形容人或动物的身材，不能修饰“合作”。", "圆": "语义：“圆”说形状，与合作的性质毫无关系。"}, "sentence_index": 6, "correct_answer": "跨国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的心情很跨国。", "explanation": "这里应该用〈很好〉。“跨国”指跨越国界，形容心情不能用它，应说“我的心情很好”。"}, {"text": "这次跨国的散步，只在小区里转了一圈。", "explanation": "这里应该用〈普通〉。“跨国”指跨越国界，在小区里转一圈不涉及国界，应说“这次普通的散步”。"}, {"text": "我的作业很跨国。", "explanation": "这里应该用〈很认真〉。“跨国”指跨越国界，形容作业要用“很认真”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家很跨国公司在中国有很多员工。", "corrected_sentence": "这家跨国公司在中国有很多员工。", "error_description": "错误在“很”：“跨国”是区别词，表示跨越国界，不能用程度副词“很”修饰，应去掉“很”，说“这家跨国公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一家跨国了公司工作三年。", "corrected_sentence": "他在一家跨国公司工作三年。", "error_description": "错误在“了”的位置：“跨国”修饰“公司”，中间不能加“了”，应说“跨国公司”，“了”不能放在“跨国”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
