INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27656, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物质经分解作用逐渐变成结构更简单的物质。", "primary_collocate": null, "pronunciation": "jiàng jiě", "ipa": "tɕjɑŋ˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "塑料袋在土里很难降解。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子放在土里，半年就能降解。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸比塑料容易降解。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可以降解的袋子对环境好。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物放进土里，会慢慢降解。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新材料三个月就降解了。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾要很多年才能降解。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料瓶在海里降解得很慢。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料能在水里降解，不会留下垃圾。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用能降解的盒子装菜。", "target_word": "降解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降解了", "label": "体标"}, {"form": "降解过", "label": "体标"}, {"form": "可降解", "label": "复合"}, {"form": "生物降解", "label": "复合"}], "register": "中性", "sense_fingerprint": "物质慢慢分解变小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a51fb9fe-8abb-41e1-afcc-9db367ee8af2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "降解", "is_correct": true, "explanation": "正确：降解指物质慢慢分解变小，与听到的词相符。"}, {"text": "讲解", "is_correct": false, "explanation": "讲解与降解只有第一个音节的声调不同（第三声与第四声），意思是讲明道理，不是物质分解。"}, {"text": "见解", "is_correct": false, "explanation": "见解与降解只有第一个音节的韵尾不同（n与ng），声调相同，意思是看法，不是物质分解。"}, {"text": "疆界", "is_correct": false, "explanation": "疆界与降解两个音节的声调都不同，意思是国家或地区的边界。"}], "explanations": {"降解": "正确：降解指物质慢慢分解变小，与听到的词相符。", "讲解": "讲解与降解只有第一个音节的声调不同（第三声与第四声），意思是讲明道理，不是物质分解。", "见解": "见解与降解只有第一个音节的韵尾不同（n与ng），声调相同，意思是看法，不是物质分解。", "疆界": "疆界与降解两个音节的声调都不同，意思是国家或地区的边界。"}, "sentence_index": null, "correct_answer": "降解"}, "level_3": {"options": [{"text": "降解", "is_correct": true, "explanation": "正确：降解指材料在土里慢慢分解，符合“很难”的语境。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：燃烧需要火，塑料袋埋在土里不会燃烧，与句意不符。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长是生物的成长，塑料袋不会生长，与句意不符。"}, {"text": "发酵", "is_correct": false, "explanation": "搭配：发酵多用于面团、食物，不用于塑料袋，搭配不当。"}], "explanations": {"降解": "正确：降解指材料在土里慢慢分解，符合“很难”的语境。", "燃烧": "语义：燃烧需要火，塑料袋埋在土里不会燃烧，与句意不符。", "生长": "语义：生长是生物的成长，塑料袋不会生长，与句意不符。", "发酵": "搭配：发酵多用于面团、食物，不用于塑料袋，搭配不当。"}, "sentence_index": 0, "correct_answer": "降解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糖在水里会降解。", "explanation": "这里应该用〈溶解〉。降解指材料在自然中慢慢分解变小，糖在水中化开要用溶解。"}, {"text": "水通电后会降解成氢气和氧气。", "explanation": "这里应该用〈分解〉。降解指材料被微生物等慢慢分解，水被电分解成气体要用分解。"}, {"text": "他的成绩在暑假里降解了不少。", "explanation": "这里应该用〈下降〉。降解指物质逐渐分解变简单，成绩变差应说下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27656, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降解", "is_correct": true, "explanation": "正确：降解指材料慢慢分解变小，符合“要很多年才能”的语境。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体受热变成液体，与垃圾慢慢分解的意思不符。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽指种子长出芽，垃圾不会发芽，与句意不符。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：装修指装饰房屋，不用于垃圾，搭配不当。"}], "explanations": {"降解": "正确：降解指材料慢慢分解变小，符合“要很多年才能”的语境。", "融化": "语义：融化指固体受热变成液体，与垃圾慢慢分解的意思不符。", "发芽": "语义：发芽指种子长出芽，垃圾不会发芽，与句意不符。", "装修": "搭配：装修指装饰房屋，不用于垃圾，搭配不当。"}, "sentence_index": 6, "correct_answer": "降解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个玻璃杯摔了一下，降解成了几块。", "explanation": "这里应该用〈摔碎〉。降解指物质逐渐分解，东西突然被摔碎要说摔碎。"}, {"text": "冰在太阳下会降解。", "explanation": "这里应该用〈融化〉。降解不用于固体受热变成液体，冰化成水要用融化。"}, {"text": "这块铁在潮湿的空气里会降解。", "explanation": "这里应该用〈生锈〉。降解指物质逐渐分解，金属在潮湿空气中被氧化要说生锈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种纸盒在土里降解了得很快。", "corrected_sentence": "这种纸盒在土里降解得很快。", "error_description": "“得”引出的补语前不能插“了”。误在“降解”与“得”之间加“了”，应为“降解得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种纸袋能土里降解。", "corrected_sentence": "这种纸袋能在土里降解。", "error_description": "介词漏用：表示地点的“土里”作状语，前面需加介词“在”，应说“能在土里降解”，不能直接接在助动词“能”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20e5954d-e01f-4bcd-a537-20930de46b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
