INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27660, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很小的、零碎的。", "primary_collocate": null, "pronunciation": "xì suì", "ipa": "ɕi˥˩ sueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "细碎的雪花落在她的头发上。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把饼干捏成细碎的渣放进碗里。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢走着，脚步很细碎。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子掉在地上，摔得满地都是细碎的玻璃。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上散着细碎的纸屑。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有细碎的切菜声。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面上泛着细碎的波光。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把肉切得再细碎一点儿。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细碎的沙子钻进了我的鞋里。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一些细碎的面包屑。", "target_word": "细碎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "細碎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很小很零碎的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ddda3849-c2ef-4d42-b931-c11a2d196bc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27660, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "细碎", "is_correct": true, "explanation": "细碎：修饰“雪花”，说明雪花细小零碎，符合句意。"}, {"text": "笔直", "is_correct": false, "explanation": "搭配：“笔直”多用于线条、道路，不能用来形容雪花。"}, {"text": "愤怒", "is_correct": false, "explanation": "语义：雪花没有情绪，不会“愤怒”，与句意矛盾。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：雪花松软轻盈，与“坚硬”的特征相反。"}], "explanations": {"细碎": "细碎：修饰“雪花”，说明雪花细小零碎，符合句意。", "笔直": "搭配：“笔直”多用于线条、道路，不能用来形容雪花。", "愤怒": "语义：雪花没有情绪，不会“愤怒”，与句意矛盾。", "坚硬": "语义：雪花松软轻盈，与“坚硬”的特征相反。"}, "sentence_index": 0, "correct_answer": "细碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她绣花的手艺很细碎。", "explanation": "这里应该用〈精细〉。细碎指零散的细小东西，形容手艺精巧要用精细。"}, {"text": "这栋大楼很细碎。", "explanation": "这里应该用〈宏伟〉。细碎指零散的细小东西，形容整栋大楼的气派要用宏伟。"}, {"text": "他的力量很细碎。", "explanation": "这里应该用〈微小〉。细碎指零散的细小东西，形容力量微弱要用微小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27660, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细碎", "is_correct": true, "explanation": "细碎：修饰“波光”，指细小而闪烁的光点，符合句意。"}, {"text": "高亢", "is_correct": false, "explanation": "语义：“高亢”形容声音，不能用来形容光。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”用于形容嗓音，不能用来形容波光。"}, {"text": "粗大", "is_correct": false, "explanation": "语义：“粗大”指体积大、线条粗，与细小闪烁的波光相矛盾。"}], "explanations": {"细碎": "细碎：修饰“波光”，指细小而闪烁的光点，符合句意。", "高亢": "语义：“高亢”形容声音，不能用来形容光。", "沙哑": "搭配：“沙哑”用于形容嗓音，不能用来形容波光。", "粗大": "语义：“粗大”指体积大、线条粗，与细小闪烁的波光相矛盾。"}, "sentence_index": 6, "correct_answer": "细碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件瓷器做得很细碎。", "explanation": "这里应该用〈精致〉。细碎指零散的细小东西，形容工艺精美要用精致。"}, {"text": "草原很细碎。", "explanation": "这里应该用〈辽阔〉。细碎指零散细小的东西，形容草原的广大要用辽阔。"}, {"text": "这块布料的质地很细碎。", "explanation": "这里应该用〈细腻〉。细碎指零散的细小东西，形容质地柔和光滑要用细腻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨点细碎的打在窗上。", "corrected_sentence": "雨点细碎地打在窗上。", "error_description": "错误形式「细碎的打」，正确形式「细碎地打」。修饰动词“打”要用「地」，「的」用于名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面包屑细碎的散落在桌上。", "corrected_sentence": "面包屑细碎地散落在桌上。", "error_description": "错误形式「细碎的散落」，正确形式「细碎地散落」。修饰动词“散落”的状语要用「地」，「的」用于名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da2c3c5e-31d3-4c02-98b7-14f4eaab6627') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
