INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27666, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "买东西的人。", "primary_collocate": null, "pronunciation": "xiāo fèi zhě", "ipa": "ɕiɑʊ˥ feɪ˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "消费者在超市买了很多水果。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的消费者大多是年轻人。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者喜欢便宜又好用的东西。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店要保护消费者的权利。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前，消费者会先看价格。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位消费者对服务不满意。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物的消费者越来越多。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消费者可以把不好的东西退回商店。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多消费者喜欢在周末逛商场。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告想让消费者多买这种饮料。", "target_word": "消费者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "消费者权益", "label": "复合词"}, {"form": "消費者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买东西、使用商品或服务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87aa3fbb-5473-40d6-85f3-a36aa4409ac9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27666, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "消费者", "is_correct": true, "explanation": "消费者指买东西、使用商品的人，可以作「在超市买了很多水果」的主语，正确。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会去超市购物，「石头在超市买了很多水果」说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能作购物的人，与「买了很多水果」不合。"}, {"text": "天气", "is_correct": false, "explanation": "配价：「买」要求有人作施事，「天气」不能作买东西的主语。"}], "explanations": {"消费者": "消费者指买东西、使用商品的人，可以作「在超市买了很多水果」的主语，正确。", "石头": "语义：石头不会去超市购物，「石头在超市买了很多水果」说不通。", "窗户": "语义：窗户是建筑部件，不能作购物的人，与「买了很多水果」不合。", "天气": "配价：「买」要求有人作施事，「天气」不能作买东西的主语。"}, "sentence_index": 0, "correct_answer": "消费者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生每天要擦很多消费者。", "explanation": "这里应该用〈桌子〉。「消费者」指人，不能被「擦」，此处用错了词义。"}, {"text": "他每天开消费者去上班。", "explanation": "这里应该用〈汽车〉。「消费者」指买东西的人，不能被「开」，此处用错了词义。"}, {"text": "工厂里的消费者都很努力。", "explanation": "这里应该用〈工人〉。「消费者」指买东西的人，不指干活的人，此处用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27666, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消费者", "is_correct": true, "explanation": "消费者指买东西的人，作「网上购物的」的中心语，「越来越多」说得通，正确。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不会购物，「网上购物的河流」说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：「体重」描写身体特征，不能指购物的人，「体重越来越多」与句意不合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是进行网上购物的人，句意说不通。"}], "explanations": {"消费者": "消费者指买东西的人，作「网上购物的」的中心语，「越来越多」说得通，正确。", "河流": "语义：河流不会购物，「网上购物的河流」说不通。", "体重": "体貌：「体重」描写身体特征，不能指购物的人，「体重越来越多」与句意不合。", "厨房": "语义：厨房是房间，不是进行网上购物的人，句意说不通。"}, "sentence_index": 6, "correct_answer": "消费者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饮料厂是饮料的消费者，每天生产两万瓶。", "explanation": "这里应该用〈生产者〉。「消费者」指购买、使用东西的人，不能用来指制造饮料的工厂。"}, {"text": "消费者每天在田里种粮食。", "explanation": "这里应该用〈农民〉。「消费者」指买东西的人，不指种地的人，此处用错了词义。"}, {"text": "工人是机器的消费者，负责生产机器。", "explanation": "这里应该用〈生产者〉。「消费者」是购买者，与「负责生产机器」矛盾，应说「生产者」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "超市里来了一只消费者。", "corrected_sentence": "超市里来了一位消费者。", "error_description": "错误：「一只消费者」。正确：「一位消费者」。「只」多用于动物或成对物件中的一个，不用于人；指人可用「位」或「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消费者的可以要求退货。", "corrected_sentence": "消费者可以要求退货。", "error_description": "错误：「消费者的可以」，多出了「的」。正确：「消费者可以」。「的」会把主语变成名词性短语，之后需要中心语，不能直接接能愿动词「可以」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3844d247-4191-47b3-a5ed-85054c04ae73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
