INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出东西来。", "primary_collocate": null, "pronunciation": "chǎn chū", "ipa": "ʈʂʰan˨˩˦ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "这家工厂每天产出一百个杯子。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地每年能产出很多米。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器一小时能产出五十个零件。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司花了很多钱，却没有产出好产品。", "target_word": "产出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场一年能产出一万公斤水果。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片森林每年产出很多木头。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们用三天时间产出了一份好报告。", "target_word": "产出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组产出的作品都很有意思。", "target_word": "产出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们努力工作，想多产出一些产品。", "target_word": "产出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验室每个月都产出新的研究结果。", "target_word": "产出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产出了", "label": "了体"}, {"form": "产出过", "label": "过体"}, {"form": "產出", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：工厂、土地、人等生产或做出产品、成果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产出", "is_correct": true, "explanation": "“这家工厂每天产出一百个杯子”说工厂做出产品，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“一百个杯子”这样的产品作宾语。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”是不及物动词，后面不能直接带宾语“一百个杯子”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指种庄稼、花木，工厂不种杯子。"}], "explanations": {"产出": "“这家工厂每天产出一百个杯子”说工厂做出产品，符合句意。", "唱": "搭配：“唱”不能带“一百个杯子”这样的产品作宾语。", "生长": "配价：“生长”是不及物动词，后面不能直接带宾语“一百个杯子”。", "种植": "语义：“种植”指种庄稼、花木，工厂不种杯子。"}, "sentence_index": 0, "correct_answer": "产出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她去年产出了一个孩子。", "explanation": "这里应该用〈生〉。产出指做出产品或成果，人的出生要用“生”。"}, {"text": "这次比赛我产出了很多钱。", "explanation": "这里应该用〈赚〉。产出指做出东西、成果，挣钱要用“赚”。"}, {"text": "这家工厂昨天产出了一起事故。", "explanation": "这里应该用〈发生〉。产出指做出产品或成果，事故是“发生”的，不能说“产出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产出", "is_correct": true, "explanation": "“用三天时间产出了一份好报告”说做出成果，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能带“一份好报告”。"}, {"text": "生病", "is_correct": false, "explanation": "配价：“生病”是不及物动词，后面不能带宾语“一份好报告”。"}, {"text": "哭", "is_correct": false, "explanation": "语义：哭不能做出报告，这里不能用。"}], "explanations": {"产出": "“用三天时间产出了一份好报告”说做出成果，符合句意。", "散步": "配价：“散步”是不及物动词，后面不能带“一份好报告”。", "生病": "配价：“生病”是不及物动词，后面不能带宾语“一份好报告”。", "哭": "语义：哭不能做出报告，这里不能用。"}, "sentence_index": 6, "correct_answer": "产出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手产出了很多朋友。", "explanation": "这里应该用〈结交〉。产出指做出东西、成果，朋友要用“结交”。"}, {"text": "这篇论文产出在杂志上。", "explanation": "这里应该用〈发表〉。产出指做出产品、成果，论文在杂志上要用“发表”。"}, {"text": "他每天产出三次饭。", "explanation": "这里应该用〈吃〉。产出指做出东西、成果，吃饭不是“产出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小工厂每天产出得两百个碗。", "corrected_sentence": "这家小工厂每天产出两百个碗。", "error_description": "错误：“产出得两百个碗”，动词“产出”后面多了“得”。正确：“产出两百个碗”，宾语直接放在“产出”后面，不用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们用两天时间产出得一份好报告。", "corrected_sentence": "学生们用两天时间产出了一份好报告。", "error_description": "错误：“产出得”，用错了“得”。正确：“产出了”。表示已经完成的动作要用“了”，不用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
