INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西时需要的东西。", "primary_collocate": null, "pronunciation": "cái liào", "ipa": "tsʰaɪ˧˥ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "做桌子需要木头这种材料。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座房子用的材料很好。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去商店买做蛋糕的材料。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做衣服的材料有布和线。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子的材料是玻璃。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生一些做手工的材料。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饺子的材料我已经准备好了。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖房子的材料太贵了。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种材料很轻，也很结实。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料不够，我们做不完。", "target_word": "材料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原材料", "label": "复合"}, {"form": "建筑材料", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "通用", "sense_fingerprint": "制作东西用的原料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27670, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "材料", "is_correct": true, "explanation": "材料：做东西需要的原料，与木头相符。"}, {"text": "工具", "is_correct": false, "explanation": "语义：木头是做桌子的原料，不是用来做事的工具，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：木头是原料，不是颜色，「这种颜色」说的不是木头。"}, {"text": "顾客", "is_correct": false, "explanation": "语义：木头不是人，不能是顾客。"}], "explanations": {"材料": "材料：做东西需要的原料，与木头相符。", "工具": "语义：木头是做桌子的原料，不是用来做事的工具，句意不通。", "颜色": "语义：木头是原料，不是颜色，「这种颜色」说的不是木头。", "顾客": "语义：木头不是人，不能是顾客。"}, "sentence_index": 0, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的材料今天来我家吃饭。", "explanation": "这里用错了：「材料」指做东西用的原料，不指人，不能来家里吃饭；这里应说「朋友」。"}, {"text": "我想喝一杯材料，解解渴。", "explanation": "这里用错了：「材料」指做东西用的原料，不指「饮料」，不能说「喝一杯材料」。"}, {"text": "他的材料很高，篮球打得很好。", "explanation": "这里用错了：「材料」不指身高或技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27670, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "材料", "is_correct": true, "explanation": "材料：做饺子需要的东西，可以提前准备。"}, {"text": "日期", "is_correct": false, "explanation": "语义：日期指日子，不能用来做饺子，句意不通。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是地方，不是做饺子用的东西，句意不通。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：「准备」可以搭配「材料」，不搭配「作者」。"}], "explanations": {"材料": "材料：做饺子需要的东西，可以提前准备。", "日期": "语义：日期指日子，不能用来做饺子，句意不通。", "饭店": "语义：饭店是地方，不是做饺子用的东西，句意不通。", "作者": "搭配：「准备」可以搭配「材料」，不搭配「作者」。"}, "sentence_index": 6, "correct_answer": "材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑着材料去上班，很方便。", "explanation": "这里用错了：「材料」指做东西用的原料，不指「自行车」之类的交通工具；这里应说「骑着自行车」。"}, {"text": "这个时间的材料是三点，不能迟到。", "explanation": "这里用错了：「材料」指做东西用的原料，不能表示时间点；这里不应用「材料」，应说「时刻」。"}, {"text": "我饿了，想吃一碗材料。", "explanation": "这里用错了：「材料」是做东西用的原料，不是做好的饭菜，不能说「吃一碗材料」；这里应说「面条」等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只材料是从外国进口的。", "corrected_sentence": "这批材料是从外国进口的。", "error_description": "「材料」用「批」或「种」计量，「只」多用于动物或成对的物品，不能用于材料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些材料们很多，够我们用。", "corrected_sentence": "这些材料很多，够我们用。", "error_description": "「材料」是无生命的东西，不加「们」表示复数，直接说「这些材料」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
