INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "把东西从一个地方送到另一个地方需要花的钱。", "primary_collocate": null, "pronunciation": "yùn shū chéng běn", "ipa": "yn˥˩ ʂu˥ ʈʂʰɤŋ˧˥ pən˨˩˦", "syllable_count": 4, "sentences": [{"text": "网上买东西，运输成本要算进价格里。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果从南方运来，运输成本不低。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家具很重，所以运输成本很高。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店把运输成本算在东西的价钱里。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开了一家小公司，帮人们降低运输成本。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离得越远，运输成本就越高。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道寄到北京的运输成本是多少。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个价钱里已经有运输成本了，不用再给钱。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了节省运输成本，他们自己开车去拉货。", "target_word": "运输成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路难走，运输成本比平路高。", "target_word": "运输成本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "運輸成本", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西送到别处所花的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3bd6d02-7b3a-476c-b3ee-298438b187a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运输成本", "is_correct": true, "explanation": "“运输成本”是运送东西所花的钱，可以算进价格里，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是商品的费用，不能算进价格里。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“算进价格里”的应是可以计算的费用，“心情”不能与“算进”搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能算进价格里，句意不通。"}], "explanations": {"运输成本": "“运输成本”是运送东西所花的钱，可以算进价格里，符合句意。", "年龄": "语义：年龄不是商品的费用，不能算进价格里。", "心情": "搭配：“算进价格里”的应是可以计算的费用，“心情”不能与“算进”搭配。", "颜色": "语义：颜色不能算进价格里，句意不通。"}, "sentence_index": 0, "correct_answer": "运输成本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店付了一把运输成本。", "explanation": "这里应该用〈笔〉。“运输成本”是抽象的费用，量词用“笔”；“把”用于有柄的器具，不能计量费用。"}, {"text": "运输成本跑得很快，一会儿就到了。", "explanation": "这里应该用〈货车〉。“跑得快”说的是车辆，运输成本是费用，不会跑。"}, {"text": "这家公司的运输成本很强。", "explanation": "这里应该用〈运力〉。“强”形容运输能力，“运力”可以说强；“运输成本”是费用，不能说强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运输成本", "is_correct": true, "explanation": "“寄到北京的运输成本”指寄送这件东西所需的费用，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是寄送过程中需要花的钱，句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格不能用钱来计算，“寄到北京的性格是多少”句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，寄送的物品不能说“体重”。"}], "explanations": {"运输成本": "“寄到北京的运输成本”指寄送这件东西所需的费用，符合句意。", "味道": "语义：味道不是寄送过程中需要花的钱，句意不通。", "性格": "语义：性格不能用钱来计算，“寄到北京的性格是多少”句意不通。", "体重": "搭配：“体重”用于人或动物，寄送的物品不能说“体重”。"}, "sentence_index": 6, "correct_answer": "运输成本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们把运输成本的颜色换成了红色。", "explanation": "这里应该用〈油漆〉。“换颜色”用于物件的外表，运输成本是费用，没有颜色，不能换色。"}, {"text": "这批货的运输成本有两米长。", "explanation": "这里应该用〈箱子〉。“两米长”说的是物体的长度，运输成本是费用，没有长度。"}, {"text": "这批货的运输成本需要三天。", "explanation": "这里应该用〈时间〉。“需要三天”说的是时间长短，运输成本是费用，不能用天数来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们算出了一只运输成本，才决定价格。", "corrected_sentence": "我们算出了一笔运输成本，才决定价格。", "error_description": "量词错误：“运输成本”应用量词“笔”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批货的运输成本已经算出了来。", "corrected_sentence": "这批货的运输成本已经算出来了。", "error_description": "趋向补语错误：“算出来了”是正确说法，不能说“算出了来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5880f798-bf61-495f-b7cd-f659b8266307') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
