INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27676, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把植物上的花、果子、叶子等取下来。", "primary_collocate": null, "pronunciation": "cǎi zhāi", "ipa": "tsʰaɪ˨˩˦ ʈʂaɪ˥", "syllable_count": 2, "sentences": [{"text": "秋天到了，农民开始采摘梨。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在草地上采摘野花。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去果园采摘樱桃，又甜又新鲜。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上都去菜园采摘西红柿。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地采摘了几朵玫瑰，送给妈妈。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的桃子熟了，大家都来采摘。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "采摘荔枝要趁早，不然会坏。", "target_word": "采摘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片茶园的茶叶，都是用手采摘的。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人手里提着篮子，在树下采摘橘子。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天可以去农场采摘草莓，体验一下。", "target_word": "采摘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采摘了", "label": "体标"}, {"form": "采摘过", "label": "体标"}, {"form": "採摘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用手把花、果子或叶子从植物上取下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '058d721c-6fd8-4b0f-a130-3d7cc342e209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "采摘", "is_correct": true, "explanation": "采摘：用手把果子从植物上取下来，这里指采收梨。"}, {"text": "关闭", "is_correct": false, "explanation": "语义：梨不能被关闭，句中要的是采收的动作。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：打碎梨不是秋天农民的采收动作，与句子语境不合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器具或机器，不能说修理梨。"}], "explanations": {"采摘": "采摘：用手把果子从植物上取下来，这里指采收梨。", "关闭": "语义：梨不能被关闭，句中要的是采收的动作。", "打碎": "语义：打碎梨不是秋天农民的采收动作，与句子语境不合。", "修理": "搭配：“修理”的对象是器具或机器，不能说修理梨。"}, "sentence_index": 0, "correct_answer": "采摘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民在地里采摘小麦。", "explanation": "这里应该用〈收割〉。采摘用于花、果、叶等，小麦等粮食要用收割。"}, {"text": "妈妈在菜市场采摘青菜。", "explanation": "这里应该用〈挑选〉。在市场买青菜不是采摘，采摘是从植物上取下。"}, {"text": "他在超市采摘了一瓶牛奶。", "explanation": "这里应该用〈买〉。在超市买牛奶不是采摘；采摘指用手把植物上的花、果子取下来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "采摘", "is_correct": true, "explanation": "采摘：用手从植物上摘取果实，这里指采摘荔枝。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是器具或机器，不能说修理荔枝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带水果作宾语，荔枝不能被唱。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：欣赏不是会让荔枝变坏的动作，与“趁早，不然会坏”的语境不合。"}], "explanations": {"采摘": "采摘：用手从植物上摘取果实，这里指采摘荔枝。", "修理": "搭配：“修理”的对象是器具或机器，不能说修理荔枝。", "唱": "搭配：“唱”不能带水果作宾语，荔枝不能被唱。", "欣赏": "语义：欣赏不是会让荔枝变坏的动作，与“趁早，不然会坏”的语境不合。"}, "sentence_index": 6, "correct_answer": "采摘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理发师在店里采摘头发。", "explanation": "这里应该用〈剪〉。采摘只用于植物的花、果、叶等，不能用于头发。"}, {"text": "科学家在森林里采摘昆虫标本。", "explanation": "这里应该用〈采集〉。采摘指用手摘取花、果、叶等，采集用于标本、数据等。"}, {"text": "他在地里采摘了一根萝卜。", "explanation": "这里应该用〈拔〉。萝卜长在地下，要拔出来；采摘用于植物上的花、果子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把西红柿采摘。", "corrected_sentence": "奶奶把西红柿采摘了。", "error_description": "体貌/补语错误：“把”字句中动词后需要有“了”或补语，“把西红柿采摘”没有说完整，应说“把西红柿采摘了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民们在果园里了采摘草莓。", "corrected_sentence": "农民们在果园里采摘草莓。", "error_description": "体标位置错误：“了”不能放在“在果园里”与动词“采摘”之间，应去掉这个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67e68ad4-b3d8-41d9-8002-c42f5564b9a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
