INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "别的国家把东西卖到你家，你的国家就是进口国。", "primary_collocate": null, "pronunciation": "jìn kǒu guó", "ipa": "tɕin˥˩ kʰoʊ˨˩˦ kwo˧˥", "syllable_count": 3, "sentences": [{"text": "我们国家是这种水果的进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从外国买牛肉的国家是牛肉进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小国家是粮食进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道哪个国家是中国茶的进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为进口国，我们每年都买很多咖啡。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛国没有煤，所以是煤的进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口国的商店里有很多外国东西。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：谁是石油的进口国？", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进口国的人喜欢买外国的牛奶。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上红色的国家是进口国。", "target_word": "进口国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "進口國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买进外国东西的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1de80df8-30f4-4a4d-832e-d5d2f03764c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机不是国家，“我们国家是……的手机”无法成立。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本不指买入货物的一方，与“我们国家”的身份不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“是……的玻璃”不能与“国家”构成身份关系，玻璃是材料。"}, {"text": "进口国", "is_correct": true, "explanation": "进口国指从外国买进商品的国家，与“我们国家是这种水果的……”的语境相符。"}], "explanations": {"手机": "语义：手机不是国家，“我们国家是……的手机”无法成立。", "课本": "语义：课本不指买入货物的一方，与“我们国家”的身份不符。", "玻璃": "搭配：“是……的玻璃”不能与“国家”构成身份关系，玻璃是材料。", "进口国": "进口国指从外国买进商品的国家，与“我们国家是这种水果的……”的语境相符。"}, "sentence_index": 0, "correct_answer": "进口国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家的大米大多卖给了外国，是大米的进口国。", "explanation": "这里应该用〈出口国〉。进口国指从外国买入商品的国家，句中说大米卖给外国，是卖出，应说出口国。"}, {"text": "这家公司是这种咖啡的进口国。", "explanation": "这里应该用〈进口商〉。进口国指国家，“这家公司”是企业，应说进口商。"}, {"text": "这个进口国每天给学生上三节课。", "explanation": "这里应该用〈老师〉。进口国指从外国买入商品的国家，不能给学生上课；句中说给学生上三节课，应说老师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟不是能拥有商店的主体，“……的商店里”需要国家或地区作修饰语。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能拥有商店，与句中语境冲突。"}, {"text": "树叶", "is_correct": false, "explanation": "搭配：“树叶的商店”不成立，商店的所属不能是植物的部件。"}, {"text": "进口国", "is_correct": true, "explanation": "进口国指从外国买入商品的国家，它的商店里有外国商品，与语境相符。"}], "explanations": {"小鸟": "语义：小鸟不是能拥有商店的主体，“……的商店里”需要国家或地区作修饰语。", "月亮": "语义：月亮是天体，不能拥有商店，与句中语境冲突。", "树叶": "搭配：“树叶的商店”不成立，商店的所属不能是植物的部件。", "进口国": "进口国指从外国买入商品的国家，它的商店里有外国商品，与语境相符。"}, "sentence_index": 6, "correct_answer": "进口国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的进口国很热，我们去游泳吧。", "explanation": "这里应该用〈天气〉。进口国指国家，不能用来描述温度；“很热”描述的是天气。"}, {"text": "这个进口国每天做很多牛肉菜。", "explanation": "这里应该用〈厨师〉。进口国指国家，不能做菜；句中说每天做很多牛肉菜，应说厨师。"}, {"text": "这个进口国每天开车送货，很辛苦。", "explanation": "这里应该用〈司机〉。进口国指国家，不能开车送货；句中的“开车送货”只能指人，应说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条进口国从外国买了很多煤。", "corrected_sentence": "这个进口国从外国买了很多煤。", "error_description": "量词错误：“进口国”是国家，应说“这个进口国”，不能说“这条进口国”；“条”多用于河流、道路等细长事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，我们国家是咖啡的很进口国。", "corrected_sentence": "老师说，我们国家是咖啡的进口国。", "error_description": "程度副词误用：「进口国」是名词，不能用程度副词「很」修饰。错误：咖啡的很进口国；正确：咖啡的进口国。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f957f932-301d-425c-a259-94b1300223e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
