INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27682, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来做事情的方法。", "primary_collocate": null, "pronunciation": "jì shù shǒu duàn", "ipa": "tɕi˥˩ ʂu˥˩ ʂoʊ˨˩˦ twan˥˩", "syllable_count": 4, "sentences": [{"text": "要完成这项工作，需要合适的技术手段。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找一种技术手段来记录声音。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在我们有更多技术手段了解天气。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用什么技术手段做这个视频？", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司没有太多技术手段，只好手工做。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种技术手段很简单，谁都能学会。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠新的技术手段把路修好了。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音是记录会议的一种技术手段。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有合适的技术手段，工作很难做完。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学几种技术手段，帮朋友修电脑。", "target_word": "技术手段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "技术手段：用来做某件事的技术性方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82ebd84-cad9-43e3-91eb-87aa720f70fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27682, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "技术手段", "is_correct": true, "explanation": "技术手段：完成工作所需的具体技术性方法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与完成工作的方法无关，句子说的是完成工作的手段。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不是完成工作的方法。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址与完成工作无关，不能作为完成工作的方法。"}], "explanations": {"技术手段": "技术手段：完成工作所需的具体技术性方法。", "颜色": "语义：颜色与完成工作的方法无关，句子说的是完成工作的手段。", "饮料": "语义：饮料是喝的东西，不是完成工作的方法。", "地址": "语义：地址与完成工作无关，不能作为完成工作的方法。"}, "sentence_index": 0, "correct_answer": "技术手段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她喝掉了那个技术手段。", "explanation": "这里应该用〈饮料〉。技术手段是方法或工具，不能被喝掉，喝东西要用饮料。"}, {"text": "她把技术手段放进冰箱里了。", "explanation": "这里应该用〈食物〉。技术手段是做事的方法，看不见摸不着，不能放进冰箱。"}, {"text": "她开着技术手段去了公司。", "explanation": "这里应该用〈汽车〉。技术手段是方法或工具，不能开着去上班，开车要用汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27682, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "技术手段", "is_correct": true, "explanation": "技术手段：靠新的技术方法把路修好，符合句意。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：歌词不能作为修路的方法，句子说的是靠技术修路。"}, {"text": "香水", "is_correct": false, "explanation": "语义：香水与修路无关，不能作为修路的方法。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：修路要靠技术或工具，不能靠眼泪完成。"}], "explanations": {"技术手段": "技术手段：靠新的技术方法把路修好，符合句意。", "歌词": "语义：歌词不能作为修路的方法，句子说的是靠技术修路。", "香水": "语义：香水与修路无关，不能作为修路的方法。", "眼泪": "搭配：修路要靠技术或工具，不能靠眼泪完成。"}, "sentence_index": 6, "correct_answer": "技术手段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想学一只技术手段，帮朋友修电脑。", "explanation": "这里应该用〈种〉。“技术手段”的量词是“种”，不用“只”。"}, {"text": "他把技术手段吃完了。", "explanation": "这里应该用〈饭〉。技术手段是做事的方法，不能吃，吃的应该是饭。"}, {"text": "他把技术手段穿在身上。", "explanation": "这里应该用〈衣服〉。技术手段是方法或工具，不能穿在身上，穿要用衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27682, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们需要一技术手段来统计数据。", "corrected_sentence": "他们需要一种技术手段来统计数据。", "error_description": "错误：“一技术手段”；正确：“一种技术手段”。“一”后接名词要加量词，“技术手段”用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27682, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们用几种技术手段们提高了效率。", "corrected_sentence": "工人们用几种技术手段提高了效率。", "error_description": "错误：“技术手段们”；正确：“技术手段”。“们”只加在指人的名词后，“技术手段”指事物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77e88780-b700-499f-a570-98f01fe9a484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
