INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把文章、图片等整理好，让它们变得更好看。", "primary_collocate": null, "pronunciation": "biān jí", "ipa": "pjɛn˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我想把旅行照片编辑得更好看。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她编辑图片以后，照片好看多了。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在编辑公司网站上的文章。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片太暗，请再编辑一下。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢编辑文章，让页面更漂亮。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑过的图片颜色更亮。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们在电脑上编辑班报，要排得好看。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用软件编辑了一张海报。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先编辑好文章，再放到网上。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会编辑照片，所以请我帮忙。", "target_word": "编辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "编辑了", "label": "体标"}, {"form": "编辑过", "label": "体标"}, {"form": "編輯", "label": "繁体"}, {"form": "编辑器", "label": "复合"}], "register": "中性", "sense_fingerprint": "整理文章、图片使其更美观", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf1fc5f1-3de3-49b7-bd2c-bca5dafc47e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：编辑照片可以使其更好看，“把照片编辑得更好看”符合该义项。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言文字，不能把照片翻译。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做食物的动作，不能用来让照片更好看。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”用于布料、衣物，不说把照片缝得好看。"}], "explanations": {"编辑": "正确：编辑照片可以使其更好看，“把照片编辑得更好看”符合该义项。", "翻译": "搭配：“翻译”的对象是语言文字，不能把照片翻译。", "烘焙": "语义：烘焙是做食物的动作，不能用来让照片更好看。", "缝": "搭配：“缝”用于布料、衣物，不说把照片缝得好看。"}, "sentence_index": 0, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书桌编辑了一下，看起来干净多了。", "explanation": "这里应该用〈整理〉。书桌要收拾整理，编辑只用于文字、图片等内容。"}, {"text": "他花了一个小时编辑电脑。", "explanation": "这里应该用〈修理〉。电脑坏了要修理，编辑不能用于机器。"}, {"text": "他在厨房编辑了一个蛋糕。", "explanation": "这里应该用〈做〉。做蛋糕是烹饪，编辑只用于文字、图片等内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "编辑", "is_correct": true, "explanation": "正确：在电脑上编辑班报并排版，使版面好看，符合该义项。"}, {"text": "雕刻", "is_correct": false, "explanation": "语义：班报是纸面文字，在电脑上不能雕刻。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”的对象是有表面的物件，不说擦拭班报。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪动作，电脑上的班报无法煮。"}], "explanations": {"编辑": "正确：在电脑上编辑班报并排版，使版面好看，符合该义项。", "雕刻": "语义：班报是纸面文字，在电脑上不能雕刻。", "擦拭": "搭配：“擦拭”的对象是有表面的物件，不说擦拭班报。", "煮": "语义：煮是烹饪动作，电脑上的班报无法煮。"}, "sentence_index": 6, "correct_answer": "编辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天编辑桌子，很辛苦。", "explanation": "这里应该用〈擦〉。擦去桌面灰尘要说擦，编辑只用于文字、图片等内容。"}, {"text": "我每天晚上编辑碗，很累。", "explanation": "这里应该用〈洗〉。碗要洗，不能说编辑。"}, {"text": "爸爸每天编辑衣服，很辛苦。", "explanation": "这里应该用〈晾晒〉。衣服晾干要说晾晒，编辑不能用于衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把照片编辑很自然。", "corrected_sentence": "她把照片编辑得很自然。", "error_description": "补语错误：动词“编辑”后带补语“很自然”时要用“得”连接，应说“编辑得很自然”，不说“编辑很自然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们编辑了过班报。", "corrected_sentence": "我们编辑过班报。", "error_description": "体标错误：“编辑”后用“过”表示经历，不能再加“了”，应说“编辑过班报”，不说“编辑了过班报”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99b1b2f7-7082-4190-914b-06aae8462713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
