INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27686, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "告诉你每天要做什么事。", "primary_collocate": null, "pronunciation": "rì chéng ān pái", "ipa": "ʐʅ˥˩ ʈʂʰɤŋ˧˥ an˥ pʰaɪ˧˥", "syllable_count": 4, "sentences": [{"text": "这周我的日程安排很满，没有时间休息。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把明天的日程安排发给我。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理看了一下今天的日程安排。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，我们改变了旅行的日程安排。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先看看日程安排，再决定哪天见面。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们发了考试周的日程安排。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次出差的日程安排是公司定的。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的日程安排是早上开会，下午见客人。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日程安排太紧，我们没时间吃午饭。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想调整一下下周的日程安排。", "target_word": "日程安排", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日程安排表", "label": "复合词"}], "register": "中性", "sense_fingerprint": "按时间排好的每天要做的事情计划", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27686, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日程安排", "is_correct": true, "explanation": "正确。日程安排指按时间排好的每天要做的事，可以说“很满”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不是要做的事，不能说“很满”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体形，不能用“很满”形容，这句讲的是要做的事。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“满”不用来修饰脾气，不说“脾气很满”。"}], "explanations": {"日程安排": "正确。日程安排指按时间排好的每天要做的事，可以说“很满”。", "天气": "语义：天气指气候状况，不是要做的事，不能说“很满”。", "身材": "体貌：身材描述人的体形，不能用“很满”形容，这句讲的是要做的事。", "脾气": "搭配：“满”不用来修饰脾气，不说“脾气很满”。"}, "sentence_index": 0, "correct_answer": "日程安排"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的日程安排是明年在上海开一家分店。", "explanation": "这里应该用〈计划〉。日程安排指按时间排好的每天要做的事，长远的打算要用计划。"}, {"text": "他的日程安排是考上大学。", "explanation": "这里应该用〈目标〉。日程安排说的是每天的时间安排，不能用来表示要达到的目的。"}, {"text": "我的日程安排是当一名医生。", "explanation": "这里应该用〈理想〉。日程安排说的是近期要做的事，不能用来说长远的志向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日程安排", "is_correct": true, "explanation": "正确。日程安排指按时间排好的要做的事，公司可以替出差的人定下来。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的重量，不能由公司决定。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是个人的感受，“定”只用于计划、规定，不能说“公司定的心情”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的性情特点，不能由公司规定，句子不通。"}], "explanations": {"日程安排": "正确。日程安排指按时间排好的要做的事，公司可以替出差的人定下来。", "体重": "体貌：体重是身体的重量，不能由公司决定。", "心情": "语义：心情是个人的感受，“定”只用于计划、规定，不能说“公司定的心情”。", "性格": "语义：性格是人的性情特点，不能由公司规定，句子不通。"}, "sentence_index": 6, "correct_answer": "日程安排"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他递给我一块日程安排。", "explanation": "这里应该用〈份〉。数日程安排要用量词“份”；“块”用于成块的东西，不能用来数日程安排。"}, {"text": "会议室的墙上贴着一首日程安排。", "explanation": "这里应该用〈份〉。“首”用于诗歌、歌曲，不能用来数日程安排。"}, {"text": "我的包里装着一条日程安排。", "explanation": "这里应该用〈份〉。“条”用于细长的东西，不能用来数日程安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秘书正在核对经理地日程安排。", "corrected_sentence": "秘书正在核对经理的日程安排。", "error_description": "结构助词：修饰名词“日程安排”要用“的”，“地”用于修饰动词，写成“经理地日程安排”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没看了日程安排。", "corrected_sentence": "我还没看过日程安排。", "error_description": "体标误用：“没”否定已发生的动作时，动词后不能加“了”；表示还没有这个经历，要说“没看过日程安排”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "洗", "is_correct": false, "explanation": "与“记得”没有反义关系，“洗”是清洁的动作。"}, {"text": "唱", "is_correct": false, "explanation": "与“记得”没有反义关系，“唱”是发声的动作。"}, {"text": "住", "is_correct": false, "explanation": "与“记得”没有反义关系，“住”指居住或停留。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "洗": "与“记得”没有反义关系，“洗”是清洁的动作。", "唱": "与“记得”没有反义关系，“唱”是发声的动作。", "住": "与“记得”没有反义关系，“住”指居住或停留。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忘记", "is_correct": true, "explanation": "反义：“记得”与“忘记”相对，表示不再记得。"}, {"text": "放", "is_correct": false, "explanation": "与“记得”没有反义关系，“放”是放置的动作。"}, {"text": "用", "is_correct": false, "explanation": "与“记得”没有反义关系，“用”是使用的动作。"}, {"text": "走", "is_correct": false, "explanation": "与“记得”没有反义关系，“走”是移动的动作。"}], "correct_answer": "忘记", "explanations": {"忘记": "反义：“记得”与“忘记”相对，表示不再记得。", "放": "与“记得”没有反义关系，“放”是放置的动作。", "用": "与“记得”没有反义关系，“用”是使用的动作。", "走": "与“记得”没有反义关系，“走”是移动的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "把看到或听到的事情放在心里，不会忘掉。", "primary_collocate": null, "pronunciation": "jì de", "ipa": "tɕi˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "老师说的话，你要记得。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地址我只看过一次，现在还记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "zhè ge dì zhǐ wǒ zhǐ kàn guo yí cì, xiàn zài hái jì de.", "sentence_source": "generated"}, {"text": "老师讲的那个故事，我一直记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "lǎo shī jiǎng de nà ge gù shi, wǒ yì zhí jì de.", "sentence_source": "generated"}, {"text": "这个电话号码很重要，一定要记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位老人说的话，我记得很清楚。", "target_word": "记得", "complexity_tier": "T3", "furigana": "nà wèi lǎo rén shuō de huà, wǒ jì de hěn qīng chu.", "sentence_source": "generated"}, {"text": "妈妈的话，我一直记得。", "target_word": "记得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路上看到的路牌，他全都记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那本书的内容，他一直记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "nà běn shū de nèi róng, tā yì zhí jì de.", "sentence_source": "generated"}, {"text": "开会时听到的事，大家要记得。", "target_word": "记得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图他只看过一遍，却都记得。", "target_word": "记得", "complexity_tier": "T3", "furigana": "dì tú tā zhǐ kàn guo yí biàn, què dōu jì de.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不记得", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "把见闻放在心里，牢记不忘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确答案：记得，表示把听到或看到的事放在心里，不会忘掉。"}, {"text": "急得", "is_correct": false, "explanation": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。"}, {"text": "挤得", "is_correct": false, "explanation": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。"}, {"text": "积德", "is_correct": false, "explanation": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。"}, {"text": "细的", "is_correct": false, "explanation": "xì（第四声）与 jì（第四声）声母不同（x 与 j），意思是细小，「细的」是形容词性短语。"}], "explanations": {"记得": "正确答案：记得，表示把听到或看到的事放在心里，不会忘掉。", "急得": "jí（第二声）与 jì（第四声）声调不同，「急得」意思是着急。", "挤得": "jǐ（第三声）与 jì（第四声）声调不同，「挤得」意思是挤压。", "积德": "jī（第一声）与 jì（第四声）声调不同，「积德」意思是积累善行。", "细的": "xì（第四声）与 jì（第四声）声母不同（x 与 j），意思是细小，「细的」是形容词性短语。"}, "sentence_index": null, "correct_answer": "记得"}, "level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示把老师的话放在心里，与“你要”的劝勉语气相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物品，不能修理“话”。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，“话”不能买。"}, {"text": "体验", "is_correct": false, "explanation": "配价：“体验”的宾语是经历或感受，不能把“老师说的话”作宾语。"}], "explanations": {"记得": "正确：“记得”表示把老师的话放在心里，与“你要”的劝勉语气相合。", "修理": "搭配：“修理”的对象是物品，不能修理“话”。", "购买": "搭配：“购买”的对象是商品，“话”不能买。", "体验": "配价：“体验”的宾语是经历或感受，不能把“老师说的话”作宾语。"}, "sentence_index": 0, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在地图上记得一个红点，决定明天去那儿。", "explanation": "这里应该用〈标〉。在地图上做标记用“标”，记得表示回忆，不能指做标记。"}, {"text": "他在门上记得一张纸条。", "explanation": "这里应该用〈贴〉。把纸条贴在门上是固定动作，记得表示回忆，不能指把纸条贴上去。"}, {"text": "他在名单上记得我的名字。", "explanation": "这里应该用〈登记〉。记得表示留在记忆中，不能指把名字写到名单上；登记才是写下来备案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记得", "is_correct": true, "explanation": "正确：“记得”表示路牌都留在记忆里，与“看到的”相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：路牌不能唱，“唱”与句中的路牌毫无关联。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球之类的物体，不能用于路牌。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多用于衣物、器皿，不用于路牌。"}], "explanations": {"记得": "正确：“记得”表示路牌都留在记忆里，与“看到的”相合。", "唱": "语义：路牌不能唱，“唱”与句中的路牌毫无关联。", "踢": "搭配：“踢”的对象是球之类的物体，不能用于路牌。", "洗": "搭配：“洗”多用于衣物、器皿，不用于路牌。"}, "sentence_index": 6, "correct_answer": "记得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在本子上记得黑板上的公式。", "explanation": "这里应该用〈抄〉。抄是把字写到本子上，记得表示留在记忆中，不能指把公式写下来。"}, {"text": "他一张一张地记得钱，数了半天。", "explanation": "这里应该用〈数〉。数是一张张点算，记得表示记忆中有，不能指点算钱。"}, {"text": "我用摄像机记得这场比赛，回去再看一遍。", "explanation": "这里应该用〈录〉。录指用设备保存影像，记得表示回忆，不能指用摄像机保存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事我一直记得着。", "corrected_sentence": "这件事我一直记得。", "error_description": "错误形式：“记得着”；正确形式：“记得”。“记得”是状态动词，表示记在心里，不能再加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条路的每个路口我都记得得。", "corrected_sentence": "那条路的每个路口我都记得。", "error_description": "错误形式：“记得得”；正确形式：“记得”。“记得”后面不能再加一个“得”，多出的“得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
