INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种用数学方法描述事情可能怎么发生的工具。", "primary_collocate": null, "pronunciation": "gài lǜ mó xíng", "ipa": "kaɪ˥˩ ly˥˩ mwo˧˥ ɕiŋ˧˥", "syllable_count": 4, "sentences": [{"text": "概率模型是描述事情可能怎么发生的工具。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了一个概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型可以算出下雨的可能。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用概率模型研究骰子的点数。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用概率模型猜明天的天气。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型太简单，算得不准。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们学着建立一个简单的概率模型。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "概率模型能告诉我们，事情有多大可能发生。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个概率模型用到的数学很简单。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店用概率模型预测每天卖多少。", "target_word": "概率模型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "用数学方法描述事情可能性的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a63aca67-39cc-41c0-8a09-ede636634a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "概率模型用数学方法描述事情可能怎么发生，正是这句定义所说的工具。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是盛花的器皿，不能描述事情可能性的发生。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：棉被是寝具，与描述事情可能怎么发生的工具无关。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "语义：蜂蜜是食物，不是描述事情可能怎么发生的工具。"}], "explanations": {"概率模型": "概率模型用数学方法描述事情可能怎么发生，正是这句定义所说的工具。", "花瓶": "语义：花瓶是盛花的器皿，不能描述事情可能性的发生。", "棉被": "语义：棉被是寝具，与描述事情可能怎么发生的工具无关。", "蜂蜜": "语义：蜂蜜是食物，不是描述事情可能怎么发生的工具。"}, "sentence_index": 0, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支球队的概率模型很高。", "explanation": "这里应该用〈胜率〉。概率模型是描述可能性的工具，不能直接表示球队赢的比例。"}, {"text": "概率模型很烫，快喝吧。", "explanation": "这里应该用〈汤〉。“快喝”指喝汤或饮品；概率模型是数学工具，不能喝。"}, {"text": "这个概率模型很好吃。", "explanation": "这里应该用〈菜〉：“很好吃”形容食物；概率模型是数学工具，不能当作食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概率模型", "is_correct": true, "explanation": "学生可以学着建立一个简单的概率模型，搭配正确。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜是蔬菜，不能被“建立”成模型。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然地理实体，与“建立一个简单的”搭配不通。"}, {"text": "身材", "is_correct": false, "explanation": "语义：“身材”指人的体形，不能被“建立”，与“建立一个简单的”搭配不通。"}], "explanations": {"概率模型": "学生可以学着建立一个简单的概率模型，搭配正确。", "白菜": "语义：白菜是蔬菜，不能被“建立”成模型。", "河流": "语义：河流是自然地理实体，与“建立一个简单的”搭配不通。", "身材": "语义：“身材”指人的体形，不能被“建立”，与“建立一个简单的”搭配不通。"}, "sentence_index": 6, "correct_answer": "概率模型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨的概率模型很大。", "explanation": "这里应该用〈可能性〉：“很大”形容可能性；概率模型是数学方法，不能说“下雨的概率模型很大”。"}, {"text": "这首乐曲的概率模型很动听。", "explanation": "这里应该用〈旋律〉：“很动听”形容乐曲；概率模型是数学工具，不能用来形容乐曲。"}, {"text": "概率模型的颜色是红色的。", "explanation": "这里“概率模型”是数学方法，没有颜色；颜色用于〈图表〉这类有形的东西，不能用来描述它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用一条概率模型预测天气。", "corrected_sentence": "我们用一个概率模型预测天气。", "error_description": "量词错误：模型应用“个”，“条”用于细长的东西。应为“用一个概率模型”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他建概率模型得很快。", "corrected_sentence": "他建概率模型建得很快。", "error_description": "重复动词漏写：“建……得”结构中补语前需要重复动词“建”，应为“建概率模型建得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0ee01af-31c8-479e-9711-8e650dae9bc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "“落后”与“超越”相对，一个是比别人强，一个是比别人差，是一对反义词。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，与“超越”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“超越”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“超越”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "“落后”与“超越”相对，一个是比别人强，一个是比别人差，是一对反义词。", "保持": "“保持”指维持原状，与“超越”没有反义关系。", "参加": "“参加”指加入某项活动，与“超越”没有反义关系。", "观察": "“观察”指仔细看，与“超越”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "落后", "is_correct": true, "explanation": "“落后”与“超越”相对，一个是比别人强，一个是比别人差，是一对反义词。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”指做成某件事，与“超越”没有反义关系。"}, {"text": "安排", "is_correct": false, "explanation": "“安排”指做出布置、计划，与“超越”没有反义关系。"}, {"text": "回答", "is_correct": false, "explanation": "“回答”指对问题作出应答，与“超越”没有反义关系。"}], "correct_answer": "落后", "explanations": {"落后": "“落后”与“超越”相对，一个是比别人强，一个是比别人差，是一对反义词。", "完成": "“完成”指做成某件事，与“超越”没有反义关系。", "安排": "“安排”指做出布置、计划，与“超越”没有反义关系。", "回答": "“回答”指对问题作出应答，与“超越”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比别的东西跑得更快或做得更好。", "primary_collocate": null, "pronunciation": "chāo yuè", "ipa": "tʂʰɑʊ˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他跑得很快，超越了前面的人。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想超越去年的自己。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车很快，一下就超越了我们。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学习很努力，很快就超越了班里的同学。", "target_word": "超越", "complexity_tier": "T3", "furigana": "chāoyuè", "sentence_source": "generated"}, {"text": "弟弟想在比赛中超越哥哥。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的公司已经超越了老对手。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经超越过很多人，但是还没有突破自己。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位选手超越了之前所有人的纪录。", "target_word": "超越", "complexity_tier": "T3", "furigana": "chāoyuè", "sentence_source": "generated"}, {"text": "没有人能超越他的记录。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后一圈，小王超越了所有的对手。", "target_word": "超越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超越了", "label": "体标"}, {"form": "超越过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "比别人或原来更快更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e21988-a24b-41f5-92fd-a20a131657a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”是对有过错的人宽恕，与“跑得很快”无关，句子读不通。"}, {"text": "超越", "is_correct": true, "explanation": "“超越”指比别人跑得更快，正好承接“跑得很快”，表示超过了前面的人。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“跑得很快”的意思不合，“放弃了前面的人”句意不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是看重或赞美，跑得快的人不会因此去欣赏前面的人，句意不通。"}], "explanations": {"原谅": "语义：“原谅”是对有过错的人宽恕，与“跑得很快”无关，句子读不通。", "超越": "“超越”指比别人跑得更快，正好承接“跑得很快”，表示超过了前面的人。", "放弃": "语义：“放弃”表示不再坚持，与“跑得很快”的意思不合，“放弃了前面的人”句意不通。", "欣赏": "语义：“欣赏”是看重或赞美，跑得快的人不会因此去欣赏前面的人，句意不通。"}, "sentence_index": 0, "correct_answer": "超越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的参加人数超越了一百人。", "explanation": "这里应该用〈超过〉。“超越”多指比别人跑得更快、做得更好，人数超过某个数字要用“超过”。"}, {"text": "这笔开销超越了原定的预算。", "explanation": "这里应该用〈超出〉。“超越”指比别人或原来做得更好，开销超出限度要用“超出”。"}, {"text": "这个月我的体重超越了三公斤。", "explanation": "这里应该用〈增加〉。“超越”指在成绩或水平上胜过别人，体重增加多少要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能说“煮过很多人”，句意荒谬。"}, {"text": "超越", "is_correct": true, "explanation": "“超越”指胜过别人，与前面的“很多人”相呼应，表示超过了很多人。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：“缩小”用于范围、差距，不能缩小“人”，句意不通。"}, {"text": "开设", "is_correct": false, "explanation": "搭配：“开设”的宾语多是课程、班级，不说“开设过很多人”。"}], "explanations": {"煮": "语义：“煮”的对象是食物，不能说“煮过很多人”，句意荒谬。", "超越": "“超越”指胜过别人，与前面的“很多人”相呼应，表示超过了很多人。", "缩小": "语义：“缩小”用于范围、差距，不能缩小“人”，句意不通。", "开设": "搭配：“开设”的宾语多是课程、班级，不说“开设过很多人”。"}, "sentence_index": 6, "correct_answer": "超越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的电费超越了两百块。", "explanation": "这里应该用〈超过〉。“超越”指比别人或原来做得更好，钱数多于某个数字要用“超过”。"}, {"text": "他的身高已经超越了一米八。", "explanation": "这里应该用〈超过〉。“超越”指在水平、成绩上胜过别人，身高多于某个数字要用“超过”。"}, {"text": "我们坐车超越了那座小镇。", "explanation": "这里应该用〈经过〉。“超越”不指车辆从某地经过，表示经过地点要用“经过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛里，他很快就超越到了所有对手。", "corrected_sentence": "这场比赛里，他很快就超越了所有对手。", "error_description": "“超越”后面不能加结果补语“到”，应说“超越了所有对手”。“到”多用于“达到”“赶到”之类的词，不能接在“超越”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27696, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有超越了所有的同学。", "corrected_sentence": "他没有超越所有的同学。", "error_description": "“没有”否定时，动词后面不能再加“了”，应说“他没有超越所有的同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '163bd4f3-44c1-4ab8-804c-0825f77f3534') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
