INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "以为别人做错了事情，其实是自己想错了。", "primary_collocate": null, "pronunciation": "wù jiě", "ipa": "wu˥˩ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "对不起，我误解你了，以为是你拿的。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我误解了他，其实他是想帮我。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她误解了朋友的好意，生了半天气。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别误解我，我不是在批评你。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他误解了妈妈的话，哭了一晚上。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一直误解你，现在才知道你的想法。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常误解别人，所以朋友很少。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师误解了小明，以为他没写作业。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他误解过我，后来向我道歉了。", "target_word": "误解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你误解他了，他不是故意迟到的。", "target_word": "误解", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "误解了", "label": "体标"}, {"form": "误解过", "label": "体标"}, {"form": "誤解", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：把别人的做法或用意想错，错怪对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73399449-2470-45bf-a42c-72fe9fbc4333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确答案。误解指把别人的做法或用意想错。"}, {"text": "无解", "is_correct": false, "explanation": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。"}, {"text": "误写", "is_correct": false, "explanation": "xiě 与 jiě 声母不同（x 与 j），意思是写错。"}, {"text": "误接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是接错。"}], "explanations": {"误解": "正确答案。误解指把别人的做法或用意想错。", "无解": "wú（第二声）与 wù（第四声）声调不同，意思是没有解决的办法。", "误写": "xiě 与 jiě 声母不同（x 与 j），意思是写错。", "误接": "jiē（第一声）与 jiě（第三声）声调不同，意思是接错。"}, "sentence_index": null, "correct_answer": "误解"}, "level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。“我误解你了，以为是你拿的”中，“误解”表示把对方的行为想错。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是对对方的感激，与“对不起”的道歉语境不符，且与“以为是你拿的”的怀疑相矛盾。"}, {"text": "谴责", "is_correct": false, "explanation": "语义：“谴责”是严厉批评，与“对不起”的道歉以及“以为是你拿的”这种想错的意思不符。"}, {"text": "相信", "is_correct": false, "explanation": "语义：“相信”表示信任对方，与“以为是你拿的”所表达的怀疑相矛盾。"}], "explanations": {"误解": "正确。“我误解你了，以为是你拿的”中，“误解”表示把对方的行为想错。", "感谢": "语义：“感谢”是对对方的感激，与“对不起”的道歉语境不符，且与“以为是你拿的”的怀疑相矛盾。", "谴责": "语义：“谴责”是严厉批评，与“对不起”的道歉以及“以为是你拿的”这种想错的意思不符。", "相信": "语义：“相信”表示信任对方，与“以为是你拿的”所表达的怀疑相矛盾。"}, "sentence_index": 0, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条广告误解了很多消费者，大家都不相信它。", "explanation": "这里应该用〈误导〉。误导指使人产生错误认识，主语可以是广告、言论；“误解”指当事人自己把别人的意思想错，不能用来说广告对消费者的影响。"}, {"text": "他误解了那扇门，一头撞了上去。", "explanation": "这里应该用〈误撞〉。误撞指不小心撞上，是动作上的失误；“误解”针对人的言行或事情真相，不能用于门。"}, {"text": "他误解了一块石头，把它搬进了屋里。", "explanation": "这里应该用〈误拿〉。误拿指拿错东西，是行为上的失误；“误解”针对人的言行或事情真相，不能用于具体物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "误解", "is_correct": true, "explanation": "正确。“常常误解别人，所以朋友很少”指把别人的做法想错，导致关系变差。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是积极行为，不会导致朋友很少，与后半句的因果关系不合。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”是正面态度，与“所以朋友很少”的因果关系相反。"}, {"text": "宠爱", "is_correct": false, "explanation": "搭配：“宠爱”多用于亲近者或晚辈，不说“宠爱别人”。"}], "explanations": {"误解": "正确。“常常误解别人，所以朋友很少”指把别人的做法想错，导致关系变差。", "帮助": "语义：“帮助”是积极行为，不会导致朋友很少，与后半句的因果关系不合。", "尊重": "语义：“尊重”是正面态度，与“所以朋友很少”的因果关系相反。", "宠爱": "搭配：“宠爱”多用于亲近者或晚辈，不说“宠爱别人”。"}, "sentence_index": 6, "correct_answer": "误解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他误解了桌上的杯子，一伸手把它碰倒了。", "explanation": "这里应该用〈误碰〉。误碰指不小心碰到，是动作；“误解”针对人的言行或事情真相，不能用于杯子。"}, {"text": "猎人误解了一只兔子，以为是野猪，一枪把它打伤了。", "explanation": "这里应该用〈误认〉。误认指把对象认错，是辨认上的错误；“误解”针对人的言行或事情真相，不能用于兔子。"}, {"text": "他误解了一只猫，把它赶出了家门。", "explanation": "这里应该用〈认错〉。认错指把人或物辨认错误；“误解”针对言语或事情的理解，不能用于猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把他的话误解了了，对不起。", "corrected_sentence": "我把他的话误解了，对不起。", "error_description": "体标重复：“误解”后的完成标记“了”已经出现，不能再加一个“了”。应写成“误解了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他误解得我的好意，这让我很难过。", "corrected_sentence": "他误解了我的好意，这让我很难过。", "error_description": "补语标记错误：“误解”后直接带宾语，完成义要用“了”，不能用“得”。“得”引出补语，“误解得我的好意”不成句。应写成“误解了我的好意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
