INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西与另一个东西能一一相配，配成一对。", "primary_collocate": null, "pronunciation": "duì yìng", "ipa": "twei˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请找出和这个词对应的图片。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个问题都有对应的答案。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把对应的两张卡片放在一起。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找不到和这把锁对应的钥匙。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每种颜色都有对应的名字。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给每个字写了对应的拼音。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子没有对应的盖子。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个和这个插头对应的插座。", "target_word": "对应", "complexity_tier": "T3", "furigana": "wǒ xiǎng zhǎo yí gè hé zhè gè chātóu duìyìng de chāzuò。", "sentence_source": "generated"}, {"text": "每种药都有对应的使用说明。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把左边的词连到对应的图上。", "target_word": "对应", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "對應", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能配成一对的、相配的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b63a2c7-7b4b-4b6e-a491-5467c19626e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对应", "is_correct": true, "explanation": "正确。“对应”表示可以配成一对，这里说词与图片相配。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不用来形容词与图片的关系。"}, {"text": "安静", "is_correct": false, "explanation": "语义：词不会“安静”，“和这个词安静的图片”与找出相配图片的语境不符。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的体型，不用于描述词与图片的相配。"}], "explanations": {"对应": "正确。“对应”表示可以配成一对，这里说词与图片相配。", "高大": "体貌：“高大”形容体型，不用来形容词与图片的关系。", "安静": "语义：词不会“安静”，“和这个词安静的图片”与找出相配图片的语境不符。", "瘦": "体貌：“瘦”形容人或动物的体型，不用于描述词与图片的相配。"}, "sentence_index": 0, "correct_answer": "对应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这双鞋很对应我的脚。", "explanation": "这里应该用〈合适〉。对应说两个东西可以配成一对，说鞋与脚的大小相称要用“合适”。"}, {"text": "老师对应学生很耐心。", "explanation": "这里应该用〈对待〉。对应表示两者相符，老师待学生的态度要用“对待”。"}, {"text": "我很对应老师。", "explanation": "这里应该用〈尊敬〉。对应表示两者相符，不表示敬重；敬重老师要用“尊敬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对应", "is_correct": true, "explanation": "正确。“对应”表示可以配成一对，这里说盖子与杯子相配。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：盖子不会“聪明”，“没有聪明的盖子”说不通。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：器物不能“幽默”，与盖子是否相配无关。"}, {"text": "调皮", "is_correct": false, "explanation": "搭配：“调皮”形容孩子或动物，不用于形容器物。"}], "explanations": {"对应": "正确。“对应”表示可以配成一对，这里说盖子与杯子相配。", "聪明": "语义：盖子不会“聪明”，“没有聪明的盖子”说不通。", "幽默": "语义：器物不能“幽默”，与盖子是否相配无关。", "调皮": "搭配：“调皮”形容孩子或动物，不用于形容器物。"}, "sentence_index": 6, "correct_answer": "对应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和他很对应。", "explanation": "这里应该用〈熟悉〉。对应只说事物能配成一对，不用来形容人与人的关系；说彼此熟悉要用“熟悉”。"}, {"text": "这只小猫很对应。", "explanation": "这里应该用〈可爱〉。对应说事物可以配成一对，形容小猫的样子要用“可爱”。"}, {"text": "他对应了我的道歉。", "explanation": "这里应该用〈接受〉。对应表示相符，不能用来表示接受别人的道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把锁有很对应的钥匙。", "corrected_sentence": "这把锁有对应的钥匙。", "error_description": "“对应”作定语表示相配，是不可分级的属性，不能被“很”修饰。应去掉“很”，说“有对应的钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请找出和这张图片对应了的词。", "corrected_sentence": "请找出和这张图片对应的词。", "error_description": "错误：体标。“对应”在这里表示相配的属性，“和……对应的”作定语时不能加“了”。应去掉“了”，说“和这张图片对应的词”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9a5a512-d259-4887-925a-718d1f003325') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
