INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27710, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把办法、制度等付诸实施，让很多人照着去做。", "primary_collocate": null, "pronunciation": "tuī xíng", "ipa": "tʰu̯eɪ˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "学校从下个月开始推行新规定。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府推行垃圾分类已经两年了。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算在全国推行这个办法。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家推行了免费上学的政策。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在班里推行早读制度。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项制度很难推行，因为很多人不同意。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里正在推行新的交通规则。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区推行了节约用水的办法。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长想在学校推行每天运动一小时。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要在农村推行新的医疗办法。", "target_word": "推行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词推行：把办法、制度等拿出来让大家一起做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27710, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推行", "is_correct": true, "explanation": "“推行”指把办法、制度让大家一起施行，与“新规定”搭配，句意通顺。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，不能带宾语“新规定”。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动、会议，不能说“参加新规定”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用来指“规定”，句意不通。"}], "explanations": {"推行": "“推行”指把办法、制度让大家一起施行，与“新规定”搭配，句意通顺。", "出发": "配价：“出发”是不及物动词，不能带宾语“新规定”。", "参加": "搭配：“参加”的对象是活动、会议，不能说“参加新规定”。", "吃": "搭配：“吃”的对象是食物，不能用来指“规定”，句意不通。"}, "sentence_index": 0, "correct_answer": "推行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司推行了新的手机，很多人都买了。", "explanation": "这里应该用〈推广〉。推行用于制度、办法，产品的宣传要用“推广”。"}, {"text": "我们正在推行一项调查。", "explanation": "这里应该用〈进行〉。推行指让很多人施行制度或办法，一次调查要用“进行”。"}, {"text": "这家店推行了很多新衣服。", "explanation": "这里应该用〈推销〉。推行用于制度、办法，卖东西要用“推销”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27710, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推行", "is_correct": true, "explanation": "“推行”指把办法、制度让大家一起施行，与“新的交通规则”搭配，句意通顺。"}, {"text": "眺望", "is_correct": false, "explanation": "搭配：“眺望”的对象是风景，不能说“眺望新的交通规则”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带宾语“新的交通规则”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱新的交通规则”，句意不通。"}], "explanations": {"推行": "“推行”指把办法、制度让大家一起施行，与“新的交通规则”搭配，句意通顺。", "眺望": "搭配：“眺望”的对象是风景，不能说“眺望新的交通规则”。", "散步": "配价：“散步”是不及物动词，不能带宾语“新的交通规则”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱新的交通规则”，句意不通。"}, "sentence_index": 6, "correct_answer": "推行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推行了自己的理想，终于当上了医生。", "explanation": "这里应该用〈实现〉。推行指让大家一起施行办法或制度，个人的理想要用“实现”。"}, {"text": "这件事推行了很大的进展。", "explanation": "这里应该用〈取得〉。“进展”常和“取得”搭配，推行只用于办法或制度。"}, {"text": "我们推行了一份合同，大家都签了字。", "explanation": "这里应该用〈签订〉。推行用于制度、办法，合同要用“签订”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府没推行了新的停车规定。", "corrected_sentence": "市政府推行了新的停车规定。", "error_description": "“没”是否定词，不能与动态助词“了”同时用在同一个动词上。“没推行了”应改为“推行了”，去掉“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们社区不有推行这个办法。", "corrected_sentence": "我们社区没有推行这个办法。", "error_description": "表示否定已发生时要用“没有”，“不有”不能这样说。“不有推行”应改为“没有推行”，只替换否定词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
