INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责带领团队完成项目的人。", "primary_collocate": null, "pronunciation": "xiàng mù jīng lǐ", "ipa": "ɕjɑŋ˥˩ mu˥˩ tɕiŋ˥ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "我们的项目经理姓王。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一家小公司的项目经理。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理带着我们做新网站。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理对每个人都很客气。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天项目经理请大家吃饭。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好项目经理要会听别人说话。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当了五年项目经理。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理把任务写在白板上。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的项目经理比我年轻。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "项目经理最近很忙，常常加班。", "target_word": "项目经理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "項目經理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带领团队做完一个项目的人，强调带队的角色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51183fcd-ff4c-496a-b5ac-da5409e35aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27714, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "项目经理", "is_correct": true, "explanation": "正确。“姓王”的是带领团队的人，用“项目经理”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人，“姓王”只用于有姓名的人，句意不通。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是场所，不能有姓氏，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "配价：“姓”要求有姓名的人作主语，“空气”不能搭配。"}], "explanations": {"项目经理": "正确。“姓王”的是带领团队的人，用“项目经理”。", "石头": "语义：石头不是人，“姓王”只用于有姓名的人，句意不通。", "图书馆": "语义：图书馆是场所，不能有姓氏，句意不通。", "空气": "配价：“姓”要求有姓名的人作主语，“空气”不能搭配。"}, "sentence_index": 0, "correct_answer": "项目经理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的项目经理负责管理全公司的财务。", "explanation": "这里应该用〈财务经理〉。项目经理只带领一个项目的团队，管理全公司财务的是财务经理。"}, {"text": "项目经理每天开车送孩子们上学。", "explanation": "这里应该用〈校车司机〉。项目经理负责带领团队完成项目，不负责开车送学生。"}, {"text": "这支球队的项目经理很厉害。", "explanation": "这里应该用〈领队〉。项目经理指带领项目团队的人，不能用来称呼球队的负责人；球队的负责人应说“领队”或“教练”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "项目经理", "is_correct": true, "explanation": "正确。“当了五年”后接的是职务，用“项目经理”。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“当”后接职务，不接疾病，“当了五年感冒”不成立。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“当”后接职务，不接天气，“当了五年天气”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是可以担任的职务，句意不通。"}], "explanations": {"项目经理": "正确。“当了五年”后接的是职务，用“项目经理”。", "感冒": "搭配：“当”后接职务，不接疾病，“当了五年感冒”不成立。", "天气": "搭配：“当”后接职务，不接天气，“当了五年天气”不成立。", "体重": "语义：体重是身体的重量，不是可以担任的职务，句意不通。"}, "sentence_index": 6, "correct_answer": "项目经理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位项目经理每天查房。", "explanation": "这里应该用〈医生〉。项目经理不负责查房，查房的是医生。"}, {"text": "项目经理每天检查学生的作业。", "explanation": "这里应该用〈班主任〉。项目经理不管理学生的作业，检查作业的是班主任。"}, {"text": "项目经理每天准备早餐。", "explanation": "这里应该用〈厨师〉。项目经理不负责做饭，准备早餐的是厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只项目经理很负责。", "corrected_sentence": "这位项目经理很负责。", "error_description": "量词错误：指人的职位要用“位”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她过做项目经理。", "corrected_sentence": "她做过项目经理。", "error_description": "体标位置错误：“过”应紧跟动词“做”，说“做过项目经理”，不说“过做项目经理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a784231-bc12-437b-9e17-f1105c73ffc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
