INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "就是不同意，心里觉得不喜欢。", "primary_collocate": null, "pronunciation": "dǐ chù", "ipa": "ti²¹⁴ tʂʰu⁵¹", "syllable_count": 2, "sentences": [{"text": "他很抵触吃药，每次都不想吃。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟抵触去上学，早上不肯起床。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这件事有点抵触，不想参加。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈叫他学钢琴，他心里很抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多孩子抵触写作业，觉得没意思。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抵触搬家，因为舍不得朋友。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话太凶，学生都很抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直抵触别人的建议，觉得自己是对的。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不抵触学新东西，只是需要一点时间。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到要加班，大家心里都有些抵触。", "target_word": "抵触", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵触了", "label": "体标"}, {"form": "抵触情绪", "label": "复合"}], "register": "中性", "sense_fingerprint": "抵触：心里不喜欢、不愿意接受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '620cf61b-9fe1-441f-be7f-b8453433329c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触（dǐchù）：心里不喜欢，不愿意接受。"}, {"text": "低处", "is_correct": false, "explanation": "低处（dīchù）与抵触只有第一个音节声调不同：低为第一声，抵为第三声，意思是低的地方。"}, {"text": "地处", "is_correct": false, "explanation": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。"}, {"text": "递出", "is_correct": false, "explanation": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。"}, {"text": "抵住", "is_correct": false, "explanation": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}], "explanations": {"抵触": "抵触（dǐchù）：心里不喜欢，不愿意接受。", "低处": "低处（dīchù）与抵触只有第一个音节声调不同：低为第一声，抵为第三声，意思是低的地方。", "地处": "地处（dìchǔ）与抵触的两个音节声调都不同：地为第四声，处为第三声，意思是位于某地。", "递出": "递出（dìchū）与抵触的两个音节声调都不同：递为第四声，出为第一声，意思是交给别人。", "抵住": "抵住（dǐzhù）与抵触只有第二个音节的声母不同：zh 与 ch 不同，意思是顶住、挡住。"}, "sentence_index": null, "correct_answer": "抵触"}, "level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：心里反感、不愿接受，与“每次都不想吃”相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“很喜欢吃药”与后半句“每次都不想吃”的意思相矛盾。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“很习惯吃药”与“每次都不想吃”相矛盾，不符合语境。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说“享受吃药”。"}], "explanations": {"抵触": "抵触：心里反感、不愿接受，与“每次都不想吃”相符。", "喜欢": "语义：“很喜欢吃药”与后半句“每次都不想吃”的意思相矛盾。", "习惯": "语义：“很习惯吃药”与“每次都不想吃”相矛盾，不符合语境。", "享受": "搭配：“享受”多搭配生活、待遇，不说“享受吃药”。"}, "sentence_index": 0, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车队终于抵触了终点站。", "explanation": "这里应该用〈抵达〉。抵达表示到达某地，抵触表示矛盾或抗拒，不能用于地点。"}, {"text": "他用汽车抵触了这笔借款。", "explanation": "这里应该用〈抵押〉。抵押是以财产作担保，抵触没有这个意思。"}, {"text": "他用手抵触了迎面的风雪。", "explanation": "这里应该用〈抵挡〉。抵挡是用身体挡住东西，抵触表示矛盾或抗拒，不表示挡住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵触", "is_correct": true, "explanation": "抵触：心里不愿接受、反感，与“学生都很”的语境相符。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“老师说话太凶”之后，“学生都很感激”与语境相矛盾。"}, {"text": "信任", "is_correct": false, "explanation": "语义：说话太凶的老师不会让学生“信任”，与语境相矛盾。"}, {"text": "敬佩", "is_correct": false, "explanation": "语义：老师说话太凶，学生不会因此“敬佩”，与语境相矛盾。"}], "explanations": {"抵触": "抵触：心里不愿接受、反感，与“学生都很”的语境相符。", "感激": "语义：“老师说话太凶”之后，“学生都很感激”与语境相矛盾。", "信任": "语义：说话太凶的老师不会让学生“信任”，与语境相矛盾。", "敬佩": "语义：老师说话太凶，学生不会因此“敬佩”，与语境相矛盾。"}, "sentence_index": 6, "correct_answer": "抵触"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要抵触洪水的侵袭。", "explanation": "这里应该用〈抵御〉。抵御指挡住外来的侵袭，抵触只表示矛盾或抗拒，不能用于抵挡洪水。"}, {"text": "他想用钱抵触这次损失。", "explanation": "这里应该用〈抵偿〉。抵偿指用钱或物补偿损失，抵触没有补偿的意思。"}, {"text": "工资可以抵触税款。", "explanation": "这里应该用〈抵扣〉。抵扣指互相冲抵后扣除，抵触没有这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把抵触去医院，一听到就皱眉。", "corrected_sentence": "他很抵触去医院，一听到就皱眉。", "error_description": "错误：“把”字句要求宾语被处置，“把抵触”不成立，应改为直接作谓语。正确说法：“他很抵触去医院，一听到就皱眉。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候抵触过了打针，现在已经不怕了。", "corrected_sentence": "我小时候抵触过打针，现在已经不怕了。", "error_description": "错误：“过”与“了”不能同时用在同一动词后表示经历。正确说法：“我小时候抵触过打针，现在已经不怕了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c7dedf-efee-4ec3-b050-7b60410f0fd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有", "is_correct": true, "explanation": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。"}, {"text": "吃", "is_correct": false, "explanation": "吃是进食的动作，与“无”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看是视觉动作，与“无”没有反义关系。"}, {"text": "说", "is_correct": false, "explanation": "说是言语动作，与“无”没有反义关系。"}], "correct_answer": "有", "explanations": {"有": "有：与“无”相对，表示存在、具有，是“无”（没有）的反义词。", "吃": "吃是进食的动作，与“无”没有反义关系。", "看": "看是视觉动作，与“无”没有反义关系。", "说": "说是言语动作，与“无”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
