INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有", "primary_collocate": null, "pronunciation": "wú", "ipa": "u˧˥", "syllable_count": 1, "sentences": [{"text": "这个房间无窗，白天也要开灯。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一人在家，屋里无其他人。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边无车，行人可以放心过街。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校无游泳池，学生去外面游泳。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇无商店，买东西很不方便。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家无电视，晚上全家人一起看书。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子无空调，夏天特别热。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她包里无手机，无法给你打电话。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个湖无鱼，湖水清得能看到底。", "target_word": "无", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天无风，树叶一动也不动。", "target_word": "无", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "無", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "无：没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 3 words above tier T1 (max 2): 他家 (Zipf 3.99), 全家人 (Zipf 3.47), 看书 (Zipf 3.84)']::text[], '11fef44c-77a9-473d-bd53-ecd3ab0c912e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有。"}, {"text": "武", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。"}, {"text": "屋", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。"}, {"text": "乌", "is_correct": false, "explanation": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。"}, {"text": "务", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}], "explanations": {"无": "无 wú，意思是没有。", "武": "wǔ（第三声）与 wú（第二声）声调不同，意思是武术、武力。", "屋": "wū（第一声）与 wú（第二声）声调不同，意思是房屋。", "乌": "wū（第一声）与 wú（第二声）声调不同，意思是乌鸦、黑色。", "务": "wù（第四声）与 wú（第二声）声调不同，意思是事务、务必。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无窗”表示没有窗户，与“白天也要开灯”构成因果，句意通顺。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修窗”指修理窗户，与房间没有窗户的意思不合。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦窗”指清洁窗户，“这个房间擦窗”与句意不符。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔窗”指把窗户摔坏，与句子的意思无关。"}], "explanations": {"无": "无：“无窗”表示没有窗户，与“白天也要开灯”构成因果，句意通顺。", "修": "语义：“修窗”指修理窗户，与房间没有窗户的意思不合。", "擦": "搭配：“擦窗”指清洁窗户，“这个房间擦窗”与句意不符。", "摔": "语义：“摔窗”指把窗户摔坏，与句子的意思无关。"}, "sentence_index": 0, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "无论天气怎么样，我们都去操场跑步。", "explanation": "这里的“无论”是连词，“无”并不表示“没有”，应用〈不管〉。"}, {"text": "他无非是想引起大家的注意。", "explanation": "这里的“无非”是副词，表示“只不过”，“无”并不表示“没有”，应用〈只是〉。"}, {"text": "我们去无锡参观，那里的园林很有名。", "explanation": "这里的“无”属于地名“无锡”的一部分，与“没有”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "无", "is_correct": true, "explanation": "无 wú，意思是没有。"}, {"text": "五", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。"}, {"text": "午", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。"}, {"text": "舞", "is_correct": false, "explanation": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。"}, {"text": "雾", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。"}, {"text": "悟", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。"}], "explanations": {"无": "无 wú，意思是没有。", "五": "wǔ（第三声）与 wú（第二声）声调不同，意思是数字五。", "午": "wǔ（第三声）与 wú（第二声）声调不同，意思是中午。", "舞": "wǔ（第三声）与 wú（第二声）声调不同，意思是跳舞。", "雾": "wù（第四声）与 wú（第二声）声调不同，意思是雾气。", "悟": "wù（第四声）与 wú（第二声）声调不同，意思是领会、醒悟。"}, "sentence_index": null, "correct_answer": "无"}, "level_3": {"options": [{"text": "无", "is_correct": true, "explanation": "无：“无空调”表示没有空调，与“夏天特别热”因果相连，句意通顺。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装空调”指安装空调，与“夏天特别热”的因果不通，句意矛盾。"}, {"text": "推", "is_correct": false, "explanation": "搭配：“推”一般带车、门等物体，不能与“空调”搭配作宾语。"}, {"text": "掉", "is_correct": false, "explanation": "配价：“掉”一般不带“空调”这样的宾语，不能说“掉空调”。"}], "explanations": {"无": "无：“无空调”表示没有空调，与“夏天特别热”因果相连，句意通顺。", "装": "语义：“装空调”指安装空调，与“夏天特别热”的因果不通，句意矛盾。", "推": "搭配：“推”一般带车、门等物体，不能与“空调”搭配作宾语。", "掉": "配价：“掉”一般不带“空调”这样的宾语，不能说“掉空调”。"}, "sentence_index": 6, "correct_answer": "无"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无论大人还是小孩，都喜欢这个游戏。", "explanation": "这里的“无论”是连词，“无”并不表示“没有”，应用〈不论〉。"}, {"text": "这件事无非是个误会，大家别太在意。", "explanation": "这里的“无非”是副词，表示“只不过”，“无”并不表示“没有”，应用〈只是〉。"}, {"text": "我的表哥住在无锡，他常来看我。", "explanation": "这里的“无”属于地名“无锡”的一部分，与“没有”的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个路口无过红绿灯，司机要特别小心。", "corrected_sentence": "这个路口无红绿灯，司机要特别小心。", "error_description": "“无”后面不能加“过”。表示没有某物时直接说“无红绿灯”，不用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛无了汽车，人们都骑自行车。", "corrected_sentence": "这座岛无汽车，人们都骑自行车。", "error_description": "“无”后面不能加“了”。表示没有某物时直接说“无汽车”，不用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ffdaa90-3a39-4aa2-b173-382c07cf3c61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
