INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27720, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能让人开心或觉得好玩的。", "primary_collocate": null, "pronunciation": "yǒu qù", "ipa": "joʊ˨˩˦ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "这本书很有趣，我一天就看完了。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的故事非常有趣，大家都笑了。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏一点也不有趣。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去了一个有趣的地方。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的朋友真有趣，我喜欢和他聊天。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影有趣极了，孩子们看得很开心。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的课很有趣，学生都爱听。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得学做饭是一件有趣的事。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗的动作很有趣。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个有趣的人，总能让大家开心。", "target_word": "有趣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有趣的", "label": "定语形式"}, {"form": "有趣极了", "label": "程度补语"}], "register": "中性", "sense_fingerprint": "让人觉得好玩、愿意看或听的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27720, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有趣", "is_correct": true, "explanation": "正确。有趣指让人觉得好玩，“这本书很有趣”符合语境。"}, {"text": "冷", "is_correct": false, "explanation": "语义：冷指温度低，书不能说“很冷”。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：咸用于说味道，不用来形容书。"}, {"text": "吵", "is_correct": false, "explanation": "语义：吵指声音杂乱，不能用来形容书的内容。"}], "explanations": {"有趣": "正确。有趣指让人觉得好玩，“这本书很有趣”符合语境。", "冷": "语义：冷指温度低，书不能说“很冷”。", "咸": "搭配：咸用于说味道，不用来形容书。", "吵": "语义：吵指声音杂乱，不能用来形容书的内容。"}, "sentence_index": 0, "correct_answer": "有趣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种运动对身体有趣。", "explanation": "这里应该用〈有益〉。有趣指让人觉得好玩，说对身体的好处要用有益。"}, {"text": "这种药对治病很有趣。", "explanation": "这里应该用〈有效〉。有趣指让人觉得好玩，说治病的效果要用有效。"}, {"text": "他的病很有趣，需要住院治疗。", "explanation": "这里应该用〈严重〉。有趣指让人觉得好玩，说病情的程度要用严重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有趣", "is_correct": true, "explanation": "正确。有趣指让人觉得好玩，“老师的课很有趣”符合语境。"}, {"text": "轻", "is_correct": false, "explanation": "语义：轻指重量小，不能用来形容课。"}, {"text": "绿", "is_correct": false, "explanation": "语义：绿是颜色，不能用来形容课。"}, {"text": "脏", "is_correct": false, "explanation": "搭配：脏多用于说卫生状况，不用来形容课。"}], "explanations": {"有趣": "正确。有趣指让人觉得好玩，“老师的课很有趣”符合语境。", "轻": "语义：轻指重量小，不能用来形容课。", "绿": "语义：绿是颜色，不能用来形容课。", "脏": "搭配：脏多用于说卫生状况，不用来形容课。"}, "sentence_index": 6, "correct_answer": "有趣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故的伤亡很有趣，需要紧急救援。", "explanation": "这里应该用〈惨重〉。有趣指让人觉得好玩，说伤亡的程度要用惨重。"}, {"text": "这瓶饮料有趣，千万别喝。", "explanation": "这里应该用〈有毒〉。有趣指让人觉得好玩，说饮料对人有害要用有毒。"}, {"text": "他被判有趣，要坐牢了。", "explanation": "这里应该用〈有罪〉。有趣指让人觉得好玩，法院认定罪行要用有罪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一本有趣书。", "corrected_sentence": "他买了一本有趣的书。", "error_description": "定语：“有趣”修饰名词时要加“的”，写成“有趣书”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行有趣极了了。", "corrected_sentence": "这次旅行有趣极了。", "error_description": "多余的“了”。“有趣极了”是固定格式，“极”表示程度，后面只用一个“了”，写成“有趣极了了”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "正确：“合成”与“分解”构成反义，表示把若干部分组合成一个整体。"}, {"text": "保持", "is_correct": false, "explanation": "语义：“保持”表示使某种状态不变，与“分解”的意义没有反义关系。"}, {"text": "进行", "is_correct": false, "explanation": "语义：“进行”表示持续做某事，与“分解”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”表示仔细看，与“分解”没有反义关系。"}], "correct_answer": "合成", "explanations": {"合成": "正确：“合成”与“分解”构成反义，表示把若干部分组合成一个整体。", "保持": "语义：“保持”表示使某种状态不变，与“分解”的意义没有反义关系。", "进行": "语义：“进行”表示持续做某事，与“分解”没有反义关系。", "观察": "语义：“观察”表示仔细看，与“分解”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合成", "is_correct": true, "explanation": "正确：“合成”与“分解”构成反义，表示把部分合为整体。"}, {"text": "收集", "is_correct": false, "explanation": "语义：“收集”表示聚集、搜罗，与“分解”没有反义关系。"}, {"text": "留下", "is_correct": false, "explanation": "语义：“留下”表示让某物留存，与“分解”没有反义关系。"}, {"text": "发现", "is_correct": false, "explanation": "语义：“发现”表示找到或察觉，与“分解”没有反义关系。"}], "correct_answer": "合成", "explanations": {"合成": "正确：“合成”与“分解”构成反义，表示把部分合为整体。", "收集": "语义：“收集”表示聚集、搜罗，与“分解”没有反义关系。", "留下": "语义：“留下”表示让某物留存，与“分解”没有反义关系。", "发现": "语义：“发现”表示找到或察觉，与“分解”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西分成几个部分。", "primary_collocate": null, "pronunciation": "fēn jiě", "ipa": "fən˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们可以把这篇文章分解成四个段落。", "target_word": "分解", "complexity_tier": "T3", "furigana": "wǒ men kě yǐ bǎ zhè piān wén zhāng fēn jiě chéng sì gè duàn luò", "sentence_source": "generated"}, {"text": "我们把大任务分解成几个小任务。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划可以分解成几个步骤。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge jì huà kě yǐ fēn jiě chéng jǐ gè bù zhòu", "sentence_source": "generated"}, {"text": "老师把这个句子分解成三个部分。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目可以分解成三个阶段。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge xiàng mù kě yǐ fēn jiě chéng sān gè jiē duàn", "sentence_source": "generated"}, {"text": "这个问题太大，要先分解一下。", "target_word": "分解", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把旧机器分解了，再一件一件检查。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把复杂的动作分解给我们看。", "target_word": "分解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器可以分解成几个部分。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè tái jī qì kě yǐ fēn jiě chéng jǐ gè bù fen", "sentence_source": "generated"}, {"text": "这个汉字可以分解成两个部分。", "target_word": "分解", "complexity_tier": "T3", "furigana": "zhè ge hàn zì kě yǐ fēn jiě chéng liǎng gè bù fen", "sentence_source": "generated"}], "morphological_forms": [{"form": "分解了", "label": "体标"}, {"form": "分解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：把整体拆分成几个部分，常用“把A分解成B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c1a906-ea1f-4e51-bb2e-ae63d5c674b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分解", "is_correct": true, "explanation": "正确答案：fēn jiě，表示把整体分成几个部分。"}, {"text": "分界", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是划分界线。"}, {"text": "分节", "is_correct": false, "explanation": "jiě（第三声）与 jié（第二声）声调不同，意思是分成章节。"}, {"text": "分级", "is_correct": false, "explanation": "jí（第二声）与 jiě（第三声）读音相近但不同，意思是划分等级。"}], "explanations": {"分解": "正确答案：fēn jiě，表示把整体分成几个部分。", "分界": "jiě（第三声）与 jiè（第四声）声调不同，意思是划分界线。", "分节": "jiě（第三声）与 jié（第二声）声调不同，意思是分成章节。", "分级": "jí（第二声）与 jiě（第三声）读音相近但不同，意思是划分等级。"}, "sentence_index": null, "correct_answer": "分解"}, "level_3": {"options": [{"text": "分解", "is_correct": true, "explanation": "正确：“分解”表示把整篇文章拆成若干部分，与“分成四个段落”相合。"}, {"text": "分配", "is_correct": false, "explanation": "搭配：“分配”用于任务、资源等，不能用来指把文章划分为段落。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，“翻译成四个段落”说不通。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，不能用来指划分文章的段落。"}], "explanations": {"分解": "正确：“分解”表示把整篇文章拆成若干部分，与“分成四个段落”相合。", "分配": "搭配：“分配”用于任务、资源等，不能用来指把文章划分为段落。", "翻译": "语义：“翻译”指转换语言，“翻译成四个段落”说不通。", "烧": "语义：“烧”指燃烧，不能用来指划分文章的段落。"}, "sentence_index": 0, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和女朋友分解了。", "explanation": "这里应该用〈分手〉。“分解”指把事物拆成部分，不能用于人与人关系的结束。"}, {"text": "我们分解了三年没见面。", "explanation": "这里应该用〈分开〉。“分解”强调把整体拆成部分，不能用于人与人长期分离。"}, {"text": "我们分解了快乐。", "explanation": "这里应该用〈分享〉。“分解”指把具体的整体拆开，不能用于抽象的快乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指喜爱地看，与“一件一件检查”的拆解工作不符。"}, {"text": "信任", "is_correct": false, "explanation": "搭配：“信任”的对象通常是人，不能用于“旧机器”。"}, {"text": "分解", "is_correct": true, "explanation": "正确：“分解”表示把机器拆成部件，与“一件一件检查”相合。"}, {"text": "迷恋", "is_correct": false, "explanation": "语义：“迷恋”指深深喜爱，与“拆开检查旧机器”的动作不符。"}], "explanations": {"欣赏": "语义：“欣赏”指喜爱地看，与“一件一件检查”的拆解工作不符。", "信任": "搭配：“信任”的对象通常是人，不能用于“旧机器”。", "分解": "正确：“分解”表示把机器拆成部件，与“一件一件检查”相合。", "迷恋": "语义：“迷恋”指深深喜爱，与“拆开检查旧机器”的动作不符。"}, "sentence_index": 6, "correct_answer": "分解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的爱情很快就分解了。", "explanation": "这里应该用〈破裂〉。“分解”指把具体事物拆成部分，不能用于感情关系的破裂。"}, {"text": "这场比赛把我分解得很累。", "explanation": "这个词不这么用。“分解”指把事物拆成部分，不能表示使人感到疲惫。"}, {"text": "我们分解了一个晚上的海浪。", "explanation": "这里应该用〈看〉。海浪是流动的整体，不能“分解”；“分解”的宾语应是可以拆分成部分的具体事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们可以把计划分解几个步骤。", "corrected_sentence": "我们可以把计划分解成几个步骤。", "error_description": "错误：“分解”要接“成”引出分成的结果，应说“分解成几个步骤”，不能省略“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师把机器分解了成几个部分。", "corrected_sentence": "工程师把机器分解成几个部分。", "error_description": "错误：“分解”后接“成”引出结果，两者之间不能加“了”。应说“工程师把机器分解成几个部分。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
