INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "责任就是你应该做的事情，或者做错了事情要承担的后果。", "primary_collocate": null, "pronunciation": "zé rèn", "ipa": "tsɤ³⁵ ʐən⁵¹", "syllable_count": 2, "sentences": [{"text": "照顾孩子是父母的责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事我也有责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次错误的责任在我。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师有责任帮助学生。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "保护环境是每个人的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想承担这个责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司应该负起自己的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为班长，他的责任很大。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这不是你一个人的责任。", "target_word": "责任", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子长大了，也要有自己的责任。", "target_word": "责任", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "责任心", "label": "复合"}, {"form": "责任感", "label": "复合"}], "register": "中性", "sense_fingerprint": "应尽的义务；出错后要承担的后果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '449b634c-ae74-4ccb-8934-b82cc0828b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食物", "is_correct": false, "explanation": "语义：食物是可以吃的东西，照顾孩子不是父母的食物。"}, {"text": "面貌", "is_correct": false, "explanation": "语义：“面貌”指外表形象，照顾孩子不属于父母的外表。"}, {"text": "责任", "is_correct": true, "explanation": "正确：照顾孩子是父母应尽的义务，与句意相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是用来演奏的器具，与照顾孩子无关。"}], "explanations": {"食物": "语义：食物是可以吃的东西，照顾孩子不是父母的食物。", "面貌": "语义：“面貌”指外表形象，照顾孩子不属于父母的外表。", "责任": "正确：照顾孩子是父母应尽的义务，与句意相符。", "乐器": "语义：“乐器”是用来演奏的器具，与照顾孩子无关。"}, "sentence_index": 0, "correct_answer": "责任"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犯了一个责任。", "explanation": "这里应该用〈过失〉。犯错要说犯过失或错误，“责任”是应尽的义务，不能说犯责任。"}, {"text": "学校举办了一个责任。", "explanation": "这里应该用〈活动〉。举办的是活动、比赛，“责任”不能被举办。"}, {"text": "我们参加了一次责任。", "explanation": "这里应该用〈考试〉。参加的是考试、比赛等活动，“责任”不能被参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "配价：“负起”要求的宾语是责任、义务一类，不能是“名字”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不与“负起”搭配，说“负起自己的颜色”不通。"}, {"text": "责任", "is_correct": true, "explanation": "责任：“负起责任”是固定搭配，表示承担应尽的义务。"}, {"text": "利益", "is_correct": false, "explanation": "搭配：“利益”一般说维护或争取，不与“负起”搭配。"}], "explanations": {"名字": "配价：“负起”要求的宾语是责任、义务一类，不能是“名字”。", "颜色": "搭配：“颜色”不与“负起”搭配，说“负起自己的颜色”不通。", "责任": "责任：“负起责任”是固定搭配，表示承担应尽的义务。", "利益": "搭配：“利益”一般说维护或争取，不与“负起”搭配。"}, "sentence_index": 6, "correct_answer": "责任"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他洗了一个责任。", "explanation": "这里应该用〈衣服〉。洗的是衣物，“责任”是抽象的义务，不能被洗。"}, {"text": "他发表了一个责任。", "explanation": "这里应该用〈文章〉。发表的是文章、言论，“责任”不能被发表。"}, {"text": "他修理了一个责任。", "explanation": "这里应该用〈自行车〉。修理的是器物，“责任”是抽象的义务，不能被修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些责任们都要由他负责。", "corrected_sentence": "这些责任都要由他负责。", "error_description": "错误形式：“责任们”；正确形式：“责任”。“们”只用于指人，不能加在抽象名词“责任”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他接受了一只新的责任。", "corrected_sentence": "他接受了一份新的责任。", "error_description": "错误形式：“一只责任”；正确形式：“一份责任”。“只”是用于动物的量词，“责任”要用“份”或“项”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7689b5b-a5f5-45f7-b2bf-f7588a33bad6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
