INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27726, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公民就是具有某个国家国籍，享有权利并承担义务的人。", "primary_collocate": null, "pronunciation": "gōng mín", "ipa": "kʊŋ˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "每个公民都要遵守法律。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是中国公民，住在北京。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民有权利去投票。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经成了这个国家的公民。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好公民会帮助别人。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民可以对政府提意见。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位公民看到小偷，马上报了警。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去年入了法国籍，现在是法国公民。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民应该关心自己的城市。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做一个有责任的公民不容易。", "target_word": "公民", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位公民", "label": "量词"}, {"form": "公民们", "label": "复合"}], "register": "书面", "sense_fingerprint": "公民：具有一国国籍、享有权利并承担义务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ce010c66-d877-4df7-8147-8f6d54c7cf13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公民", "is_correct": true, "explanation": "正确答案，即「公民」，gōng mín。"}, {"text": "功名", "is_correct": false, "explanation": "gōngmíng 韵尾不同（ng 与 n），意思是功绩和名声。"}, {"text": "宫门", "is_correct": false, "explanation": "韵母不同（gōngmén 的 en 与 gōngmín 的 in），意思是宫殿的大门。"}, {"text": "公明", "is_correct": false, "explanation": "gōngmíng 第二个音节韵尾不同（ng 与 n），意思是公正无私。"}], "explanations": {"公民": "正确答案，即「公民」，gōng mín。", "功名": "gōngmíng 韵尾不同（ng 与 n），意思是功绩和名声。", "宫门": "韵母不同（gōngmén 的 en 与 gōngmín 的 in），意思是宫殿的大门。", "公明": "gōngmíng 第二个音节韵尾不同（ng 与 n），意思是公正无私。"}, "sentence_index": null, "correct_answer": "公民"}, "level_3": {"options": [{"text": "公民", "is_correct": true, "explanation": "正确。句中“每个……都要遵守法律”指具有国籍、享有权利的人，应填「公民」。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：「房屋」是建筑物，不能“遵守法律”。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：「钢笔」是文具，与“遵守法律”无关。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「石头」是无生命的物体，不能「遵守法律」，句意不通。"}], "explanations": {"公民": "正确。句中“每个……都要遵守法律”指具有国籍、享有权利的人，应填「公民」。", "房屋": "语义：「房屋」是建筑物，不能“遵守法律”。", "钢笔": "语义：「钢笔」是文具，与“遵守法律”无关。", "石头": "语义：「石头」是无生命的物体，不能「遵守法律」，句意不通。"}, "sentence_index": 0, "correct_answer": "公民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在院子里种了一个公民。", "explanation": "这里应该用〈树〉。「种」的对象是植物，「公民」指人，不能种。"}, {"text": "院子里有一只公民，它在草地上跑来跑去。", "explanation": "这里应该用〈小狗〉。「公民」指有国籍的人，不能用来指动物。"}, {"text": "我们昨天把公民寄到了北京。", "explanation": "这里应该用〈包裹〉。「寄」的对象是包裹、信件等物品，「公民」指人，不能寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公民", "is_correct": true, "explanation": "正确。句中“看到小偷，马上报了警”需要一个能看见并报警的人，应填「公民」。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：「婴儿」不会看到小偷并报警，句意不通。"}, {"text": "盲人", "is_correct": false, "explanation": "语义：「盲人」看不见，不能“看到小偷”。"}, {"text": "人群", "is_correct": false, "explanation": "搭配：「人群」是集合名词，不能与“一位”搭配，也不能单独报警。"}], "explanations": {"公民": "正确。句中“看到小偷，马上报了警”需要一个能看见并报警的人，应填「公民」。", "婴儿": "语义：「婴儿」不会看到小偷并报警，句意不通。", "盲人": "语义：「盲人」看不见，不能“看到小偷”。", "人群": "搭配：「人群」是集合名词，不能与“一位”搭配，也不能单独报警。"}, "sentence_index": 6, "correct_answer": "公民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天骑着公民去上班。", "explanation": "这里应该用〈自行车〉。「骑」的对象是车辆或动物，「公民」指人，不能骑。"}, {"text": "他把公民修好了。", "explanation": "这里应该用〈电脑〉。「修」的对象是机器、设备等物品，「公民」指人，不能修。"}, {"text": "这家公司的公民很多，都很努力。", "explanation": "这里应该用〈员工〉。「公民」指国民身份，公司里工作的人应该说「员工」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我是一只中国公民。", "corrected_sentence": "我是一名中国公民。", "error_description": "量词错误：应为「一名中国公民」。「只」用于动物，指人要用「名」或「位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他现在已经有法国公民了。", "corrected_sentence": "他现在已经是法国公民了。", "error_description": "动词误用：「有法国公民」应为「是法国公民」。说一个人的身份要用「是」，不能用「有」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16782303-5f5e-466a-b0d1-aa2aa443e529') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
