INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起做一件事，每人做一部分。", "primary_collocate": null, "pronunciation": "fēn dān", "ipa": "fən˥ tan˥", "syllable_count": 2, "sentences": [{"text": "打扫教室时，每个同学分担一部分。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个项目由三个人分担。", "target_word": "分担", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们分担了做饭和洗碗的工作。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家的活儿，大家一起分担吧。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次演出的准备工作，我们平均分担。", "target_word": "分担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让每个小组分担一项任务。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们分担着照顾老人的工作。", "target_word": "分担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的家务，我和姐姐一起分担。", "target_word": "分担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多活儿，一个人做不完，要大家分担。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，队员们分担了不同的准备工作。", "target_word": "分担", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "分担了", "label": "体标"}, {"form": "分担过", "label": "体标"}, {"form": "分担着", "label": "体标"}, {"form": "分擔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一件事由多人分工，每人负责其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eddf536e-727f-466d-9471-e2a4e4949a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：每个同学分工负责其中一部分，符合语境。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是不及物动作，不能说“睡一部分”，与打扫分工无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与打扫教室的分工无关。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”不能表示分担工作，与语境不合。"}], "explanations": {"分担": "正确：每个同学分工负责其中一部分，符合语境。", "睡": "语义：“睡”是不及物动作，不能说“睡一部分”，与打扫分工无关。", "唱": "语义：“唱”与打扫教室的分工无关。", "跳": "语义：“跳”不能表示分担工作，与语境不合。"}, "sentence_index": 0, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们分担了这场比赛。", "explanation": "这里应该用〈参加〉。分担指多人分工做一件事，参加比赛不能说分担。"}, {"text": "大家一起分担这块蛋糕。", "explanation": "这里应该用〈分享〉。分担用于工作、责任、费用，分享食物要用〈分享〉。"}, {"text": "我们分担了那座公园。", "explanation": "这里应该用〈游览〉。分担的宾语是工作或费用，不能是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分担", "is_correct": true, "explanation": "正确：“分担着照顾老人的工作”指多人分工，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与分工承担的语境相反，不符合句意。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”不能用来描述承担工作，与句意不合。"}, {"text": "买", "is_correct": false, "explanation": "语义：工作不能“买”，“买着照顾老人的工作”不成立。"}], "explanations": {"分担": "正确：“分担着照顾老人的工作”指多人分工，符合语境。", "拒绝": "语义：“拒绝”与分工承担的语境相反，不符合句意。", "忘记": "语义：“忘记”不能用来描述承担工作，与句意不合。", "买": "语义：工作不能“买”，“买着照顾老人的工作”不成立。"}, "sentence_index": 6, "correct_answer": "分担"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们分担了那座博物馆。", "explanation": "这里应该用〈参观〉。分担的宾语是工作或责任，不能指参观的地点。"}, {"text": "我们分担了这本书。", "explanation": "这里应该用〈阅读〉。分担不能用于书籍，读书要用〈阅读〉。"}, {"text": "队员们分担了那位教练。", "explanation": "这里应该用〈陪伴〉。分担的宾语不能是人，陪伴教练要用〈陪伴〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们分担了打扫房间的一只工作。", "corrected_sentence": "我们分担了打扫房间的一项工作。", "error_description": "错误在于量词“只”。“只”多用于动物或成对器物中的一个，不能修饰“工作”；“工作”可用“项”或“件”，应说“一项工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们平分分担了这些任务。", "corrected_sentence": "他们平均分担了这些任务。", "error_description": "错误形式“平分分担”，正确形式“平均分担”。“平分”与“分担”意思重复，表示按份额均等承担应用“平均”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ead0f57e-393d-43ff-b200-52770069b672') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
