INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27730, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做玩电脑或手机游戏这件事。", "primary_collocate": null, "pronunciation": "wán yóu xì", "ipa": "wan˧˥ joʊ˧˥ ɕi˥˩", "syllable_count": 3, "sentences": [{"text": "我弟弟喜欢在手机上玩游戏。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上我常常和朋友玩游戏。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子写完作业才可以玩游戏。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天玩游戏玩到很晚。", "target_word": "玩游戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈说不能一直玩游戏。", "target_word": "玩游戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们在家玩游戏，不出去。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你喜欢在电脑上玩游戏吗？", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，我们只好在房间里玩游戏。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天玩游戏玩了三个小时。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同学喜欢玩游戏，不喜欢看书。", "target_word": "玩游戏", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "玩游戏", "label": "原形"}, {"form": "玩玩游戏", "label": "重叠"}, {"form": "玩了游戏", "label": "体标"}], "register": "中性", "sense_fingerprint": "在电脑或手机上玩电子游戏，用来休息或娱乐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27730, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩游戏", "is_correct": true, "explanation": "正确。“玩游戏”指在手机上做电子游戏，与“在手机上”搭配自然。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“在手机上睡觉”不合常理，手机上不能睡觉。"}, {"text": "种花", "is_correct": false, "explanation": "语义：“在手机上种花”不合常理，花要种在土里。"}, {"text": "吃游戏", "is_correct": false, "explanation": "搭配：“吃”不能带“游戏”作宾语，“吃游戏”说不通。"}], "explanations": {"玩游戏": "正确。“玩游戏”指在手机上做电子游戏，与“在手机上”搭配自然。", "睡觉": "语义：“在手机上睡觉”不合常理，手机上不能睡觉。", "种花": "语义：“在手机上种花”不合常理，花要种在土里。", "吃游戏": "搭配：“吃”不能带“游戏”作宾语，“吃游戏”说不通。"}, "sentence_index": 0, "correct_answer": "玩游戏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在工厂玩游戏，忙到很晚。", "explanation": "这里应该用〈上班〉。玩游戏指做电子游戏，不能用来表示在工厂上班，句中“忙到很晚”也与“玩”的意思冲突。"}, {"text": "妈妈每天在菜市场玩游戏，生意做到很晚。", "explanation": "这里应该用〈卖菜〉。玩游戏指做电子游戏，不能用来表示在菜市场卖东西。"}, {"text": "他每天在医院玩游戏，手术做到很晚。", "explanation": "这里应该用〈动手术〉。玩游戏指做电子游戏，不能用来表示给病人做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27730, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩游戏", "is_correct": true, "explanation": "正确。“玩游戏”指在电脑上做电子游戏，与“喜欢”搭配自然。"}, {"text": "喝汤", "is_correct": false, "explanation": "语义：“在电脑上喝汤”不合常理，电脑上不能喝汤。"}, {"text": "切菜", "is_correct": false, "explanation": "语义：“在电脑上切菜”不合常理，切菜要在厨房进行。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“在电脑上洗澡”不合常理，洗澡要在浴室进行。"}], "explanations": {"玩游戏": "正确。“玩游戏”指在电脑上做电子游戏，与“喜欢”搭配自然。", "喝汤": "语义：“在电脑上喝汤”不合常理，电脑上不能喝汤。", "切菜": "语义：“在电脑上切菜”不合常理，切菜要在厨房进行。", "洗澡": "语义：“在电脑上洗澡”不合常理，洗澡要在浴室进行。"}, "sentence_index": 6, "correct_answer": "玩游戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天在车间玩游戏，一直干到很晚。", "explanation": "这里应该用〈工作〉。玩游戏指做电子游戏，不能用来表示在车间干活。"}, {"text": "快递员每天在街上玩游戏，送件送到很晚。", "explanation": "这里应该用〈送快递〉。玩游戏指做电子游戏，不能用来表示送件。"}, {"text": "奶奶每天在院子里玩游戏，收拾到很晚。", "explanation": "这里应该用〈打扫〉。玩游戏指做电子游戏，不能用来表示打扫家务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27730, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末他常常玩游戏玩凌晨。", "corrected_sentence": "周末他常常玩游戏玩到凌晨。", "error_description": "“玩到凌晨”中的“到”是补语的一部分，不能省略。省略后“玩凌晨”不成话，应说“玩到凌晨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27730, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们晚上在宿舍了玩游戏，很开心。", "corrected_sentence": "我们晚上在宿舍玩游戏，很开心。", "error_description": "句中多出的“了”放在“玩游戏”前面，位置不对。“了”应放在动词后，而这句话不需要“了”，应删去，说“在宿舍玩游戏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
