INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27732, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电脑里用来让程序运行的指令。", "primary_collocate": null, "pronunciation": "dài mǎ", "ipa": "taɪ˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "他每天写很多代码。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段代码有一个错误。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写代码。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一下我的代码。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序不能运行，是因为代码错了。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把代码发给了同事。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这行代码是什么意思？", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的代码写得又短又清楚。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑按照代码做事。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学校学过写代码。", "target_word": "代码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "行", "label": "量词"}, {"form": "代碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "程序员写的、让电脑程序运行的指令", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27732, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代码", "is_correct": true, "explanation": "正确答案：代码（dài mǎ），指电脑中让程序运行的指令。"}, {"text": "大码", "is_correct": false, "explanation": "dài 与 dà 韵母不同（缺少 i），意思是大号，指尺码大。"}, {"text": "代买", "is_correct": false, "explanation": "mǎ 与 mǎi 韵母不同（多出 i），意思是代替别人购买。"}, {"text": "大马", "is_correct": false, "explanation": "dà 与 dài 韵母不同（缺少 i），意思是大的马，也可指马来西亚。"}], "explanations": {"代码": "正确答案：代码（dài mǎ），指电脑中让程序运行的指令。", "大码": "dài 与 dà 韵母不同（缺少 i），意思是大号，指尺码大。", "代买": "mǎ 与 mǎi 韵母不同（多出 i），意思是代替别人购买。", "大马": "dà 与 dài 韵母不同（缺少 i），意思是大的马，也可指马来西亚。"}, "sentence_index": null, "correct_answer": "代码"}, "level_3": {"options": [{"text": "代码", "is_correct": true, "explanation": "正确：代码是程序员写的指令，可以说“写代码”。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能“写”，句子说的是编写程序。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，也不能“写很多”，与句意不合。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“写”一般不接“电话”，要说“打电话”。"}], "explanations": {"代码": "正确：代码是程序员写的指令，可以说“写代码”。", "饺子": "语义：饺子是食物，不能“写”，句子说的是编写程序。", "空气": "语义：空气看不见，也不能“写很多”，与句意不合。", "电话": "搭配：“写”一般不接“电话”，要说“打电话”。"}, "sentence_index": 0, "correct_answer": "代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈照着代码做菜。", "explanation": "这里应该用〈食谱〉。代码是给电脑执行的指令，做菜要照着食谱，不能照着代码。"}, {"text": "他会说三种代码。", "explanation": "这里应该用〈语言〉。代码是给计算机执行的指令，不能说“会说”。"}, {"text": "他忘了邮箱的代码。", "explanation": "这里应该用〈密码〉。登录邮箱用的是密码，代码是程序中的指令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27732, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代码", "is_correct": true, "explanation": "正确：“这行代码”指一行程序指令，与“是什么意思”相合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“行”作量词不用于天气，天气也不说“这行天气”。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：冰淇淋是食物，不是需要解释意义的文字或指令。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是需要解释意义的文字，“这行眼泪是什么意思”不合理。"}], "explanations": {"代码": "正确：“这行代码”指一行程序指令，与“是什么意思”相合。", "天气": "搭配：“行”作量词不用于天气，天气也不说“这行天气”。", "冰淇淋": "语义：冰淇淋是食物，不是需要解释意义的文字或指令。", "眼泪": "语义：眼泪不是需要解释意义的文字，“这行眼泪是什么意思”不合理。"}, "sentence_index": 6, "correct_answer": "代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她记不住我的手机代码。", "explanation": "这里应该用〈号码〉。手机号码不说“手机代码”，代码指程序中的指令。"}, {"text": "钢琴家看着代码弹琴。", "explanation": "这里应该用〈乐谱〉。代码是给电脑执行的指令，弹琴要看乐谱，不能看代码。"}, {"text": "他学会了英语代码。", "explanation": "这里应该用〈语法〉。英语语法是语言规则，代码指程序指令，不能说“英语代码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写了一只代码。", "corrected_sentence": "他写了一段代码。", "error_description": "“代码”的量词应为“段”或“行”，不能用“只”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些代码们都写好了。", "corrected_sentence": "这些代码都写好了。", "error_description": "错误：“代码们”。正确：“代码”。“们”只用于指人的名词，“代码”不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
