INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "升力是一种力量，它能让飞机向上飞起来。", "primary_collocate": null, "pronunciation": "shēng lì", "ipa": "ʂɤŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "飞机飞得快，就会有更大的升力。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的翅膀能给身体一点升力。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过机翼，会产生升力。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有升力，飞机就飞不起来。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机翼的形状会影响升力的大小。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画了升力的图。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机慢下来，升力就会变小。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝飞起来，也是因为有升力。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟张开翅膀，得到了更多升力。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机的升力很大，能带很多人。", "target_word": "升力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "升力系数", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机或鸟向上飞时受到的向上的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "升力", "is_correct": true, "explanation": "正确：升力是飞机或鸟向上飞时受到的向上的力。"}, {"text": "胜利", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利。"}, {"text": "生梨", "is_correct": false, "explanation": "shēng 相同，lí（第二声）与 lì（第四声）声调不同，意思是生梨，一种水果。"}, {"text": "生理", "is_correct": false, "explanation": "lǐ（第三声）与 lì（第四声）声调不同，意思是生理，即生物体的机能。"}], "explanations": {"升力": "正确：升力是飞机或鸟向上飞时受到的向上的力。", "胜利": "shèng（第四声）与 shēng（第一声）声调不同，意思是胜利。", "生梨": "shēng 相同，lí（第二声）与 lì（第四声）声调不同，意思是生梨，一种水果。", "生理": "lǐ（第三声）与 lì（第四声）声调不同，意思是生理，即生物体的机能。"}, "sentence_index": null, "correct_answer": "升力"}, "level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：飞机飞得快不会使它变重，“重量”与速度无关。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：飞机没有脾气，“脾气”不能用来说明飞行时的力。"}, {"text": "升力", "is_correct": true, "explanation": "正确：飞机速度快，机翼受到的向上的升力就更大。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“更大的”修饰力量或速度，不说“更大的味道”。"}], "explanations": {"重量": "语义：飞机飞得快不会使它变重，“重量”与速度无关。", "脾气": "语义：飞机没有脾气，“脾气”不能用来说明飞行时的力。", "升力": "正确：飞机速度快，机翼受到的向上的升力就更大。", "味道": "搭配：“更大的”修饰力量或速度，不说“更大的味道”。"}, "sentence_index": 0, "correct_answer": "升力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "发动机产生升力，使飞机向前飞。", "explanation": "这里应该用〈推力〉。升力是向上的力，使飞机向前飞要用推力。"}, {"text": "鞋底靠升力才能站稳。", "explanation": "这里应该用〈摩擦力〉。站稳靠的是鞋底与地面的摩擦力，升力是飞行时向上的力，不能让人站稳。"}, {"text": "苹果受到升力会落下来。", "explanation": "这里应该用〈重力〉。升力是向上的力，使苹果下落的是重力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "升力", "is_correct": true, "explanation": "正确：升力是飞机或鸟向上飞时受到的向上的力。"}, {"text": "生气", "is_correct": false, "explanation": "lì 与 qì 声母不同（l 与 q），声调相同，意思是生气，即发怒。"}, {"text": "生日", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），声调相同，意思是生日。"}, {"text": "省力", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是省力，即费力少。"}, {"text": "生计", "is_correct": false, "explanation": "lì 与 jì 声母不同（l 与 j），声调相同，意思是生计，即谋生的办法。"}], "explanations": {"升力": "正确：升力是飞机或鸟向上飞时受到的向上的力。", "生气": "lì 与 qì 声母不同（l 与 q），声调相同，意思是生气，即发怒。", "生日": "lì 与 rì 声母不同（l 与 r），声调相同，意思是生日。", "省力": "shěng（第三声）与 shēng（第一声）声调不同，意思是省力，即费力少。", "生计": "lì 与 jì 声母不同（l 与 j），声调相同，意思是生计，即谋生的办法。"}, "sentence_index": null, "correct_answer": "升力"}, "level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：飞机慢下来，颜色不会因此变小，句子不合常理。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温与飞机的速度无关，不会“变小”。"}, {"text": "升力", "is_correct": true, "explanation": "正确：飞机速度慢下来，机翼上的升力就会变小。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“变小”不能用于名字，句子不通。"}], "explanations": {"颜色": "语义：飞机慢下来，颜色不会因此变小，句子不合常理。", "体温": "语义：体温与飞机的速度无关，不会“变小”。", "升力": "正确：飞机速度慢下来，机翼上的升力就会变小。", "名字": "搭配：“变小”不能用于名字，句子不通。"}, "sentence_index": 6, "correct_answer": "升力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地球对月亮的升力很大，使月亮绕着地球转。", "explanation": "这里应该用〈引力〉。升力是飞行器或鸟的向上的力，地球吸引月亮的是引力。"}, {"text": "汽车的升力全部来自发动机。", "explanation": "这里应该用〈动力〉。升力是飞行时的向上的力，推动车子前进的是动力。"}, {"text": "水对池底有很大的升力。", "explanation": "这里应该用〈压力〉。升力是向上的力，水对池底施加的是向下的压力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机翼上方的气流变快，就会产生一只更大的升力。", "corrected_sentence": "机翼上方的气流变快，就会产生更大的升力。", "error_description": "“升力”是抽象的力，不能用量词“只”计量，应直接说“更大的升力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机起飞后，就会有稳定地升力。", "corrected_sentence": "飞机起飞后，就会有稳定的升力。", "error_description": "“稳定”修饰名词“升力”时要用结构助词“的”，不用“地”（“地”用于修饰动词）；应说“稳定的升力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
