INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27742, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫别人把话或东西继续往下传给更多人。", "primary_collocate": null, "pronunciation": "chuán xià qù", "ipa": "ʈʂʰwan˧˥ ɕja˥˩ tɕʰy˥˩", "syllable_count": 3, "sentences": [{"text": "听到好消息的人，请把它传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“你们看完了，就传下去。”", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息很重要，你一定要传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喜欢这首歌，就把它传下去吧。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我说：“这件事别说出去，也别传下去。”", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让我把这张纸条传下去，不要自己留着。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家别把这个秘密传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长说，听到了就告诉后面的人，再传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好办法要告诉大家，让更多人传下去。", "target_word": "传下去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看完这本书，再叫朋友传下去。", "target_word": "传下去", "complexity_tier": "T3", "furigana": "chuán xià qù", "sentence_source": "generated"}], "morphological_forms": [{"form": "傳下去", "label": "繁体"}, {"form": "传下去了", "label": "体标"}], "register": "中性", "sense_fingerprint": "请求或要求别人把话、消息继续告诉更多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2f8d72d-01b8-470d-9c8d-ddfe701976a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传下去", "is_correct": true, "explanation": "正确答案：「请把它传下去」指请人把好消息继续告诉别人，符合句意。"}, {"text": "扔下去", "is_correct": false, "explanation": "搭配：「扔」用于具体的东西，不能说「扔好消息」。"}, {"text": "吃下去", "is_correct": false, "explanation": "搭配：「吃」用于食物，不能说「吃好消息」。"}, {"text": "藏下去", "is_correct": false, "explanation": "语义：「藏」是隐藏起来，与「请人把好消息告诉更多人」的要求相反。"}], "explanations": {"传下去": "正确答案：「请把它传下去」指请人把好消息继续告诉别人，符合句意。", "扔下去": "搭配：「扔」用于具体的东西，不能说「扔好消息」。", "吃下去": "搭配：「吃」用于食物，不能说「吃好消息」。", "藏下去": "语义：「藏」是隐藏起来，与「请人把好消息告诉更多人」的要求相反。"}, "sentence_index": 0, "correct_answer": "传下去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把这封信传下去寄到北京。", "explanation": "这里应该用〈寄〉。「传下去」是一层层往下递，寄到远方要用「寄」，不能说传下去。"}, {"text": "请把那把伞传下去给我。", "explanation": "这里应该用〈递〉。「传下去」指一层层往下递，直接交给面前的人要用「递」。"}, {"text": "请把这本书传下去送给老师。", "explanation": "这里应该用〈送〉。「传下去」是一层层往下递，直接送给老师这样的上级要用「送」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传下去", "is_correct": true, "explanation": "正确答案：「别把这个秘密传下去」指不要把秘密继续告诉别人，符合句意。"}, {"text": "切下去", "is_correct": false, "explanation": "搭配：「切」用于食物或物体，不能说「切秘密」。"}, {"text": "煮下去", "is_correct": false, "explanation": "搭配：「煮」用于食物，不能用来说秘密。"}, {"text": "收回去", "is_correct": false, "explanation": "语义：「收回去」是收回已经放出去的东西，与「别把秘密继续往外说」的意思不符。"}], "explanations": {"传下去": "正确答案：「别把这个秘密传下去」指不要把秘密继续告诉别人，符合句意。", "切下去": "搭配：「切」用于食物或物体，不能说「切秘密」。", "煮下去": "搭配：「煮」用于食物，不能用来说秘密。", "收回去": "语义：「收回去」是收回已经放出去的东西，与「别把秘密继续往外说」的意思不符。"}, "sentence_index": 6, "correct_answer": "传下去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请大家把这件事传下去给校长。", "explanation": "这里应该用〈汇报〉。「传下去」是往下传达，给校长这样的上级要用「汇报」。"}, {"text": "你看完这本书，就把它传下去还给图书馆。", "explanation": "这里应该用〈归还〉。「传下去」是往下递给别人继续传，还给图书馆要用「归还」。"}, {"text": "你看完后，把笔记传下去给老师。", "explanation": "这里应该用〈上交〉。「传下去」是向下递，交给老师这样的上级要用「上交」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们，请把这张通知传下去了。", "corrected_sentence": "同学们，请把这张通知传下去。", "error_description": "体标错误：祈使句「请……」后面不能加「了」，表示请求时直接说「请把……传下去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你觉得有用，就被这个方法传下去。", "corrected_sentence": "你觉得有用，就把这个方法传下去。", "error_description": "介词误用：「被」字句不能这样用，应把「被」改为「把」，用「把」引出被传递的「这个方法」，说「把这个方法传下去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
