INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27744, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让机器或东西开始工作。", "primary_collocate": null, "pronunciation": "qǐ dòng", "ipa": "tɕʰi˨˩˦ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "请启动电脑。", "target_word": "启动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他启动了汽车。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车子启动的时候很安静。", "target_word": "启动", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我按一下这个键，机器就启动了。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑启动得太慢了。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师启动了电脑，开始上课。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先打开电源，再启动机器。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把新机器启动了。", "target_word": "启动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机启动以后，要等一会儿才能用。", "target_word": "启动", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他启动过这台机器，所以知道怎么用。", "target_word": "启动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "启动了", "label": "体标"}, {"form": "启动过", "label": "体标"}, {"form": "啟動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使机器或系统开始运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27744, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启动", "is_correct": true, "explanation": "正确：“请启动电脑”表示让电脑开始运转，“启动”是唯一合适的动词。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用于电脑。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物，不能说“喂养电脑”。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝味道，不能用于电脑。"}], "explanations": {"启动": "正确：“请启动电脑”表示让电脑开始运转，“启动”是唯一合适的动词。", "种植": "语义：“种植”指栽种植物，不能用于电脑。", "喂养": "搭配：“喂养”的对象是动物，不能说“喂养电脑”。", "品尝": "语义：“品尝”指尝味道，不能用于电脑。"}, "sentence_index": 0, "correct_answer": "启动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到好消息，就启动了笑容。", "explanation": "这里应该用〈露出〉。“启动”用于机器和系统，露出笑容要用“露出”。"}, {"text": "请启动窗户，让房间透透气。", "explanation": "这里应该用〈打开〉。“启动”用于机器和系统，窗户要说“打开窗户”。"}, {"text": "我们启动包裹，里面有一本书。", "explanation": "这里应该用〈打开〉。“启动”用于机器和系统，包裹不能启动，应说“打开包裹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27744, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启动", "is_correct": true, "explanation": "正确：“先打开电源，再启动机器”表示让机器开始工作，“启动”最合适。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用于机器。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是植物或液体，不能说“浇机器”。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：“哄”的对象是人或小孩，不能说“哄机器”。"}], "explanations": {"启动": "正确：“先打开电源，再启动机器”表示让机器开始工作，“启动”最合适。", "唱": "语义：“唱”指发声演唱，不能用于机器。", "浇": "搭配：“浇”的对象是植物或液体，不能说“浇机器”。", "哄": "搭配：“哄”的对象是人或小孩，不能说“哄机器”。"}, "sentence_index": 6, "correct_answer": "启动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他启动门，走进了房间。", "explanation": "这里应该用〈开〉。门的开关用“开”，“启动”只用于机器和系统。"}, {"text": "老师启动了那个同学，让他回答问题。", "explanation": "这里应该用〈叫〉。“启动”只用于机器和系统，叫学生回答问题要说“叫”。"}, {"text": "我启动灯，然后开始看书。", "explanation": "这里应该用〈开〉。开灯要用“开”，“启动”不用于灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人昨天启动了了新机器。", "corrected_sentence": "工人昨天启动了新机器。", "error_description": "错误形式：启动了了新机器；正确形式：启动了新机器。“了”重复了一次，只保留一个“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电脑启动得得很快。", "corrected_sentence": "电脑启动得很快。", "error_description": "错误形式：启动得得很快；正确形式：启动得很快。“得”重复了一次，只保留一个“得”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
