INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27748, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "常常的意思是“很多次”，比如“我常常去公园玩”。", "primary_collocate": null, "pronunciation": "cháng cháng", "ipa": "ʈʂʰɑŋ˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我常常去公园玩。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常早上六点起床。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们常常一起去爬山。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王常常忘记带手机。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常给妈妈打电话。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里常常下雪。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟常常在晚上看书。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你常常吃早饭吗？", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前常常迟到，现在不迟到了。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常说，学习要多练习。", "target_word": "常常", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示动作发生的次数很多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27748, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "常常", "is_correct": true, "explanation": "正确：“常常”表示次数多，与“去公园玩”的习惯相合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不修饰“去”，不说“非常去公园玩”。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要和否定词一起用，不能说“从来去公园玩”。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，常与“了”连用，不能直接修饰“去公园玩”这类动作。"}], "explanations": {"常常": "正确：“常常”表示次数多，与“去公园玩”的习惯相合。", "非常": "搭配：“非常”修饰形容词或心理动词，不修饰“去”，不说“非常去公园玩”。", "从来": "搭配：“从来”要和否定词一起用，不能说“从来去公园玩”。", "太": "搭配：“太”修饰形容词，常与“了”连用，不能直接修饰“去公园玩”这类动作。"}, "sentence_index": 0, "correct_answer": "常常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常在去年毕业。", "explanation": "这里应该用〈已经〉。〈常常〉表示多次重复，〈毕业〉只发生一次，表示一次性的完成应说“他已经毕业了”或直接说“他去年毕业”。"}, {"text": "我常常去了一次医院。", "explanation": "这里应该用〈偶尔〉。〈常常〉表示多次，与“一次”矛盾；表示少数几次应用〈偶尔〉，说“我偶尔去了一次医院”。"}, {"text": "下个月我常常搬家。", "explanation": "这里应该用〈要〉。〈常常〉指经常重复的动作，“搬家”是一次性的未来事件，应说“下个月我要搬家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27748, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "常常", "is_correct": true, "explanation": "正确：“常常”表示经常，与“在晚上看书”的习惯相合。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不修饰“在晚上看书”这类动作。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度最高，不用来修饰“看书”这类动作。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不说“非常在晚上看书”。"}], "explanations": {"常常": "正确：“常常”表示经常，与“在晚上看书”的习惯相合。", "很": "搭配：“很”修饰形容词，不修饰“在晚上看书”这类动作。", "最": "搭配：“最”表示程度最高，不用来修饰“看书”这类动作。", "非常": "搭配：“非常”修饰形容词或心理动词，不说“非常在晚上看书”。"}, "sentence_index": 6, "correct_answer": "常常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥常常建成于去年。", "explanation": "这里应该用〈已经〉。〈常常〉表示多次重复，〈建成〉只发生一次，表示已完成的一次性事件应说“这座桥已经建成”。"}, {"text": "这次考试我常常考了满分。", "explanation": "这里应该用〈终于〉。〈常常〉表示多次，“这次考试”只考一次，表示一次性的结果应说“这次考试我终于考了满分”。"}, {"text": "妈妈常常生了二宝。", "explanation": "这里应该用〈后来〉。〈常常〉表示多次重复，生二宝只发生一次，应说“妈妈后来生了二宝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常在图书馆学习常常。", "corrected_sentence": "他常常在图书馆学习。", "error_description": "错误：句末多出一个「常常」。「常常」是状语，只能放在动词前面，句末的「常常」应删去，得到「他常常在图书馆学习。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学校的老师很常常开会。", "corrected_sentence": "这个学校的老师常常开会。", "error_description": "“很”是程度副词，不能与“常常”叠用来修饰动词，表示次数多直接说“常常开会”，不能说“很常常开会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
