INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27754, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球日是一个特别的日子，每年一次，告诉大家要爱护我们的地球。", "primary_collocate": null, "pronunciation": "dì qiú rì", "ipa": "ti˥˩ t͡ɕʰiou˧˥ ɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "今天是地球日，我们不开车。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日每年有一次。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日到了，妈妈带我去公园捡垃圾。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在地球日画了一幅地球的画。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日这天，大家都少用塑料袋。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢地球日，因为可以种花。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道地球日是哪一天吗？", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日让我们想到要爱护地球。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天是地球日，学校要开会。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日那天晚上，我们关了灯。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每年一次提醒人们爱护地球的特别日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c5d266d-7f63-4cac-bf36-2351f9160e06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地球日", "is_correct": true, "explanation": "地球日是每年一次提醒人们爱护地球的特别日子，“今天是”后面填入此词正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“今天是”后面要说日子，“颜色”不能作为日子，句子不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人有多高，不是日子，不能说“今天是身高”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不能说“今天是脾气”。"}], "explanations": {"地球日": "地球日是每年一次提醒人们爱护地球的特别日子，“今天是”后面填入此词正确。", "颜色": "语义：“今天是”后面要说日子，“颜色”不能作为日子，句子不通。", "身高": "语义：“身高”指人有多高，不是日子，不能说“今天是身高”。", "脾气": "语义：“脾气”指性情，不能说“今天是脾气”。"}, "sentence_index": 0, "correct_answer": "地球日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小朋友在一只地球日画了一幅画。", "explanation": "这里的量词应该用〈个〉。“只”用于动物，“地球日”是节日，要用“个”。"}, {"text": "爸爸每天都过地球日。", "explanation": "这里的错误在于频率。“地球日”一年只有一次，应说“每年”，不能说“每天”。"}, {"text": "这位老人的地球日在六月。", "explanation": "这里应该用〈生日〉。“地球日”是全球性的纪念日，不属于个人，个人的日子要说“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地球日", "is_correct": true, "explanation": "地球日是特别的日子，“你知道……是哪一天吗”问的是日期，填入此处正确。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指有多重，不是日子，不能问“体重是哪一天”。"}, {"text": "学历", "is_correct": false, "explanation": "配价：“学历”需要人作为持有者，不能用来问日期。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个性，不能问“性格是哪一天”。"}], "explanations": {"地球日": "地球日是特别的日子，“你知道……是哪一天吗”问的是日期，填入此处正确。", "体重": "语义：“体重”指有多重，不是日子，不能问“体重是哪一天”。", "学历": "配价：“学历”需要人作为持有者，不能用来问日期。", "性格": "语义：“性格”指个性，不能问“性格是哪一天”。"}, "sentence_index": 6, "correct_answer": "地球日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的地球日很便宜。", "explanation": "这里应该用〈价格〉。“便宜”说的是价格，“地球日”是日子，不能用来说价钱高低。"}, {"text": "这位奶奶的地球日很大了。", "explanation": "这里应该用〈年龄〉。“很大”说的是年纪，“地球日”是日子，不能用来说人的年龄大。"}, {"text": "我们在地球日的操场上踢球。", "explanation": "这里的错误在于地点。“地球日”是日期，不是地点，不能说“地球日的操场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明年的一只地球日是星期六。", "corrected_sentence": "明年的地球日是星期六。", "error_description": "量词错误。“地球日”是日子，不能用“只”（只用于动物）。正确说法是“明年的地球日是星期六”，去掉“一只”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学校每年都在地球日们那天举办活动。", "corrected_sentence": "我们学校每年都在地球日那天举办活动。", "error_description": "词缀错误：“地球日”是日子，不能加“们”表示复数。正确说法是“我们学校每年都在地球日那天举办活动”，去掉“们”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a0a4231-0e50-42c7-9177-91d0248c52a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
