INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27760, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示最高程度，没有比这更厉害的了。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "这道题极难，全班只有一人做对。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累极了，一回家就睡了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的空气极新鲜。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市夏天极热。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音极小。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的产品质量极高。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的比赛好看极了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘菜极辣，我吃了一口就停了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对朋友极好，大家都喜欢他。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的结果让我失望极了。", "target_word": "极", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，表示程度已到最高，没有比这更高的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27760, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示达到最高程度，与听到的读音一致。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是打击。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, {"text": "其", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是其他、它的。"}, {"text": "齐", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是整齐。"}], "explanations": {"极": "正确：极（jí）表示达到最高程度，与听到的读音一致。", "积": "jī（第一声）与 jí（第二声）声调不同，意思是积累。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是打击。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。", "其": "qí 与 jí 声母不同，意思是其他、它的。", "齐": "qí 与 jí 声母不同，意思是整齐。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "在", "is_correct": false, "explanation": "语法：“在”不能修饰形容词“难”，“这道题在难”不通。"}, {"text": "极", "is_correct": true, "explanation": "正确：“极难”表示难度达到最高，与“全班只有一人做对”相符。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示“刚刚”，不能修饰形容词“难”，“刚难”不通。"}, {"text": "没", "is_correct": false, "explanation": "搭配：“没”否定已经发生的事，不修饰形容词“难”，“没难”不通。"}], "explanations": {"在": "语法：“在”不能修饰形容词“难”，“这道题在难”不通。", "极": "正确：“极难”表示难度达到最高，与“全班只有一人做对”相符。", "刚": "搭配：“刚”表示“刚刚”，不能修饰形容词“难”，“刚难”不通。", "没": "搭配：“没”否定已经发生的事，不修饰形容词“难”，“没难”不通。"}, "sentence_index": 0, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去南极看了企鹅。", "explanation": "这里的“极”是名词“南极”的一部分，不是程度副词“极”。"}, {"text": "他极跑了三圈，累坏了。", "explanation": "“极”是程度副词，只修饰形容词，不能修饰动词“跑”；这里不能说“极跑”。"}, {"text": "他极吃了三碗饭，撑得走不动。", "explanation": "“极”是程度副词，不修饰动词“吃”；这里不能说“极吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27760, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极", "is_correct": true, "explanation": "正确：极（jí）表示最高程度，与听到的读音一致。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, {"text": "鸡", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。"}, {"text": "计", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是计算。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}, {"text": "奇", "is_correct": false, "explanation": "qí 与 jí 声母不同，意思是奇怪。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}], "explanations": {"极": "正确：极（jí）表示最高程度，与听到的读音一致。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。", "鸡": "jī（第一声）与 jí（第二声）声调不同，意思是鸡。", "计": "jì（第四声）与 jí（第二声）声调不同，意思是计算。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。", "奇": "qí 与 jí 声母不同，意思是奇怪。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, "sentence_index": null, "correct_answer": "极"}, "level_3": {"options": [{"text": "也", "is_correct": false, "explanation": "搭配：“也”要放在形容词前，不能放在“好看”之后，“好看也了”不通。"}, {"text": "略", "is_correct": false, "explanation": "语域：“略”偏书面语，且须放在形容词前，这里放在“好看”之后不通。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，前文没有转折语境，“好看却了”也不成立。"}, {"text": "极", "is_correct": true, "explanation": "正确：“好看极了”是补语形式，表示好看的程度达到最高。"}], "explanations": {"也": "搭配：“也”要放在形容词前，不能放在“好看”之后，“好看也了”不通。", "略": "语域：“略”偏书面语，且须放在形容词前，这里放在“好看”之后不通。", "却": "语义：“却”表示转折，前文没有转折语境，“好看却了”也不成立。", "极": "正确：“好看极了”是补语形式，表示好看的程度达到最高。"}, "sentence_index": 6, "correct_answer": "极"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在北极工作。", "explanation": "这里的“极”是名词“北极”，不是程度副词“极”。"}, {"text": "他极睡了一整天。", "explanation": "“极”是程度副词，不修饰动词“睡”；这里不能说“极睡”。"}, {"text": "他极考了一百分，大家都很惊讶。", "explanation": "“极”是程度副词，不修饰动词“考”；这里不能说“极考”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的冬天很极冷。", "corrected_sentence": "这里的冬天极冷。", "error_description": "“极”本身就表示最高程度，不能再受程度副词“很”修饰；“很极冷”不符合语法，应去掉“很”，说“极冷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影好看极。", "corrected_sentence": "这部电影好看极了。", "error_description": "“极了”是补语形式，要带上“了”，应说“好看极了”；“好看极”不完整，不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
