INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27764, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水窖是一个用来存雨水的大坑。", "primary_collocate": null, "pronunciation": "shuǐ jiào", "ipa": "ʂweɪ˨˩˦ tɕjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "水窖是存雨水的地方。", "target_word": "水窖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村口有一个很大的水窖。", "target_word": "水窖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "雨水流进了水窖。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在山边挖水窖。", "target_word": "水窖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水窖里还有很多水。", "target_word": "水窖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年雨多，水窖都满了。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去水窖那边看看吧。", "target_word": "水窖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从水窖里提了一桶水回家。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水窖太深了，小孩不能靠近。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了存水，每家人都建了水窖。", "target_word": "水窖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "口", "label": "量词"}], "register": "中性", "sense_fingerprint": "水窖：用来存雨水的大坑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。水窖（shuǐ jiào）指用来存雨水的大坑。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡（shuì）与水（shuǐ）声调不同，意思是睡眠。"}, {"text": "水饺", "is_correct": false, "explanation": "饺（jiǎo）与窖（jiào）声调不同，意思是饺子。"}, {"text": "谁叫", "is_correct": false, "explanation": "谁（shuí）与水（shuǐ）声调不同，意思是“谁在叫”。"}], "explanations": {"水窖": "正确。水窖（shuǐ jiào）指用来存雨水的大坑。", "睡觉": "睡（shuì）与水（shuǐ）声调不同，意思是睡眠。", "水饺": "饺（jiǎo）与窖（jiào）声调不同，意思是饺子。", "谁叫": "谁（shuí）与水（shuǐ）声调不同，意思是“谁在叫”。"}, "sentence_index": null, "correct_answer": "水窖"}, "level_3": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。“水窖是存雨水的地方”指用来存雨水的大坑。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是存雨水的地方。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，与存雨水无关。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“存雨水”的对象不能是电梯，电梯也不是存放东西的设施。"}], "explanations": {"水窖": "正确。“水窖是存雨水的地方”指用来存雨水的大坑。", "厨房": "语义：厨房是做饭的地方，不是存雨水的地方。", "图书馆": "语义：图书馆是借阅书籍的地方，与存雨水无关。", "电梯": "搭配：“存雨水”的对象不能是电梯，电梯也不是存放东西的设施。"}, "sentence_index": 0, "correct_answer": "水窖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村口的水窖里停满了汽车。", "explanation": "这里应该用〈停车场〉。停车场用于停放车辆，水窖是用来存雨水的大坑，不能停车。"}, {"text": "老师在水窖里给学生上课。", "explanation": "这里应该用〈教室〉。教室用于上课，水窖是存雨水的大坑，不用于授课。"}, {"text": "周末，爸爸带我去水窖边看电影。", "explanation": "这里应该用〈电影院〉。电影院用于放映电影，水窖是存雨水的大坑，不用于放映电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水窖", "is_correct": true, "explanation": "正确。“我们去水窖那边看看吧”指去看用来存雨水的大坑。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”是时间，不是地方，不能说“去昨天那边看看”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不是地点，不能说“去……那边”。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水指落下来的水，不是可以前往的地方，与“去……那边”不合。"}], "explanations": {"水窖": "正确。“我们去水窖那边看看吧”指去看用来存雨水的大坑。", "昨天": "语义：“昨天”是时间，不是地方，不能说“去昨天那边看看”。", "作业": "搭配：“作业”不是地点，不能说“去……那边”。", "雨水": "语义：雨水指落下来的水，不是可以前往的地方，与“去……那边”不合。"}, "sentence_index": 6, "correct_answer": "水窖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天，我们把白菜存进水窖里。", "explanation": "这里应该用〈地窖〉。地窖用来存放蔬菜，水窖是存雨水的大坑，不用于存菜。"}, {"text": "我们在水窖里养了几只鸡。", "explanation": "这里应该用〈鸡舍〉。鸡舍用来养鸡，水窖是存雨水的大坑，不用于养鸡。"}, {"text": "孩子们在水窖里玩滑梯。", "explanation": "这里应该用〈游乐场〉。游乐场有滑梯等设施，水窖是存雨水的大坑，不是游乐设施。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里每户都挖了一条水窖。", "corrected_sentence": "村里每户都挖了一个水窖。", "error_description": "错误：“一条水窖”，“条”用于细长的东西，如河流、道路。正确：“一个水窖”，水窖的量词应为“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们不能靠近那个的水窖。", "corrected_sentence": "孩子们不能靠近那个水窖。", "error_description": "错误：“那个的水窖”，指示词、量词与名词之间不加“的”。正确：“那个水窖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
