INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "等啊等，直到某个时候。", "primary_collocate": null, "pronunciation": "děng dào", "ipa": "tɤŋ˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我们等到十点，他还没来。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在门口等到天黑。", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我一直等到十二点才睡觉。", "target_word": "等到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在办公室里等到下班才离开。", "target_word": "等到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人一直等到医生来。", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你要等到什么时候？", "target_word": "等到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗在门口等到主人回家。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们等到比赛结束才离开。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他等啊等，一直等到太阳下山。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈等到半夜，孩子才回来。", "target_word": "等到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等到了", "label": "体标（完成）"}, {"form": "等到过", "label": "体标（经历）"}], "register": "中性", "sense_fingerprint": "等到：一直等，直到某个时间或结果出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c76bde43-0392-4ea4-a443-ef925d444d96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示一直等，直到某个时间，与“十点”和“他还没来”相呼应。"}, {"text": "拿到", "is_correct": false, "explanation": "语义：“拿到”指取得物品，不能说“拿到十点”表示持续等待。"}, {"text": "找到", "is_correct": false, "explanation": "语义：“找到”指找着东西，不能说“找到十点”。"}, {"text": "送到", "is_correct": false, "explanation": "语义：“送到”指把东西送到某处，不能说“送到十点”表示等待。"}], "explanations": {"等到": "等到表示一直等，直到某个时间，与“十点”和“他还没来”相呼应。", "拿到": "语义：“拿到”指取得物品，不能说“拿到十点”表示持续等待。", "找到": "语义：“找到”指找着东西，不能说“找到十点”。", "送到": "语义：“送到”指把东西送到某处，不能说“送到十点”表示等待。"}, "sentence_index": 0, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站等到了一个小时。", "explanation": "这里应该用〈等了〉或〈等待〉。〈等到〉表示等来某个时间或结果，不能与表示持续时段的“一个小时”连用。"}, {"text": "这场比赛等到天黑才结束。", "explanation": "这里应该用〈直到〉。〈等到〉的主语必须是能够等待的人，“这场比赛”不能等待，表示事情持续到某时才结束要用〈直到〉。"}, {"text": "这项工程等到明年才完工。", "explanation": "这里应该用〈直到〉。〈等到〉的主语须能等待，“这项工程”不能等待，表示持续到某时才完成要用〈直到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等到", "is_correct": true, "explanation": "等到表示一直等，直到主人回家，与“在门口”和“回家”相呼应。"}, {"text": "吃到", "is_correct": false, "explanation": "语义：“吃到”指吃着食物，“吃到主人回家”不成立。"}, {"text": "咬到", "is_correct": false, "explanation": "语义：“咬到”指用牙咬着，“咬到主人回家”不成立。"}, {"text": "卖到", "is_correct": false, "explanation": "语义：“卖到”指把东西卖往某处，“小狗卖到主人回家”不成立。"}], "explanations": {"等到": "等到表示一直等，直到主人回家，与“在门口”和“回家”相呼应。", "吃到": "语义：“吃到”指吃着食物，“吃到主人回家”不成立。", "咬到": "语义：“咬到”指用牙咬着，“咬到主人回家”不成立。", "卖到": "语义：“卖到”指把东西卖往某处，“小狗卖到主人回家”不成立。"}, "sentence_index": 6, "correct_answer": "等到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨等到半夜才停。", "explanation": "这里应该用〈直到〉。〈等到〉的主语必须能够等待，“雨”不能等待，表示持续到某时才停要用〈直到〉。"}, {"text": "妈妈在门口等到了半个晚上。", "explanation": "这里应该用〈等了〉。〈等到〉表示等来某个时刻或结果，不能与持续的时段“半个晚上”连用。"}, {"text": "妈妈等到门口，孩子才回来。", "explanation": "这里应该用〈走到〉。〈等到〉表示等待直到某个时刻或事件出现，不表示移动到某个地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在车站等到到了天亮。", "corrected_sentence": "我在车站等到了天亮。", "error_description": "错误：“到”被重复写了一次。正确：“等到了”中只用一个“到”，“了”紧跟在“等到”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27766, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在门口的等到了妈妈。", "corrected_sentence": "孩子在门口等到了妈妈。", "error_description": "错误：“等到”前多加了“的”，使动词被错误地当作名词性修饰语。正确：“孩子在门口”作状语，“等到了妈妈”直接作谓语，中间不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd83ef5f7-7cfa-4393-adfb-48cc13913394') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
