INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从坐着或躺着变成站着。", "primary_collocate": null, "pronunciation": "qǐ lái", "ipa": "tɕʰi˨˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始了，观众都起来鼓掌。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从椅子上起来，给老人让座。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他躺了一会儿，就起来倒水喝。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你起来，让我过去一下。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗趴在地上，听到声音就起来了。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸坐在门口，看见客人马上起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡醒了，自己从床上起来穿衣服。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说：“都坐下，谁也不要起来。”", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他累得坐在地上，半天没起来。", "target_word": "起来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车一停，坐着的人都起来拿行李。", "target_word": "起来", "complexity_tier": "T3", "furigana": "chē yì tíng, zuò zhe de rén dōu qǐ lái ná xíng li.", "sentence_source": "generated"}], "morphological_forms": [{"form": "起来了", "label": "体标"}], "register": "口语", "sense_fingerprint": "由坐或躺变成站；起身站立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示由坐变为站立，符合“比赛开始了，观众都……鼓掌”的语境。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”表示快速移动，不能与“鼓掌”搭配说明观众的动作状态。"}, {"text": "走", "is_correct": false, "explanation": "搭配：“走”表示移动，不能与“鼓掌”搭配说明观众的状态。"}, {"text": "躺", "is_correct": false, "explanation": "语义：观众躺着鼓掌与比赛场景不合，也与起身的意思相反。"}], "explanations": {"起来": "起来：表示由坐变为站立，符合“比赛开始了，观众都……鼓掌”的语境。", "跑": "搭配：“跑”表示快速移动，不能与“鼓掌”搭配说明观众的动作状态。", "走": "搭配：“走”表示移动，不能与“鼓掌”搭配说明观众的状态。", "躺": "语义：观众躺着鼓掌与比赛场景不合，也与起身的意思相反。"}, "sentence_index": 0, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从楼梯上起来，到了二楼。", "explanation": "这里应该用〈上〉。起来指由坐或躺变成站，不能指往高处走。"}, {"text": "他站累了，就在椅子上起来休息。", "explanation": "这里应该用〈坐下〉。起来是由坐变站，在椅子上休息要“坐下”。"}, {"text": "下课了，大家从教室起来回家。", "explanation": "这里应该用〈出来〉。起来指起身站立，不能表示离开某个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起来", "is_correct": true, "explanation": "起来：表示从床上起身，符合“孩子睡醒了，自己从床上……穿衣服”的语境。"}, {"text": "躺", "is_correct": false, "explanation": "语义：“躺”指躺卧，与睡醒后起身穿衣的动作相反"}, {"text": "站", "is_correct": false, "explanation": "搭配：“站”不能表示从床上离开后再穿衣服的动作，搭配不当。"}, {"text": "睡", "is_correct": false, "explanation": "语义：句首已说“睡醒了”，“睡”与前文重复，且与起身穿衣不合。"}], "explanations": {"起来": "起来：表示从床上起身，符合“孩子睡醒了，自己从床上……穿衣服”的语境。", "躺": "语义：“躺”指躺卧，与睡醒后起身穿衣的动作相反", "站": "搭配：“站”不能表示从床上离开后再穿衣服的动作，搭配不当。", "睡": "语义：句首已说“睡醒了”，“睡”与前文重复，且与起身穿衣不合。"}, "sentence_index": 6, "correct_answer": "起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "站了一天，他回家就在床上起来了。", "explanation": "这里应该用〈躺下〉。起来是由躺变站，到床上休息要“躺下”。"}, {"text": "飞机起来了，慢慢飞上了天。", "explanation": "这里应该用〈起飞〉。起来指人由坐或躺变成站，不用于飞机离开地面。"}, {"text": "电梯坏了，我们从一楼起来到五楼。", "explanation": "这里应该用〈走上〉。起来指起身站立，不能表示往楼上走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一听到门铃，就从沙发上起来着。", "corrected_sentence": "他一听到门铃，就从沙发上起来了。", "error_description": "错误形式：“起来着”；正确形式：“起来了”。起身的动作已经完成要用“了”，“起来”不能加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27768, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师进来了，同学们都起来着。", "corrected_sentence": "老师进来了，同学们都起来了。", "error_description": "错误形式：“起来着”；正确形式：“起来了”。起身的动作已经完成要用“了”，“起来”不能加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
