INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示把某样东西拿来做某件事，说明它的用途。", "primary_collocate": null, "pronunciation": "yòng lái", "ipa": "jʊŋ˥˩ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这把刀用来切菜。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "筷子是用来吃饭的。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子用来喝水。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "手机可以用来看书。", "target_word": "用来", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用来写字的笔坏了。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱用来买书了。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上的纸是用来画画的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个本子是用来记生词的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间是用来学习的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱是用来放吃的东西的。", "target_word": "用来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "动词，后面接动词，表示某物被拿来做某件事的用途", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用来", "is_correct": true, "explanation": "“用来”表示用途，这把刀正是用来切菜的。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”的主语须是有感情的人，刀不能喜欢切菜。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后接活动或事件，不能接“切菜”这样的动作。"}, {"text": "管理", "is_correct": false, "explanation": "搭配：“管理”的对象是人、事务或单位，不能接“切菜”。"}], "explanations": {"用来": "“用来”表示用途，这把刀正是用来切菜的。", "喜欢": "语义：“喜欢”的主语须是有感情的人，刀不能喜欢切菜。", "参加": "搭配：“参加”后接活动或事件，不能接“切菜”这样的动作。", "管理": "搭配：“管理”的对象是人、事务或单位，不能接“切菜”。"}, "sentence_index": 0, "correct_answer": "用来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用来去学校。", "explanation": "这里不能用〈用来〉。〈用来〉的主语应是物品，“他”是人，应说“他骑车去学校”。"}, {"text": "明天用来下雨。", "explanation": "这里应该用〈会〉。〈用来〉表示为了某个目的使用物品或做事，“下雨”是自然现象，不能作为目的，应说“明天会下雨”。"}, {"text": "用来省钱，我每天带午饭。", "explanation": "这里应该用〈为了〉。〈用来〉多用于物品的用途，人主动做事表示目的时应说“为了省钱，我每天带午饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用来", "is_correct": true, "explanation": "“用来”表示用途，这里说纸是用来画画的。"}, {"text": "负责", "is_correct": false, "explanation": "语义：“负责”的主语须是能承担责任的人，纸不能负责画画。"}, {"text": "擅长", "is_correct": false, "explanation": "语义：“擅长”的主语须是有技能的人，纸不能擅长画画。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”需要有参与者，纸不能讨论画画。"}], "explanations": {"用来": "“用来”表示用途，这里说纸是用来画画的。", "负责": "语义：“负责”的主语须是能承担责任的人，纸不能负责画画。", "擅长": "语义：“擅长”的主语须是有技能的人，纸不能擅长画画。", "讨论": "配价：“讨论”需要有参与者，纸不能讨论画画。"}, "sentence_index": 6, "correct_answer": "用来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间教室用来学生上课。", "explanation": "这里应该用〈供〉。〈用来〉表示物品的用途，不能直接把人作为受益者，应说“供学生上课”。"}, {"text": "这家商店用来顾客买东西。", "explanation": "这里应该用〈方便〉。〈用来〉的宾语应是物品的用途，不能直接把顾客作为使用者，应说“这家商店方便顾客买东西”。"}, {"text": "这间屋子用来老人的休息。", "explanation": "这里应该用〈供〉。“用来”不能接“老人的休息”这样的名词短语，应说“供老人休息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把刀用来用削水果。", "corrected_sentence": "这把刀用来削水果。", "error_description": "错误：“用来”后面多加了一个“用”（用来用削水果）。正确：应说“用来削水果”，“用来”后直接接动词，不能再加“用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27770, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个盒子是用来用来装针的。", "corrected_sentence": "这个盒子是用来装针的。", "error_description": "错误：“用来”重复出现（用来用来装针）。正确：只用一个“用来”，说“是用来装针的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
