INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把水送到田里，让庄稼喝到水。", "primary_collocate": null, "pronunciation": "guàn gài", "ipa": "kwan˥˩ kai˥˩", "syllable_count": 2, "sentences": [{"text": "农民用河水灌溉田地。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河灌溉着山下的农田。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天不下雨，农民只好灌溉稻田。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，人们要灌溉麦田。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套新机器可以灌溉很大的一片地。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修了一条水渠来灌溉庄稼。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灌溉玉米地需要很多水。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上去灌溉菜地。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水库里的水用来灌溉附近的农田。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太干，我们得把河水引来灌溉。", "target_word": "灌溉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "灌溉了", "label": "体标"}, {"form": "灌溉着", "label": "体标"}, {"form": "灌溉过", "label": "体标"}, {"form": "灌溉系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "引水浇田地，供庄稼生长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌溉", "is_correct": true, "explanation": "正确：“灌溉”指引水浇田，与“用河水___田地”相符。"}, {"text": "饮", "is_correct": false, "explanation": "语义：“饮”是让人或牲口喝水，田地不能“饮”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象多为衣物、身体，不说洗田地。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人、牲口或婴儿，不说喂田地。"}], "explanations": {"灌溉": "正确：“灌溉”指引水浇田，与“用河水___田地”相符。", "饮": "语义：“饮”是让人或牲口喝水，田地不能“饮”。", "洗": "搭配：“洗”的对象多为衣物、身体，不说洗田地。", "喂": "搭配：“喂”的对象是人、牲口或婴儿，不说喂田地。"}, "sentence_index": 0, "correct_answer": "灌溉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们用管道把天然气灌溉到城市。", "explanation": "这里应该用〈输送〉。“灌溉”指引水浇灌农田，天然气等要用“输送”。"}, {"text": "他把资料灌溉进电脑里。", "explanation": "这里应该用〈输入〉。“灌溉”只用于给农田引水，数据要说“输入”。"}, {"text": "医生给病人灌溉了一针药。", "explanation": "这里应该用〈注射〉。“灌溉”指给农田引水，给人打针要用“注射”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌溉", "is_correct": true, "explanation": "正确：“灌溉”与“玉米地需要很多水”相符，说明田间需要浇水。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”是把成熟的庄稼割下来，与“需要很多水”的语境不符。"}, {"text": "放牧", "is_correct": false, "explanation": "语义：“放牧”是让牲畜在草地上吃草，不用于玉米地。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶、草坪等，不用于玉米地。"}], "explanations": {"灌溉": "正确：“灌溉”与“玉米地需要很多水”相符，说明田间需要浇水。", "收割": "语义：“收割”是把成熟的庄稼割下来，与“需要很多水”的语境不符。", "放牧": "语义：“放牧”是让牲畜在草地上吃草，不用于玉米地。", "修剪": "搭配：“修剪”的对象是枝叶、草坪等，不用于玉米地。"}, "sentence_index": 6, "correct_answer": "灌溉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友灌溉了一杯酒。", "explanation": "这里应该用〈倒〉。“灌溉”只用于给田地引水，给人倒酒不能说灌溉。"}, {"text": "我在杯子里灌溉了一些果汁。", "explanation": "这里应该用〈倒〉。“灌溉”只用于农田，往杯子里倒果汁不能说灌溉。"}, {"text": "服务员给客人灌溉了一壶茶。", "explanation": "这里应该用〈倒〉。“灌溉”不用于倒茶，倒茶要说“倒”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷每天早上都去灌溉了菜地。", "corrected_sentence": "爷爷每天早上都去灌溉菜地。", "error_description": "体标误用：“每天早上都”表示经常性、习惯性的动作，动词“灌溉”后不能加“了”。正确应为“每天早上都去灌溉菜地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年夏天，这片田曾经用河水灌溉着。", "corrected_sentence": "去年夏天，这片田曾经用河水灌溉过。", "error_description": "动态助词误用：“曾经”表示经历，应与“过”搭配，“着”表示动作持续，两者不能搭配。正确应为“灌溉过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
