INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西被拉或压时，里面产生的力。", "primary_collocate": null, "pronunciation": "yìng lì", "ipa": "iŋ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "拉橡皮筋的时候，里面有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "东西一压，里面就会有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁条弯了，是因为应力太大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力是东西里面产生的力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用力拉绳子，绳子里有应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力越大，应力也越大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用弹簧给我们讲应力。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃杯里有应力，所以容易裂。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根木头压断了，应力太大。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "应力小，东西就不容易坏。", "target_word": "应力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应力集中", "label": "复合词"}, {"form": "残余应力", "label": "复合词"}], "register": "通用", "sense_fingerprint": "日常：东西被拉或压时里面产生的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d11fcc8-d62b-4b13-af83-f4f5872bc024') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。应力指东西被拉或压时里面产生的力。"}, {"text": "英里", "is_correct": false, "explanation": "声调混淆：yīng lǐ 与 yìng lì 声母韵母相同，只差声调，意思是长度单位英里。"}, {"text": "盈利", "is_correct": false, "explanation": "声调混淆：yíng 与 yìng 只差声调，意思是盈利。"}, {"text": "用力", "is_correct": false, "explanation": "yòng 与 yìng 声调相同，但韵母不同（ong 与 ing），意思是用力。"}], "explanations": {"应力": "正确答案。应力指东西被拉或压时里面产生的力。", "英里": "声调混淆：yīng lǐ 与 yìng lì 声母韵母相同，只差声调，意思是长度单位英里。", "盈利": "声调混淆：yíng 与 yìng 只差声调，意思是盈利。", "用力": "yòng 与 yìng 声调相同，但韵母不同（ong 与 ing），意思是用力。"}, "sentence_index": null, "correct_answer": "应力"}, "level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。拉橡皮筋时，橡皮筋里面产生的就是应力。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是东西被拉时里面产生的力，与句中语境不符。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会在橡皮筋里产生，与拉伸的语境不符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的外形特征，不能说东西里面有身高。"}], "explanations": {"应力": "正确答案。拉橡皮筋时，橡皮筋里面产生的就是应力。", "颜色": "语义：颜色不是东西被拉时里面产生的力，与句中语境不符。", "饭菜": "语义：饭菜不会在橡皮筋里产生，与拉伸的语境不符。", "身高": "体貌：身高是人的外形特征，不能说东西里面有身高。"}, "sentence_index": 0, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的应力很大。", "explanation": "这里应该用〈力气〉。应力是东西被拉或压时里面产生的力，指人身上的力气不说应力。"}, {"text": "这次考试我的应力很大。", "explanation": "这里应该用〈压力〉。应力指东西里面的力，考试带来的心理负担要用“压力”。"}, {"text": "空气应力很大。", "explanation": "这里应该用〈阻力〉。应力是东西里面产生的力，外部阻碍运动的力要用“阻力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应力", "is_correct": true, "explanation": "正确答案。老师用弹簧讲的是东西被拉或压时里面产生的应力。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不能被“讲”，且与弹簧的物理语境不符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭与用弹簧讲解的内容无关。"}, {"text": "楼梯", "is_correct": false, "explanation": "搭配：“讲”的宾语应是知识内容，楼梯不能作为讲的对象。"}], "explanations": {"应力": "正确答案。老师用弹簧讲的是东西被拉或压时里面产生的应力。", "饺子": "语义：饺子不能被“讲”，且与弹簧的物理语境不符。", "早饭": "语义：早饭与用弹簧讲解的内容无关。", "楼梯": "搭配：“讲”的宾语应是知识内容，楼梯不能作为讲的对象。"}, "sentence_index": 6, "correct_answer": "应力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他工作太忙，心里应力很大。", "explanation": "这里应该用〈压力〉。应力是东西被拉或压时里面的力，心理负担要用“压力”。"}, {"text": "苹果掉下来是因为地球的应力。", "explanation": "这里应该用〈引力〉。地球吸引东西的力叫引力，不是东西里面的应力。"}, {"text": "这个学生很有应力，跑得很快。", "explanation": "这里应该用〈力气〉。人身上的力气不说应力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "绳子有里应力，所以会断。", "corrected_sentence": "绳子里有应力，所以会断。", "error_description": "位置错误：「有里应力」应为「里有应力」。方位词“里”要放在“有”之前，表示在绳子内部。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27778, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "绳子拉紧后，里面的应力变大着。", "corrected_sentence": "绳子拉紧后，里面的应力变大了。", "error_description": "动态助词错误：「变大着」应为「变大了」。变化已经发生，要用“了”，不用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d84cfb1-221a-4b10-bbee-f3a36a0ddda0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
