INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体里流出一些东西，比如眼泪或口水。", "primary_collocate": null, "pronunciation": "fēn mì", "ipa": "fən˥˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "看到好吃的，嘴里会分泌口水。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闻到饭菜的香味，我的嘴里就开始分泌口水。", "target_word": "分泌", "complexity_tier": "T3", "furigana": "fēn mì", "sentence_source": "generated"}, {"text": "宝宝睡觉时，嘴巴分泌很多口水。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到别人吃火锅，我的嘴里也开始分泌口水。", "target_word": "分泌", "complexity_tier": "T3", "furigana": "fēn mì", "sentence_source": "generated"}, {"text": "宝宝饿的时候，嘴里会分泌很多口水。", "target_word": "分泌", "complexity_tier": "T3", "furigana": "fēn mì", "sentence_source": "generated"}, {"text": "闻到香味，我的嘴里开始分泌口水。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人饿得厉害的时候，胃里会分泌胃液。", "target_word": "分泌", "complexity_tier": "T3", "furigana": "fēn mì", "sentence_source": "generated"}, {"text": "喝了一大口醋，嘴里马上分泌出很多口水。", "target_word": "分泌", "complexity_tier": "T3", "furigana": "fēn mì", "sentence_source": "generated"}, {"text": "吃酸柠檬时，嘴里会分泌很多口水。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿长牙时，会分泌更多口水。", "target_word": "分泌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分泌了", "label": "体标"}, {"form": "分泌过", "label": "体标"}, {"form": "分泌物", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体流出眼泪、口水、汗水等日常液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27780, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：分泌 fēn mì，指身体的腺体产生并排出液体。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "fēng 与 fēn 韵母不同（-ng 与 -n），意思是蜂蜜。"}, {"text": "分米", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，意思是分米（长度单位）。"}, {"text": "分立", "is_correct": false, "explanation": "lì 与 mì 声母不同（l 与 m），意思是分开设立。"}], "explanations": {"分泌": "正确：分泌 fēn mì，指身体的腺体产生并排出液体。", "蜂蜜": "fēng 与 fēn 韵母不同（-ng 与 -n），意思是蜂蜜。", "分米": "mǐ（第三声）与 mì（第四声）声调不同，意思是分米（长度单位）。", "分立": "lì 与 mì 声母不同（l 与 m），意思是分开设立。"}, "sentence_index": null, "correct_answer": "分泌"}, "level_3": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：“嘴里会分泌口水”是看到食物时的生理反应，与句意相符。"}, {"text": "咀嚼", "is_correct": false, "explanation": "搭配：“咀嚼”的对象是食物，不说“咀嚼口水”。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”需要可燃物，“口水”不能被点燃。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不接“口水”作宾语，此处搭配不成立。"}], "explanations": {"分泌": "正确：“嘴里会分泌口水”是看到食物时的生理反应，与句意相符。", "咀嚼": "搭配：“咀嚼”的对象是食物，不说“咀嚼口水”。", "点燃": "语义：“点燃”需要可燃物，“口水”不能被点燃。", "唱": "配价：“唱”不接“口水”作宾语，此处搭配不成立。"}, "sentence_index": 0, "correct_answer": "分泌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雨水从屋顶分泌下来。", "explanation": "这里应该用〈流〉。分泌指身体内部产生并排出液体，雨水从外部流下不能说分泌。"}, {"text": "树叶从树上分泌下来了。", "explanation": "这里应该用〈掉〉。分泌是生物体的生理过程，树叶脱落不能用分泌。"}, {"text": "衣服上分泌了泥。", "explanation": "这里应该用〈沾〉。分泌是生物体内的生理过程，衣服沾上泥不能用分泌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分泌", "is_correct": true, "explanation": "正确：“胃里会分泌胃液”说明饥饿时的生理变化，与句意相符。"}, {"text": "抄写", "is_correct": false, "explanation": "语义：“抄写”的对象是文字，不能是胃液。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”搭配植物或田地，不接“胃液”。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”要求场所或物体作宾语，此处的“胃液”不构成搭配。"}], "explanations": {"分泌": "正确：“胃里会分泌胃液”说明饥饿时的生理变化，与句意相符。", "抄写": "语义：“抄写”的对象是文字，不能是胃液。", "浇灌": "搭配：“浇灌”搭配植物或田地，不接“胃液”。", "打扫": "配价：“打扫”要求场所或物体作宾语，此处的“胃液”不构成搭配。"}, "sentence_index": 6, "correct_answer": "分泌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子里的水分泌出来了。", "explanation": "这里应该用〈溢出〉。分泌指生物体内产生并排出液体，杯中的水溢出不能说分泌。"}, {"text": "他分泌出了一些牙膏。", "explanation": "这里应该用〈挤出〉。牙膏是人挤出来的，人不能分泌牙膏。"}, {"text": "墙上分泌出了水珠。", "explanation": "这里应该用〈渗出〉。墙壁不是生物体，不能分泌水珠。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想到酸梅，嘴里就分泌了出口水。", "corrected_sentence": "想到酸梅，嘴里就分泌出了口水。", "error_description": "补语位置错误：“分泌出”中的“出”是补语，须紧接“分泌”，不能放在“了”和宾语之间。正确说法是“分泌出了口水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝宝醒来后，嘴里会分泌了口水。", "corrected_sentence": "宝宝醒来后，嘴里会分泌口水。", "error_description": "体标错误：“会”表示可能或习惯性的情况，这里描述的是生理反应，“分泌”后不应加“了”。正确说法是“会分泌口水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
