INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "身体里把吃进去的东西变成能量和需要的部分，再把没用的东西排出去的过程。", "primary_collocate": null, "pronunciation": "dài xiè zuò yòng", "ipa": "tai˥˩ ɕiɛ˥˩ tsuɔ˥˩ yŋ˥˩", "syllable_count": 4, "sentences": [{"text": "年纪大了，身体的代谢作用会变慢。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多运动能让代谢作用快一点。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠不好会影响代谢作用。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的代谢作用快，吃多少都不胖。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝水有助于身体的代谢作用。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我的代谢作用有点慢。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上吃早饭可以促进代谢作用。", "target_word": "代谢作用", "complexity_tier": "T3", "furigana": "zǎo shang chī zǎo fàn kě yǐ cù jìn dài xiè zuò yòng", "sentence_source": "generated"}, {"text": "身体的代谢作用把食物变成能量。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长身体，代谢作用特别快。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上吃太多，代谢作用来不及处理。", "target_word": "代谢作用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代谢", "label": "简称"}, {"form": "代謝作用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人体把食物变成能量并排出废物的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcc7d272-1178-4374-b7d4-e14c7e02a6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27782, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代谢作用", "is_correct": true, "explanation": "正确：“代谢作用”指身体把食物变成能量的过程，此处说年纪大后这一过程变慢。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是身体的生理过程，“身体的价格会变慢”不成立。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与身体的生理过程无关，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“会变慢”不能与“天气”搭配，句意不通。"}], "explanations": {"代谢作用": "正确：“代谢作用”指身体把食物变成能量的过程，此处说年纪大后这一过程变慢。", "价格": "语义：价格不是身体的生理过程，“身体的价格会变慢”不成立。", "乐器": "语义：乐器与身体的生理过程无关，句子不通。", "天气": "搭配：“会变慢”不能与“天气”搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "代谢作用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆自行车的代谢作用很快。", "explanation": "〈代谢作用〉只属于生物体，这里却当作〈车速〉来用。应说「这辆自行车很快」。"}, {"text": "他的代谢作用每天去图书馆。", "explanation": "〈代谢作用〉是过程，不能像人一样去某个地方，这里把它当作〈人〉来用。应说「他每天去图书馆」。"}, {"text": "他的代谢作用吵醒了邻居。", "explanation": "〈代谢作用〉是生理过程，不会发出声音，这里把它当作〈发声体〉来用。应说「他半夜大声说话，吵醒了邻居」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代谢作用", "is_correct": true, "explanation": "正确：“代谢作用”指身体把食物变成能量的过程，“促进”的对象正是这一过程。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是身体的过程，不能被“促进”。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是身体的生理过程，句中不能“促进”它。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“促进”通常搭配过程、关系或发展，不能搭配“声音”。"}], "explanations": {"代谢作用": "正确：“代谢作用”指身体把食物变成能量的过程，“促进”的对象正是这一过程。", "颜色": "语义：颜色不是身体的过程，不能被“促进”。", "歌曲": "语义：歌曲不是身体的生理过程，句中不能“促进”它。", "声音": "搭配：“促进”通常搭配过程、关系或发展，不能搭配“声音”。"}, "sentence_index": 6, "correct_answer": "代谢作用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份蛋糕的代谢作用很甜。", "explanation": "〈代谢作用〉是生理过程，这里却当作〈味道〉来用，不能用来形容甜不甜。应说「这份蛋糕很甜」。"}, {"text": "代谢作用昨天下午开会了。", "explanation": "〈代谢作用〉是生理过程，这里却当作〈团体〉来用，不能开会。应说「我们昨天下午开会了」。"}, {"text": "代谢作用的颜色是红的。", "explanation": "〈代谢作用〉是生理过程，没有颜色，这里当作〈物体〉来用。应说「血液是红的」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "多喝水能让代谢作用胖一些。", "corrected_sentence": "多喝水能让代谢作用快一些。", "error_description": "搭配错误：代谢作用只能说“快”或“慢”，不能说“胖”；应说“代谢作用快一些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个年纪的孩子，代谢作用特别胖。", "corrected_sentence": "这个年纪的孩子，代谢作用特别快。", "error_description": "搭配错误：形容代谢作用应说“快”或“慢”，不能说“胖”；应说“代谢作用特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
