INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有机肥是用动植物做成的肥料，能让植物长得更好。", "primary_collocate": null, "pronunciation": "yǒu jī féi", "ipa": "iou˨˩˦ tɕi˥ fei˧˥", "syllable_count": 3, "sentences": [{"text": "妈妈在花盆里放了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥是用动物粪便做成的。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋有机肥可以用来种菜。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用了有机肥，青菜长得很快。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷自己在院子里做有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥没有化肥那么快见效。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥放久了会有一点臭味。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给西红柿浇水，又加了有机肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的有机肥都是牛粪做的。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有机肥能让土地更肥。", "target_word": "有机肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有机肥料", "label": "复合"}, {"form": "有機肥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用动植物做成、让植物长得更好的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcc7d272-1178-4374-b7d4-e14c7e02a6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：有机肥是施在花盆土里的肥料，与“花盆里”和“放了”相符。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是施在花盆里的肥料。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油易燃，不能放在花盆里给植物用。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“牛奶”是液体，在花盆里应说“倒”，不与“放了”搭配。"}], "explanations": {"有机肥": "正确：有机肥是施在花盆土里的肥料，与“花盆里”和“放了”相符。", "饼干": "语义：饼干是食品，不是施在花盆里的肥料。", "汽油": "语义：汽油易燃，不能放在花盆里给植物用。", "牛奶": "搭配：“牛奶”是液体，在花盆里应说“倒”，不与“放了”搭配。"}, "sentence_index": 0, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用了有机肥，虫子就死了。", "explanation": "这里应该用〈农药〉。有机肥用来增加土壤肥力，不能杀虫，杀虫要用农药。"}, {"text": "播下有机肥，等它发芽。", "explanation": "这里应该用〈种子〉。有机肥是肥料，不能播下去发芽，播下的应是种子。"}, {"text": "天冷了，我穿上了有机肥。", "explanation": "这里应该用〈外套〉。有机肥是肥料，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有机肥", "is_correct": true, "explanation": "正确：有机肥是由有机物质制成的，放久会发酵产生气味，与“臭味”相符。"}, {"text": "钢材", "is_correct": false, "explanation": "语义：钢材不会腐烂，也不会产生臭味。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“放久了会有臭味”通常说易腐物，“玻璃”不能与“臭味”搭配。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池放久不会因腐败而产生臭味。"}], "explanations": {"有机肥": "正确：有机肥是由有机物质制成的，放久会发酵产生气味，与“臭味”相符。", "钢材": "语义：钢材不会腐烂，也不会产生臭味。", "玻璃": "搭配：“放久了会有臭味”通常说易腐物，“玻璃”不能与“臭味”搭配。", "电池": "语义：电池放久不会因腐败而产生臭味。"}, "sentence_index": 6, "correct_answer": "有机肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "牛每天要吃有机肥。", "explanation": "这里应该用〈饲料〉。有机肥是肥料，不能给牛吃，给牛吃的是饲料。"}, {"text": "用有机肥洗手。", "explanation": "这里应该用〈肥皂〉。有机肥不能用来洗手，“肥皂”与“肥”字相近，学习者易混淆，洗手应使用肥皂。"}, {"text": "他往汽车里加了有机肥，车就能开了。", "explanation": "这里应该用〈汽油〉。有机肥是给植物用的肥料，不能让汽车开动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上放着两个有机肥。", "corrected_sentence": "我家阳台上放着两袋有机肥。", "error_description": "量词错误：“有机肥”应用“袋”计量，说“两袋有机肥”；用“个”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27784, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子角落堆着一堆有机肥们。", "corrected_sentence": "院子角落堆着一堆有机肥。", "error_description": "词缀错误：“们”不能加在“有机肥”后面。“们”只用于指人或拟人的复数，表示物质的肥料应直接说“一堆有机肥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6e827a1-0877-4189-ad75-857b5ca92182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
