INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在商店里卖的。", "primary_collocate": null, "pronunciation": "shì shòu", "ipa": "ʂɨ˥˩ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "市售面包比家里做的贵。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些饼干都是市售的。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喝市售饮料，只喝白开水。", "target_word": "市售", "complexity_tier": "T3", "furigana": "shì shòu", "sentence_source": "generated"}, {"text": "市售酱油有很多牌子。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市售的花盆太小了。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用市售肥料给花施肥。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市售洗发水里有香味。", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市售茶叶种类很多，价格差别也很大。", "target_word": "市售", "complexity_tier": "T3", "furigana": "shì shòu", "sentence_source": "generated"}, {"text": "市售牛肉每斤多少钱？", "target_word": "市售", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "自己做的饺子比市售的好吃。", "target_word": "市售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在商店里买得到的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8690e496-04c6-47d2-9989-640dbeda1136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "制售", "is_correct": false, "explanation": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。"}, {"text": "世守", "is_correct": false, "explanation": "shì shǒu 第二音节声调不同（shǒu 与 shòu），意思是世代守护。"}, {"text": "失手", "is_correct": false, "explanation": "shī shǒu 两个音节的声调都不同，意思是不小心做错或弄坏。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "制售": "zhì shòu（第四声）与 shì shòu 声母不同（zh 与 sh），意思是生产并销售。", "世守": "shì shǒu 第二音节声调不同（shǒu 与 shòu），意思是世代守护。", "失手": "shī shǒu 两个音节的声调都不同，意思是不小心做错或弄坏。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。与“面包比家里做的贵”形成比较，指在商店买的面包。"}, {"text": "自家", "is_correct": false, "explanation": "语义：“自家”与“家里做的”意思重复，句子自相矛盾。"}, {"text": "家常", "is_correct": false, "explanation": "搭配：“家常”多修饰菜肴，一般不说家常面包。"}, {"text": "自制", "is_correct": false, "explanation": "语义：自制面包与“家里做的”同属自家制作，比较对象矛盾。"}], "explanations": {"市售": "正确答案。与“面包比家里做的贵”形成比较，指在商店买的面包。", "自家": "语义：“自家”与“家里做的”意思重复，句子自相矛盾。", "家常": "搭配：“家常”多修饰菜肴，一般不说家常面包。", "自制": "语义：自制面包与“家里做的”同属自家制作，比较对象矛盾。"}, "sentence_index": 0, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自己做的酱油是市售的，很好吃。", "explanation": "这里应该用〈自制〉。市售指在商店里卖的，自己做的酱油不能说是市售的。"}, {"text": "这些蔬菜是市售的，不用花钱，很新鲜。", "explanation": "这里应该用〈自产〉。市售指在商店里卖的，此处说不用花钱，应说自产的。"}, {"text": "这幅画是市售的，从来不卖。", "explanation": "这里应该用〈私藏〉。市售指在商店里卖的，与“从来不卖”自相矛盾；私藏指自己收藏，从不拿出来卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。shì shòu 指在商店里卖的。"}, {"text": "失守", "is_correct": false, "explanation": "shī shǒu 两个音节的声调都不同，意思是丢掉阵地。"}, {"text": "失收", "is_correct": false, "explanation": "shī shōu 两个音节的声调都不同，意思是农作物歉收。"}, {"text": "实收", "is_correct": false, "explanation": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}], "explanations": {"市售": "正确答案。shì shòu 指在商店里卖的。", "失守": "shī shǒu 两个音节的声调都不同，意思是丢掉阵地。", "失收": "shī shōu 两个音节的声调都不同，意思是农作物歉收。", "实收": "shí shōu 两个音节的声调都不同，意思是实际收到的。"}, "sentence_index": null, "correct_answer": "市售"}, "level_3": {"options": [{"text": "市售", "is_correct": true, "explanation": "正确答案。指在商店买的洗发水，与“有香味”不矛盾。"}, {"text": "无香", "is_correct": false, "explanation": "语义：“无香”与后文“有香味”直接矛盾。"}, {"text": "无味", "is_correct": false, "explanation": "语义：“无味”与后文“有香味”直接矛盾。"}, {"text": "臭", "is_correct": false, "explanation": "语义：“臭”表示难闻，与后文“有香味”直接矛盾。"}], "explanations": {"市售": "正确答案。指在商店买的洗发水，与“有香味”不矛盾。", "无香": "语义：“无香”与后文“有香味”直接矛盾。", "无味": "语义：“无味”与后文“有香味”直接矛盾。", "臭": "语义：“臭”表示难闻，与后文“有香味”直接矛盾。"}, "sentence_index": 6, "correct_answer": "市售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有个市售的主意，大家都很佩服。", "explanation": "这里应该用〈现成〉。市售指在商店里卖的，主意不能在商店里买，应说现成的主意。"}, {"text": "这个问题是市售的，我们一起讨论。", "explanation": "这里应该用〈共同〉。市售指在商店里卖的商品，问题不是商品；大家都关心的问题应说共同的问题。"}, {"text": "我的朋友是市售的，我很喜欢他。", "explanation": "这里应该用〈亲密〉。市售只能指商品，不能用来形容人；表示关系近，应说亲密的朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这瓶酱油是市售，买来就能用。", "corrected_sentence": "这瓶酱油是市售的，买来就能用。", "error_description": "“市售”作谓语时后面要加“的”，应说“是市售的”，不能只说“是市售”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种面包是市售，我每天都买。", "corrected_sentence": "这种面包是市售的，我每天都买。", "error_description": "「市售」作谓语时后面要加「的」，应说「是市售的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85f1dd45-87d6-4a03-8c0c-feb4b82a9282') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
