INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27788, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蛋白质是身体需要的一种营养。", "primary_collocate": null, "pronunciation": "dàn bái zhì", "ipa": "tan˥˩ paɪ˧˥ ʈʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "鱼和豆腐都含有丰富的蛋白质。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动以后，多吃点蛋白质对身体好。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他每天需要补充蛋白质。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长身体，不能缺少蛋白质。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸡胸肉的蛋白质多，脂肪少。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早饭吃一个鸡蛋，就能补充蛋白质。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "素食者可以从豆类里得到蛋白质。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶里有蛋白质，还有钙。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想减肥，所以少吃米饭，多吃蛋白质。", "target_word": "蛋白质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种食物的蛋白质含量很高。", "target_word": "蛋白质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "动物蛋白质", "label": "复合"}, {"form": "植物蛋白质", "label": "复合"}, {"form": "蛋白質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鱼、肉、蛋、豆类中身体需要的营养", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec18da45-1d04-4db4-bc9e-52cf006b7b9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27788, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蛋白质", "is_correct": true, "explanation": "蛋白质是食物中常见的营养成分，鱼和豆腐里含有丰富的它。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不是食物成分，鱼和豆腐里不含汽油。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“含有丰富的”用于说明食物的营养成分，钢铁不属于这类搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是食物，也不含营养，不能用“含有丰富的”来形容。"}], "explanations": {"蛋白质": "蛋白质是食物中常见的营养成分，鱼和豆腐里含有丰富的它。", "汽油": "语义：汽油不是食物成分，鱼和豆腐里不含汽油。", "钢铁": "搭配：“含有丰富的”用于说明食物的营养成分，钢铁不属于这类搭配。", "石头": "语义：石头不是食物，也不含营养，不能用“含有丰富的”来形容。"}, "sentence_index": 0, "correct_answer": "蛋白质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "炒菜前要先放一点蛋白质。", "explanation": "这里应该用〈盐〉。炒菜前放的是盐来调味，蛋白质是营养物质，不是调味品。"}, {"text": "鸡蛋的蛋白质很嫩。", "explanation": "这里应该用〈蛋白〉。鸡蛋里的白色部分叫蛋白，蛋白质指营养物质。"}, {"text": "红茶里加一勺蛋白质。", "explanation": "这里应该用〈糖〉。红茶里加的是糖来调甜，蛋白质是营养成分，不用来给红茶调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27788, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蛋白质", "is_correct": true, "explanation": "豆类是蛋白质的常见来源，符合“从豆类里得到”的说法。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是矿物燃料，不是豆类中的成分，不能从豆类里得到。"}, {"text": "电池", "is_correct": false, "explanation": "语义：电池是储存电能的装置，不能从豆类里得到。"}, {"text": "塑料", "is_correct": false, "explanation": "搭配：“从……里得到”后接的应是天然食物中的营养，塑料是人造材料，不与此搭配。"}], "explanations": {"蛋白质": "豆类是蛋白质的常见来源，符合“从豆类里得到”的说法。", "石油": "语义：石油是矿物燃料，不是豆类中的成分，不能从豆类里得到。", "电池": "语义：电池是储存电能的装置，不能从豆类里得到。", "塑料": "搭配：“从……里得到”后接的应是天然食物中的营养，塑料是人造材料，不与此搭配。"}, "sentence_index": 6, "correct_answer": "蛋白质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用蛋白质擦干净了桌子。", "explanation": "这里应该用〈抹布〉。擦桌子要用抹布，蛋白质是营养物质，不能用来擦东西。"}, {"text": "这盘蛋白质切得薄薄的，装在盘子里很好看。", "explanation": "这里应该用〈豆腐〉。蛋白质是营养成分，没有实体可以切片装盘；切片装盘的是豆腐。"}, {"text": "路面上积着一层蛋白质，走路很滑。", "explanation": "这里应该用〈积水〉。下雨后路面上积的是水，蛋白质是营养成分，不会积成一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27788, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只蛋白质，身体需要它。", "corrected_sentence": "这是一种蛋白质，身体需要它。", "error_description": "量词错误：“蛋白质”不用“只”，应说“一种蛋白质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27788, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天要多吃过蛋白质。", "corrected_sentence": "我每天要多吃蛋白质。", "error_description": "体标错误：“要”表示打算，动词后不能加“过”，应说“要多吃蛋白质”，不说“要多吃过蛋白质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '663775be-f27c-44e2-a340-d8c04f699ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
