INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西裂成小块了。", "primary_collocate": null, "pronunciation": "pò suì", "ipa": "pʰo˥˩ sueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "盘子掉了，破碎了一地。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的眼镜掉在地上，镜片破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰一踩就破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饼干太脆，一碰就破碎。", "target_word": "破碎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地震后，房子的窗户都破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，杯子破碎了会伤手。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不小心，让灯泡破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玻璃很薄，容易破碎。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旧花盆放了很久，已经破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球砸到车窗，玻璃破碎了。", "target_word": "破碎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "破碎了", "label": "完成体"}, {"form": "破碎过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "东西裂成小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1464a407-3635-4c26-9c56-965320c82102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，盘子掉了不会唱。"}, {"text": "破碎", "is_correct": true, "explanation": "正确。指东西裂成小块，与“盘子掉了”的语境一致。"}, {"text": "绽放", "is_correct": false, "explanation": "搭配：“绽放”多用于花朵，不能说盘子绽放。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指种子长出嫩芽，与摔碎的盘子无关。"}], "explanations": {"唱": "语义：“唱”指发出歌声，盘子掉了不会唱。", "破碎": "正确。指东西裂成小块，与“盘子掉了”的语境一致。", "绽放": "搭配：“绽放”多用于花朵，不能说盘子绽放。", "发芽": "语义：“发芽”指种子长出嫩芽，与摔碎的盘子无关。"}, "sentence_index": 0, "correct_answer": "破碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条水管冻了一夜，已经破碎了，水流了一地。", "explanation": "这里应该用〈破裂〉。水管裂开口子应说“破裂”，破碎指东西碎成很多小块。"}, {"text": "这双鞋穿了三年，鞋底已经破碎了。", "explanation": "这里应该用〈磨损〉。鞋底变薄变旧是磨损，没有碎成小块，不能说破碎。"}, {"text": "这根绳子在大风中破碎了，风筝飞走了。", "explanation": "这里应该用〈断裂〉。绳子整根断开应说“断裂”，破碎指碎成很多小块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物变大，灯泡不会生长。"}, {"text": "破碎", "is_correct": true, "explanation": "正确。指灯泡碎裂，与“孩子不小心”的语境相符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”的主语需有情感，灯泡不会哭。"}, {"text": "挑", "is_correct": false, "explanation": "配价：“挑”需要带宾语，“让灯泡挑了”不成立。"}], "explanations": {"生长": "语义：“生长”指生物变大，灯泡不会生长。", "破碎": "正确。指灯泡碎裂，与“孩子不小心”的语境相符。", "哭": "语义：“哭”的主语需有情感，灯泡不会哭。", "挑": "配价：“挑”需要带宾语，“让灯泡挑了”不成立。"}, "sentence_index": 6, "correct_answer": "破碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件旧衣服穿了二十年，已经破碎了。", "explanation": "这里应该用〈破旧〉。破碎指东西裂成小块；衣服只是陈旧磨损，应说“破旧”。"}, {"text": "大风一吹，这根树枝破碎了。", "explanation": "这里应该用〈折断〉。树枝断成两截应说“折断”，破碎指碎成很多小块。"}, {"text": "他的信封封口破碎了，信件却完好无损。", "explanation": "这里应该用〈撕破〉。信封被撕开一个口子，不是碎成小块，应说“撕破”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一块饼干从桌子上掉下来，被破碎了。", "corrected_sentence": "一块饼干从桌子上掉下来，破碎了。", "error_description": "被动错误：“破碎”是不及物动词，不能用“被”字句。应说“饼干从桌子上掉下来，破碎了”，去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "灯泡从桌上掉下来，把它破碎了。", "corrected_sentence": "灯泡从桌上掉下来，破碎了。", "error_description": "把字句错误：“破碎”是不及物动词，不能带“把”字宾语。应说“灯泡从桌上掉下来，破碎了”，去掉“把它”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aef10fd1-001a-48cb-897b-ee721349d09a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
