INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有执法权的机关或人员依照法律规定处理事情。", "primary_collocate": null, "pronunciation": "zhí fǎ", "ipa": "ʈʂɻ̩˧˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察在街上执法，大家都要听。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们依法执法，不会看人情。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察执法时要穿制服。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交警在路口执法，检查酒后开车。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察执法要公平，不能帮朋友。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是警察，每天在外面执法。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察执法时必须依法办事，不能随意处罚人。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开车太快，警察来执法了。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察执法很认真，没有人敢吵闹。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，警察必须公平地执法。", "target_word": "执法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "执法者", "label": "复合"}, {"form": "依法执法", "label": "搭配"}, {"form": "严格执法", "label": "搭配"}], "register": "正式", "sense_fingerprint": "警察等按法律规定处理事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27792, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "执法", "is_correct": true, "explanation": "正确答案。执法读 zhí fǎ，指有关部门依法处理事情。"}, {"text": "指法", "is_correct": false, "explanation": "zhǐ fǎ 第一个音节声调与 zhí 不同（第三声），意思是手指的操作方法。"}, {"text": "知法", "is_correct": false, "explanation": "zhī fǎ 第一个音节声调与 zhí 不同（第一声），意思是懂得法律。"}, {"text": "直发", "is_correct": false, "explanation": "zhí fà 第二个音节声调与 fǎ 不同（第四声），意思是直的头发。"}], "explanations": {"执法": "正确答案。执法读 zhí fǎ，指有关部门依法处理事情。", "指法": "zhǐ fǎ 第一个音节声调与 zhí 不同（第三声），意思是手指的操作方法。", "知法": "zhī fǎ 第一个音节声调与 zhí 不同（第一声），意思是懂得法律。", "直发": "zhí fà 第二个音节声调与 fǎ 不同（第四声），意思是直的头发。"}, "sentence_index": null, "correct_answer": "执法"}, "level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“大家都要听”的语境不符，警察在街上睡觉不会让人听从。"}, {"text": "执法", "is_correct": true, "explanation": "正确。“警察在街上执法”表示依法处理，“大家都要听”与之呼应。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”必须带宾语，“警察在街上喜欢”的说法不成立。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“大家都要听”不相干，句意不通。"}], "explanations": {"睡觉": "语义：“睡觉”与“大家都要听”的语境不符，警察在街上睡觉不会让人听从。", "执法": "正确。“警察在街上执法”表示依法处理，“大家都要听”与之呼应。", "喜欢": "配价：“喜欢”必须带宾语，“警察在街上喜欢”的说法不成立。", "吃饭": "语义：“吃饭”与“大家都要听”不相干，句意不通。"}, "sentence_index": 0, "correct_answer": "执法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直执法，从来不闯红灯。", "explanation": "这里应该用〈守法〉。守法指遵守法律，“执法”指有执法权的机关或人员依法处理违法行为，普通人不能说执法。"}, {"text": "学生在教室执法。", "explanation": "这里应该用〈上课〉。上课指学习或授课，“执法”指依法处理违法行为，学生在教室里的活动不能说执法。"}, {"text": "医生在病房执法。", "explanation": "这里应该用〈检查〉。医生在病房做的是诊查，“执法”指依法处理违法行为，不能用来描述医生的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27792, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "执法", "is_correct": true, "explanation": "正确答案。执法读 zhí fǎ，指有关部门依法处理事情。"}, {"text": "织法", "is_correct": false, "explanation": "zhī fǎ 第一个音节声调与 zhí 不同（第一声），意思是编织方法。"}, {"text": "治法", "is_correct": false, "explanation": "zhì fǎ 第一个音节声调与 zhí 不同（第四声），意思是治疗方法。"}, {"text": "指法", "is_correct": false, "explanation": "zhǐ fǎ 第一个音节声调与 zhí 不同（第三声），意思是手指的操作方法。"}], "explanations": {"执法": "正确答案。执法读 zhí fǎ，指有关部门依法处理事情。", "织法": "zhī fǎ 第一个音节声调与 zhí 不同（第一声），意思是编织方法。", "治法": "zhì fǎ 第一个音节声调与 zhí 不同（第四声），意思是治疗方法。", "指法": "zhǐ fǎ 第一个音节声调与 zhí 不同（第三声），意思是手指的操作方法。"}, "sentence_index": null, "correct_answer": "执法"}, "level_3": {"options": [{"text": "大笑", "is_correct": false, "explanation": "语义：“大笑”与“依法办事、不能随意处罚”的语境不符。"}, {"text": "大喊", "is_correct": false, "explanation": "语义：“大喊”不是依法办事的行为，与语境不符。"}, {"text": "执法", "is_correct": true, "explanation": "正确。“警察执法时必须依法办事”与语境相合。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”必须带宾语，“警察认识时”的说法不成立。"}], "explanations": {"大笑": "语义：“大笑”与“依法办事、不能随意处罚”的语境不符。", "大喊": "语义：“大喊”不是依法办事的行为，与语境不符。", "执法": "正确。“警察执法时必须依法办事”与语境相合。", "认识": "配价：“认识”必须带宾语，“警察认识时”的说法不成立。"}, "sentence_index": 6, "correct_answer": "执法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "顾客正在执法。", "explanation": "这里应该用〈投诉〉。投诉是向有关部门反映问题，“执法”只用于有执法权的机关或人员，顾客不能执法。"}, {"text": "老师在办公室执法。", "explanation": "这里应该用〈批改〉。批改是改正作业，“执法”指依法处理违法行为，老师批改作业不能说执法。"}, {"text": "售货员在柜台执法。", "explanation": "这里应该用〈卖〉。卖是出售商品，“执法”指依法处理违法行为，售货员卖东西不能说执法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海关人员从机场执法，检查旅客的行李。", "corrected_sentence": "海关人员在机场执法，检查旅客的行李。", "error_description": "介词误用：「从机场执法」错误。“从”表示起点，表示执法的地点要用“在”，正确为「在机场执法」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "交警正在路口依法执法了，维持秩序。", "corrected_sentence": "交警正在路口依法执法，维持秩序。", "error_description": "多了“了”：“正在”表示动作进行中，句末不能再加“了”，应说「正在依法执法」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
