INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27798, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "土地变得不好，不能种出很多庄稼了。", "primary_collocate": null, "pronunciation": "tǔ rǎng tuì huà", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦ tʰweɪ˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "土壤退化了，地里长不出好庄稼。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民很担心土壤退化。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "土壤退化以后，粮食越来越少。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的土壤退化得很快。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤退化是一个大问题。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我们讲了土壤退化的原因。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多种树能帮助减少土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的土壤退化，大家只好搬家。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用太多化肥会带来土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的土壤退化比平原更严重。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤退化问题", "label": "复合"}], "register": "中性", "sense_fingerprint": "土壤退化|土地变差，种不出很多庄稼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27798, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：“土壤退化了”作主语，说明土地变差，导致地里长不出好庄稼。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是土地，“教室了，地里长不出好庄稼”无法成立。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆与庄稼和土地无关，不能作为土地变差的主语。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，与土地和庄稼无关，“电视了，地里长不出好庄稼”不成立。"}], "explanations": {"土壤退化": "正确：“土壤退化了”作主语，说明土地变差，导致地里长不出好庄稼。", "教室": "语义：教室不是土地，“教室了，地里长不出好庄稼”无法成立。", "图书馆": "语义：图书馆与庄稼和土地无关，不能作为土地变差的主语。", "电视": "语义：电视是电器，与土地和庄稼无关，“电视了，地里长不出好庄稼”不成立。"}, "sentence_index": 0, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地经过多年的土壤退化，庄稼长得特别好。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”指土地变差、庄稼难长，不能说长得特别好。"}, {"text": "这块地土壤退化了，庄稼比去年长得更好了。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”指土地变差，庄稼应该长得更差，不会更好。"}, {"text": "这条河的土壤退化很严重，鱼都死光了。", "explanation": "这里应该用〈水污染〉。河水受污染是水的问题，“土壤退化”只说土地质量变差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27798, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：减少土壤退化是种树的目的，与“多种树能帮助减少”的语境相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是可以被“减少”的对象，“多种树能帮助减少钢琴”不成立。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌与种树没有因果关系，“减少诗歌”不成立。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是故事，与种树无关，“多种树能帮助减少童话”不成立。"}], "explanations": {"土壤退化": "正确：减少土壤退化是种树的目的，与“多种树能帮助减少”的语境相符。", "钢琴": "语义：钢琴不是可以被“减少”的对象，“多种树能帮助减少钢琴”不成立。", "诗歌": "语义：诗歌与种树没有因果关系，“减少诗歌”不成立。", "童话": "语义：童话是故事，与种树无关，“多种树能帮助减少童话”不成立。"}, "sentence_index": 6, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们很高兴，因为村里的地发生了土壤退化。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”是坏事，土地变差不会让人高兴。"}, {"text": "这块地的土壤退化很好，庄稼长得很壮。", "explanation": "这里应该用〈土壤肥力〉。“土壤退化”指土壤变差，不能用“很好”来说它的好坏；说土壤好应用〈土壤肥力〉。"}, {"text": "为了让庄稼丰收，他们在地里施了很多土壤退化。", "explanation": "这里应该用〈化肥〉。“施”的对象是肥料，土壤退化是一种变差的过程，不能被施用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27798, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都很关心土壤退化地问题。", "corrected_sentence": "大家都很关心土壤退化的问题。", "error_description": "助词错误：“土壤退化”修饰名词“问题”，中间应该用“的”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27798, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的土壤退化比那里很快。", "corrected_sentence": "这里的土壤退化比那里更快。", "error_description": "比较句错误：“比”字句中形容词前不能用“很”，应说“更快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
