INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27802, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为了做好一件事，提前想好的办法。", "primary_collocate": null, "pronunciation": "fāng àn", "ipa": "fɑŋ˥ ɑn˥˩", "syllable_count": 2, "sentences": [{"text": "我们需要一个新的方案。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理看了我的方案，觉得很好。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个方案太贵了，我们不能用。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出了三个解决问题的方案。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让大家说说旅行方案。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的方案比我的更简单。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司明天要讨论这个方案。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把你的方案写在纸上。", "target_word": "方案", "complexity_tier": "T3", "furigana": "fāng àn", "sentence_source": "generated"}, {"text": "为了省钱，我们改了装修方案。", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个方案各有好处，我们选哪个呢？", "target_word": "方案", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：事先想好的做事办法和安排（旅行方案）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27802, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是唯一的，说“需要一个新的太阳”与句意不合。"}, {"text": "方案", "is_correct": true, "explanation": "方案：为做事而事先想好的办法，与“我们需要一个新的”相符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不说“一个空气”。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日子，不是可以“需要”的新事物，句意不合。"}], "explanations": {"太阳": "语义：太阳是唯一的，说“需要一个新的太阳”与句意不合。", "方案": "方案：为做事而事先想好的办法，与“我们需要一个新的”相符。", "空气": "搭配：“空气”是不可数名词，不说“一个空气”。", "生日": "语义：“生日”是日子，不是可以“需要”的新事物，句意不合。"}, "sentence_index": 0, "correct_answer": "方案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会用说话的方案。", "explanation": "这里应该用〈技巧〉。方案指事先想好的做事安排，说话的技巧不能说方案。"}, {"text": "昨天晚上我看了一部很好看的方案。", "explanation": "这里应该用〈电影〉。方案指事先想好的做事办法，不能“看一部”来娱乐。"}, {"text": "这幅画的方案很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，方案不能用来形容鲜艳的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27802, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身材", "is_correct": false, "explanation": "体貌：“身材”形容人的体型，不能拿来作为公司会议讨论的内容。"}, {"text": "方案", "is_correct": true, "explanation": "方案：为做好某事而提出的具体安排，与“公司明天要讨论”相符。"}, {"text": "鼻子", "is_correct": false, "explanation": "语义：“鼻子”是身体器官，不是公司会议要讨论的事项。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”描写人的脸，不能作为会议讨论的内容。"}], "explanations": {"身材": "体貌：“身材”形容人的体型，不能拿来作为公司会议讨论的内容。", "方案": "方案：为做好某事而提出的具体安排，与“公司明天要讨论”相符。", "鼻子": "语义：“鼻子”是身体器官，不是公司会议要讨论的事项。", "面容": "体貌：“面容”描写人的脸，不能作为会议讨论的内容。"}, "sentence_index": 6, "correct_answer": "方案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把方案很好用。", "explanation": "这里应该用〈工具〉。方案指事先想好的办法，不指实际的用具。"}, {"text": "这道菜的方案很辣。", "explanation": "这里应该用〈味道〉。“辣”形容滋味，方案不指口味，表示菜的滋味要用“味道”。"}, {"text": "他的方案很强壮。", "explanation": "这里应该用〈身体〉。“强壮”形容人或动物的体格，方案不能用“强壮”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27802, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要一把新的方案。", "corrected_sentence": "我们需要一份新的方案。", "error_description": "量词错误：“方案”应用量词“份”，不能用“把”（“把”用于有柄的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27802, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个方案们各有优缺点，你觉得哪个好？", "corrected_sentence": "这两个方案各有优缺点，你觉得哪个好？", "error_description": "加“们”错误：“方案”不指人，不能加“们”，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
