INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（政策、规定、措施等）由政府或有关部门正式公布、开始实行。", "primary_collocate": null, "pronunciation": "chū tái", "ipa": "ʈʂʰu˥ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "政府出台了新的环保规定。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里将出台一项新政策。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法是去年出台的。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护孩子，学校出台了新规定。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台政策，帮助小公司发展。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定还没有出台，大家都在等。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府刚出台了一个租房办法。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关部门出台了很多措施来减少污染。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法规什么时候出台？", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们市出台了新的交通规定。", "target_word": "出台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出台了", "label": "完成体"}, {"form": "出台过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "政府或部门正式公布新政策、新规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e373b1f0-8529-4f99-bdb4-29789ab94d68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出台", "is_correct": true, "explanation": "正确。出台指政府或部门正式公布新规定，“政府出台了新的环保规定”符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，不能用来说规定，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗指清洗东西，不能用于规定。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：唱多用于歌曲、戏曲，不说“唱规定”。"}], "explanations": {"出台": "正确。出台指政府或部门正式公布新规定，“政府出台了新的环保规定”符合语境。", "吃": "语义：吃指进食，不能用来说规定，句子不通。", "洗": "语义：洗指清洗东西，不能用于规定。", "唱": "搭配：唱多用于歌曲、戏曲，不说“唱规定”。"}, "sentence_index": 0, "correct_answer": "出台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司出台了一款新游戏。", "explanation": "这里应该用〈推出〉。出台用于政策、规定、办法，产品要用推出。"}, {"text": "他出台了一个新的建议。", "explanation": "这里应该用〈提出〉。出台指正式公布政策或规定，提建议要用提出。"}, {"text": "爱迪生出台了电灯。", "explanation": "这里应该用〈发明〉。出台用于政策、规定，做出新的东西要用发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出台", "is_correct": true, "explanation": "正确。出台指政府正式公布新办法，“刚出台了一个租房办法”符合语境。"}, {"text": "骑", "is_correct": false, "explanation": "语义：骑指坐在车上行进，不能用来说办法。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：煮用于做饭菜，不说“煮办法”。"}, {"text": "种", "is_correct": false, "explanation": "语义：种指种植，办法不能被种。"}], "explanations": {"出台": "正确。出台指政府正式公布新办法，“刚出台了一个租房办法”符合语境。", "骑": "语义：骑指坐在车上行进，不能用来说办法。", "煮": "搭配：煮用于做饭菜，不说“煮办法”。", "种": "语义：种指种植，办法不能被种。"}, "sentence_index": 6, "correct_answer": "出台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家出版社出台了一本新书。", "explanation": "这里应该用〈出版〉。出台用于政策、规定、办法，书籍要用出版。"}, {"text": "这家商店出台了新鲜的蔬菜。", "explanation": "这里应该用〈出售〉。出台用于政策、规定，买卖商品要用出售。"}, {"text": "这位歌手明天要出台一张新专辑。", "explanation": "这里应该用〈发行〉。出台用于政策、规定、办法，唱片、专辑要用发行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府出台着一项新的垃圾分类办法。", "corrected_sentence": "市政府出台了一项新的垃圾分类办法。", "error_description": "体标：表示已完成的公布要用“了”，用“着”表示持续状态，“出台着”是错的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府明天出台了一项新办法。", "corrected_sentence": "政府明天出台一项新办法。", "error_description": "体标：“明天”指将来，不能与完成体“了”搭配，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '412ca064-7475-415c-bc02-5d332d6f9ddb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
