INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把旧的东西变得更好用。", "primary_collocate": null, "pronunciation": "jì shù gé xīn", "ipa": "tɕi˥˩ ʂu˥˩ kɤ˧˥ ɕin˥", "syllable_count": 4, "sentences": [{"text": "工人们一起搞技术革新，把旧机器修得更好用。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢搞技术革新，旧工具到他手里都变好用了。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组的技术革新让老设备又能用了。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的一项技术革新，让旧水泵省了不少电。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧机器经过技术革新，又省电又好用。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不买新的，而是自己搞技术革新。", "target_word": "技术革新", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂对旧机床进行了技术革新，现在更方便了。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项技术革新很简单，却让老工具好用多了。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅做了技术革新，旧收音机又能响了。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的技术革新，让旧自行车骑起来更轻松。", "target_word": "技术革新", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "技術革新", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动手改造旧机器、旧工具，使它们更好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '09b47580-90f5-4a9a-ab97-6f640ec498d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27818, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口号", "is_correct": false, "explanation": "语义：口号不能动手修理机器，句中“把旧机器修得更好用”说明动作是改造机器"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“搞”后面不能接“天气”"}, {"text": "技术革新", "is_correct": true, "explanation": "“技术革新”指动手改造旧机器、旧工具，与“修得更好用”相符"}, {"text": "八卦", "is_correct": false, "explanation": "语义：八卦是闲话，与改造机器使其更好用无关"}], "explanations": {"口号": "语义：口号不能动手修理机器，句中“把旧机器修得更好用”说明动作是改造机器", "天气": "搭配：“搞”后面不能接“天气”", "技术革新": "“技术革新”指动手改造旧机器、旧工具，与“修得更好用”相符", "八卦": "语义：八卦是闲话，与改造机器使其更好用无关"}, "sentence_index": 0, "correct_answer": "技术革新"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次技术革新把整栋楼的墙都刷成了新的。", "explanation": "这里应该用〈装修〉。技术革新指改造旧机器、旧工具，刷墙、装潢要用〈装修〉"}, {"text": "这个大厅的技术革新很精美。", "explanation": "这里应该用〈装饰〉。技术革新指改进机器或工具使其更好用，大厅的美观要用〈装饰〉"}, {"text": "老师傅完成了一幅技术革新。", "explanation": "量词错误：技术革新应搭配〈项〉，〈幅〉多用于画作。这里应该用〈项〉"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27818, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲座", "is_correct": false, "explanation": "语义：讲座是讲授活动，不能改造旧机床，句子语义不通"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛与改造旧机床无关，句子语义不通"}, {"text": "技术革新", "is_correct": true, "explanation": "“技术革新”指改造旧设施使其更好用，与“更方便了”相符"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“进行”不能接“故事”，应说“讲故事”"}], "explanations": {"讲座": "语义：讲座是讲授活动，不能改造旧机床，句子语义不通", "比赛": "语义：比赛与改造旧机床无关，句子语义不通", "技术革新": "“技术革新”指改造旧设施使其更好用，与“更方便了”相符", "故事": "搭配：“进行”不能接“故事”，应说“讲故事”"}, "sentence_index": 6, "correct_answer": "技术革新"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师傅是一位很好的技术革新。", "explanation": "这里把技术革新当作人来用，指人应说〈能工巧匠〉；技术革新指让旧东西变好用的改进活动"}, {"text": "他用技术革新的办法教孩子写字。", "explanation": "这里误把技术革新当作一般的办法来用。教孩子写字应说〈教学〉；技术革新只指让旧东西变好用的改进"}, {"text": "她把这次技术革新送给了朋友做礼物。", "explanation": "这里把抽象的技术革新当作礼物来用。送人的礼物应是〈纪念品〉；技术革新只指让旧东西变好用的改进"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厂里一位老师傅做了一块技术革新，旧水泵又能转了。", "corrected_sentence": "厂里一位老师傅做了一项技术革新，旧水泵又能转了。", "error_description": "量词错误：“技术革新”应搭配量词“项”，“块”用于块状的东西，不能说“一块技术革新”，应说“一项技术革新”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间对旧工具技术革新，干活更省力了。", "corrected_sentence": "车间对旧工具进行技术革新，干活更省力了。", "error_description": "搭配结构错误：“对……”之后要接动词，应说“进行技术革新”，不能直接说“技术革新”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8282a897-9d06-4ca8-a6bc-97a88d746f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
