INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "快要消失了，就像快没了的动物或植物。", "primary_collocate": null, "pronunciation": "bīn wēi", "ipa": "pin˥˥ wei˥˥", "syllable_count": 2, "sentences": [{"text": "这种鱼很少了，已经濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "濒危动物需要我们的保护。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看过濒危的金丝猴。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花越来越少，现在很濒危。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了濒危植物的故事。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上有很多濒危的动物。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树林变小了，小鸟也濒危了。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护濒危物种，他去了山里。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种濒危的小鸟住在山上。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一张濒危动物的画。", "target_word": "濒危", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濒危物种", "label": "复合"}, {"form": "濒危植物", "label": "复合"}], "register": "书面", "sense_fingerprint": "动植物快要消失", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危作谓语，指快要消失，与“很少了”的语境相符。"}, {"text": "充足", "is_correct": false, "explanation": "语义：“充足”指数量多，与“很少了”的语境矛盾。"}, {"text": "繁多", "is_correct": false, "explanation": "语义：“繁多”指数量多，与“很少了”的语境矛盾。"}, {"text": "旺盛", "is_correct": false, "explanation": "搭配：“旺盛”多形容生命力或势头，不用来描述鱼的数量状况。"}], "explanations": {"濒危": "濒危作谓语，指快要消失，与“很少了”的语境相符。", "充足": "语义：“充足”指数量多，与“很少了”的语境矛盾。", "繁多": "语义：“繁多”指数量多，与“很少了”的语境矛盾。", "旺盛": "搭配：“旺盛”多形容生命力或势头，不用来描述鱼的数量状况。"}, "sentence_index": 0, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的队员很濒危，个个都精神饱满。", "explanation": "这里应该用〈健壮〉。队员精神饱满，与“快要消失”相矛盾，应说“健壮”。"}, {"text": "这份工作的压力很濒危。", "explanation": "这里应该用〈沉重〉。濒危指快要消失的动植物或事物，压力不会“消失”，形容压力大应说“沉重”。"}, {"text": "这座城市的人口很濒危，走路都挤。", "explanation": "这里应该用〈密集〉。濒危指快要消失的动植物或事物，人口多不是快要消失，不能说“濒危”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濒危", "is_correct": true, "explanation": "濒危作谓语，指快要消失，与“树林变小了”的语境相符。"}, {"text": "富足", "is_correct": false, "explanation": "语义：“富足”指物质充裕，不用来描述小鸟的状况，句意不通。"}, {"text": "繁荣", "is_correct": false, "explanation": "语义：“树林变小了，小鸟也……”中的“也”表示同样的遭遇，“繁荣”与之矛盾，句意不通。"}, {"text": "欢乐", "is_correct": false, "explanation": "语义：“欢乐”指愉快，与“树林变小了”的语境矛盾。"}], "explanations": {"濒危": "濒危作谓语，指快要消失，与“树林变小了”的语境相符。", "富足": "语义：“富足”指物质充裕，不用来描述小鸟的状况，句意不通。", "繁荣": "语义：“树林变小了，小鸟也……”中的“也”表示同样的遭遇，“繁荣”与之矛盾，句意不通。", "欢乐": "语义：“欢乐”指愉快，与“树林变小了”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "濒危"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们画了一个濒危的太阳，天空很亮。", "explanation": "这里应该用〈灿烂〉。太阳快要消失，与“天空很亮”相矛盾，形容太阳明亮应说“灿烂”。"}, {"text": "他的心情很濒危。", "explanation": "这里应该用〈低落〉。濒危指面临灭绝或消亡，不能用来形容心情。"}, {"text": "这所学校的学生很濒危，每年都招满了新生。", "explanation": "这里应该用〈众多〉。招满新生说明人数多，与“快要消失”相矛盾，应说“众多”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种树已经濒危着。", "corrected_sentence": "这种树已经濒危了。", "error_description": "错误形式：“濒危着”；正确形式：“濒危了”。“濒危”是形容词，表示快要消失的状态，不能带动态助词“着”，应把“着”改为表示变化的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种鸟被濒危了。", "corrected_sentence": "这种鸟已经濒危了。", "error_description": "错误形式：“被濒危”；正确形式：“已经濒危”。“濒危”是形容词，不能与“被”构成被动式，应把“被”改为“已经”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
