INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示某人不拥有某物，或不具有某种东西。", "primary_collocate": null, "pronunciation": "méi yǒu", "ipa": "mei˧˥ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我没有玩具。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他没有手机。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟没有姐姐。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天没有时间。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个教室没有空调。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有钱买新车。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有铅笔，你有吗？", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家没有小狗。", "target_word": "没有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在这里没有朋友。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们没有票，不能进去。", "target_word": "没有", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "沒有", "label": "繁体"}, {"form": "没", "label": "省略形式"}, {"form": "有没有", "label": "正反问"}], "register": "口语", "sense_fingerprint": "没有：某人不拥有某物，或不具有某种东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfff504e-4568-4828-bef5-09ba6f7af341') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有”表示不拥有，与句意一致。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃玩具。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只接衣物，不能说穿玩具。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮品，不能说喝玩具。"}], "explanations": {"没有": "正确：“没有”表示不拥有，与句意一致。", "吃": "语义：“吃”的对象是食物，不能说吃玩具。", "穿": "搭配：“穿”只接衣物，不能说穿玩具。", "喝": "语义：“喝”的对象是饮品，不能说喝玩具。"}, "sentence_index": 0, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没有我高，但他跑得比我快。", "explanation": "这里的“没有”表示“不如”，用于比较，是另一个意思，不表示不拥有。"}, {"text": "我昨天没有去学校，因为生病了。", "explanation": "这里的“没有”表示动作未发生，用于过去，是另一个意思，不表示不拥有。"}, {"text": "电影还没有开始，我们再等一会儿。", "explanation": "这里的“没有”表示“尚未”，是另一个意思，不表示不拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有", "is_correct": true, "explanation": "正确：“没有”与后句“你有吗”相对，表示不拥有。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”只接帽子、眼镜等，不能说戴铅笔。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能说煮铅笔。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”接歌曲，不能说唱铅笔。"}], "explanations": {"没有": "正确：“没有”与后句“你有吗”相对，表示不拥有。", "戴": "搭配：“戴”只接帽子、眼镜等，不能说戴铅笔。", "煮": "语义：“煮”的对象是食物，不能说煮铅笔。", "唱": "搭配：“唱”接歌曲，不能说唱铅笔。"}, "sentence_index": 6, "correct_answer": "没有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服没有那么贵，我们可以买。", "explanation": "这里的“没有”表示“不太”，用于程度比较，是另一个意思，不表示不拥有。"}, {"text": "我一次都没有迟到过，老师表扬了我。", "explanation": "这里的“没有”表示“从未”，是另一个意思，不表示不拥有。"}, {"text": "我们没有必要着急，慢慢走吧。", "explanation": "这里的“没有必要”表示“不必”，是另一个意思，不表示不拥有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家里不没有电脑。", "corrected_sentence": "我家里没有电脑。", "error_description": "错误：“不没有”。正确：“没有”。表示领有的否定只用“没有”或“没”，前面不能再加“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他家里没有有车。", "corrected_sentence": "他家里没有车。", "error_description": "错误：“没有有车”。正确：“没有车”。“没有”是一个整体，后面直接接宾语，不能重复“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea03c2e4-f2a3-4b86-8f27-bea25ba4156f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
