INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27828, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "丰度是表示某种东西在另一种东西里有多少的说法。", "primary_collocate": null, "pronunciation": "fēng dù", "ipa": "fəŋ˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "这条河里鱼的丰度很高。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这片森林里，鸟的丰度在下降。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土壤里细菌的丰度影响植物生长。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖水中小虫的丰度比去年低。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片草地上蝴蝶的丰度很高。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海里鱼的丰度下降了，渔民很担心。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家统计了公园里昆虫的丰度。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山上的树种丰度比山下高得多。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后池塘里青蛙的丰度明显上升了。", "target_word": "丰度", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区老鼠的丰度很高，需要多加注意。", "target_word": "丰度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "豐度", "label": "繁体"}], "register": "书面", "sense_fingerprint": "某种东西在另一种东西里的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18462fa8-6019-40c1-b9b3-2f552a608b56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度（fēng dù）即本词，指某种东西在另一种东西里有多少。"}, {"text": "封堵", "is_correct": false, "explanation": "dǔ（第三声）与 dù（第四声）声调不同，意思是堵住、封住。"}, {"text": "分度", "is_correct": false, "explanation": "fēn 与 fēng 韵尾不同（n 与 ng），意思是把刻度分成若干等份。"}, {"text": "蜂毒", "is_correct": false, "explanation": "dú（第二声）与 dù（第四声）声调不同，意思是蜜蜂的毒液。"}, {"text": "风速", "is_correct": false, "explanation": "sù 与 dù 声母不同（s 与 d），意思是风的快慢。"}], "explanations": {"丰度": "丰度（fēng dù）即本词，指某种东西在另一种东西里有多少。", "封堵": "dǔ（第三声）与 dù（第四声）声调不同，意思是堵住、封住。", "分度": "fēn 与 fēng 韵尾不同（n 与 ng），意思是把刻度分成若干等份。", "蜂毒": "dú（第二声）与 dù（第四声）声调不同，意思是蜜蜂的毒液。", "风速": "sù 与 dù 声母不同（s 与 d），意思是风的快慢。"}, "sentence_index": null, "correct_answer": "丰度"}, "level_3": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度指鱼在河里的多少，与“很高”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：鱼的颜色不说高低，句子说的是鱼的多少。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状不说高低，句子说的是鱼的多少。"}, {"text": "块头", "is_correct": false, "explanation": "体貌：“块头”指个体的体型大小，不能用来说整条河里鱼的多少。"}], "explanations": {"丰度": "丰度指鱼在河里的多少，与“很高”搭配，符合句意。", "颜色": "语义：鱼的颜色不说高低，句子说的是鱼的多少。", "形状": "语义：形状不说高低，句子说的是鱼的多少。", "块头": "体貌：“块头”指个体的体型大小，不能用来说整条河里鱼的多少。"}, "sentence_index": 0, "correct_answer": "丰度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位射手的丰度很高。", "explanation": "这里应该用〈命中率〉。丰度说的是某种东西在另一种东西里的多少，不用于射击的成功比例。"}, {"text": "这场演出的丰度很高。", "explanation": "这里应该用〈上座率〉。丰度不用来说座位被占的比例。"}, {"text": "这座湖里的一只丰度很高。", "explanation": "量词用错。“只”用于动物等具体事物，丰度是抽象概念，不能用“一只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27828, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度（fēng dù）即本词，指某种东西在另一种东西里有多少。"}, {"text": "风露", "is_correct": false, "explanation": "lù（第四声）与 dù 只差声母（l 与 d），意思是风和露水。"}, {"text": "风趣", "is_correct": false, "explanation": "qù 与 dù 只差声母（q 与 d），意思是幽默、有意思。"}, {"text": "丰都", "is_correct": false, "explanation": "dū（第一声）与 dù（第四声）声调不同，是重庆的一个地名。"}], "explanations": {"丰度": "丰度（fēng dù）即本词，指某种东西在另一种东西里有多少。", "风露": "lù（第四声）与 dù 只差声母（l 与 d），意思是风和露水。", "风趣": "qù 与 dù 只差声母（q 与 d），意思是幽默、有意思。", "丰都": "dū（第一声）与 dù（第四声）声调不同，是重庆的一个地名。"}, "sentence_index": null, "correct_answer": "丰度"}, "level_3": {"options": [{"text": "丰度", "is_correct": true, "explanation": "丰度指昆虫在公园里的多少，与“统计”搭配，符合句意。"}, {"text": "人数", "is_correct": false, "explanation": "语义：“人数”只用于人，昆虫不能数人数。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”一般指人的体形，不用于统计昆虫的数量。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指买卖的钱数，昆虫没有价格，不能用来统计。"}], "explanations": {"丰度": "丰度指昆虫在公园里的多少，与“统计”搭配，符合句意。", "人数": "语义：“人数”只用于人，昆虫不能数人数。", "身材": "体貌：“身材”一般指人的体形，不用于统计昆虫的数量。", "价格": "语义：「价格」指买卖的钱数，昆虫没有价格，不能用来统计。"}, "sentence_index": 6, "correct_answer": "丰度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的丰度很多。", "explanation": "这里应该用〈人口〉。丰度说的是某种东西在另一种东西里的多少，不用来说城市的人口数。"}, {"text": "这件衣服的丰度很高。", "explanation": "这里应该用〈价格〉。丰度不用于衡量物品的价钱。"}, {"text": "这个地区的一把丰度很高。", "explanation": "量词用错。“把”用于有柄的器具等，丰度是抽象概念，不能用“一把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火星大气中氩的丰度了很低。", "corrected_sentence": "火星大气中氩的丰度很低。", "error_description": "错误：「了」放错位置。「丰度很低」中不能在「丰度」后加「了」，应删去，写作「火星大气中氩的丰度很低」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "海里某种藻类的一只丰度很高。", "corrected_sentence": "海里某种藻类的丰度很高。", "error_description": "量词用错：“丰度”是抽象名词，不能用“只”（“只”用于动物等具体事物）。应去掉“一只”，写作“海里某种藻类的丰度很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
