INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27832, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可以检查是不是真的。", "primary_collocate": null, "pronunciation": "kě yàn zhèng", "ipa": "kʰɤ˨˩˦ jɛn˥˩ ʈʂəŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这条新闻的来源是可验证的。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者只写可验证的消息。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的年龄是可验证的。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事可验证，你可以去问他。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请提供一个可验证的联系地址。", "target_word": "可验证", "complexity_tier": "T3", "furigana": "qǐng tí gōng yí gè kě yàn zhèng de lián xì dì zhǐ", "sentence_source": "generated"}, {"text": "警察需要可验证的证据。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的时间可验证吗？", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的数字都可验证。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西时要看可验证的评价。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他留下的电话号码是可验证的。", "target_word": "可验证", "complexity_tier": "T3", "furigana": "tā liú xià de diàn huà hào mǎ shì kě yàn zhèng de", "sentence_source": "generated"}], "morphological_forms": [{"form": "可驗證", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可验证：可以检查是不是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可验证", "is_correct": true, "explanation": "正确。「这条新闻的来源是可验证的」说来源能被检查，符合语境。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」形容场面喧闹，不能说新闻的来源热闹。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容身材或体积，不能用来形容来源。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：「好吃」指食物的味道，新闻的来源不能好吃。"}], "explanations": {"可验证": "正确。「这条新闻的来源是可验证的」说来源能被检查，符合语境。", "热闹": "语义：「热闹」形容场面喧闹，不能说新闻的来源热闹。", "高大": "体貌：「高大」形容身材或体积，不能用来形容来源。", "好吃": "语义：「好吃」指食物的味道，新闻的来源不能好吃。"}, "sentence_index": 0, "correct_answer": "可验证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶很可验证。", "explanation": "这里应该用〈慈祥〉。可验证指能检查真假，不能形容人的性格。"}, {"text": "鸟叫声很可验证。", "explanation": "这里应该用〈清脆〉。可验证说的是能否核实，不用来形容声音的好听程度。"}, {"text": "这间房子很可验证。", "explanation": "这里应该用〈宽敞〉。可验证只指能否检查真假，不用来说房间的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可验证", "is_correct": true, "explanation": "正确。「这张照片的时间可验证吗」问时间能否被核实，符合语境。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：「胖」形容人或动物的身材，不能用来形容时间。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」多用于外貌或景色，不能说时间漂亮。"}, {"text": "寂寞", "is_correct": false, "explanation": "语义：「寂寞」指人的情感，时间不能是寂寞的，与照片的核实无关。"}], "explanations": {"可验证": "正确。「这张照片的时间可验证吗」问时间能否被核实，符合语境。", "胖": "体貌：「胖」形容人或动物的身材，不能用来形容时间。", "漂亮": "搭配：「漂亮」多用于外貌或景色，不能说时间漂亮。", "寂寞": "语义：「寂寞」指人的情感，时间不能是寂寞的，与照片的核实无关。"}, "sentence_index": 6, "correct_answer": "可验证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师很可验证。", "explanation": "这里应该用〈亲切〉。可验证指能否确认真假，不用来形容老师的态度。"}, {"text": "他的声音很可验证。", "explanation": "这里应该用〈响亮〉。可验证只说能否核实，不用来形容声音的大小。"}, {"text": "这张桌子很可验证。", "explanation": "这里应该用〈结实〉。可验证指能否检查真假，不用来说家具的牢固程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提供的资料是可验证地。", "corrected_sentence": "他提供的资料是可验证的。", "error_description": "「可验证」是形容词，作谓语后应接「的」，不能用「地」；「地」用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的住址是可验证。", "corrected_sentence": "他的住址是可验证的。", "error_description": "「可验证」作「是」的谓语时要带「的」，应说「是可验证的」，去掉「的」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
