INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责照顾或管理，不让东西乱跑或变坏。", "primary_collocate": null, "pronunciation": "guǎn hǎo", "ipa": "kwan˨˩˦ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小狗在公园里，主人要管好它。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车时请管好你的包，别让小偷拿走。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把牛管好，别让它们跑到别人的地里。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，我要管好自己的玩具，别弄坏了。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没管好那只鸟，鸟飞走了。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷管好了家里的鸡，一只也没丢。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很热，要管好冰箱里的菜，不然会变坏。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家的猫总爬到邻居家，请管好它。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我帮爷爷管好院子里的鸭子。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的书包，你要管好，别让他弄丢。", "target_word": "管好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管好了", "label": "体标"}, {"form": "管不好", "label": "可能补语"}, {"form": "管得好", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "负责照看东西或动物，不让它乱跑、丢失或变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3530f0c-2ea7-4f92-a396-cbac9f313f3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管好", "is_correct": true, "explanation": "正确：原句为“主人要管好它”，空格应填“管好”。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：狗不能被“吃掉”来看管，此处意思不通。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”用于火、灯等，不能用于狗。"}, {"text": "砸碎", "is_correct": false, "explanation": "语义：“砸碎”是毁坏，与“看管”的意思相反。"}], "explanations": {"管好": "正确：原句为“主人要管好它”，空格应填“管好”。", "吃掉": "语义：狗不能被“吃掉”来看管，此处意思不通。", "点燃": "搭配：“点燃”用于火、灯等，不能用于狗。", "砸碎": "语义：“砸碎”是毁坏，与“看管”的意思相反。"}, "sentence_index": 0, "correct_answer": "管好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把桌子管好，客人马上就到。", "explanation": "这里应该用〈摆好〉。管好表示管理照看，摆放桌子要说摆好。"}, {"text": "他这次数学管好了，分数很高。", "explanation": "这里应该用〈考好〉。管好不表示考试成绩，考得好要说考好。"}, {"text": "他管好了一盘棋，还没吃饭。", "explanation": "这里应该用〈下完〉。管好表示管理照看，下棋要说下完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管好", "is_correct": true, "explanation": "正确：原句为“要管好冰箱里的菜，不然会变坏”，空格应填“管好”。"}, {"text": "晒", "is_correct": false, "explanation": "语义：冰箱里的菜不能被“晒”来防止变坏，此处意思不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于菜。"}, {"text": "踢", "is_correct": false, "explanation": "语义：菜不能被“踢”来防止变坏，此处意思不通。"}], "explanations": {"管好": "正确：原句为“要管好冰箱里的菜，不然会变坏”，空格应填“管好”。", "晒": "语义：冰箱里的菜不能被“晒”来防止变坏，此处意思不通。", "唱": "搭配：“唱”不能用于菜。", "踢": "语义：菜不能被“踢”来防止变坏，此处意思不通。"}, "sentence_index": 6, "correct_answer": "管好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们管好了一首歌，大家鼓掌。", "explanation": "这里应该用〈唱完〉。管好表示管理照看，歌要说唱完。"}, {"text": "这场雨终于管好了。", "explanation": "这里应该用〈停〉。管好指管理照看人或物，雨不能被管理，雨停要说停。"}, {"text": "他终于管好了那一千米。", "explanation": "这里应该用〈游完〉。管好不表示游泳的距离，游完一千米要说游完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨天他不管好那只鸟，鸟飞走了。", "corrected_sentence": "昨天他没管好那只鸟，鸟飞走了。", "error_description": "否定错误：“管好”是动结式，表示过去没有做到要用“没”，应说“没管好”，不能说“不管好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天都很管好家里的鸡。", "corrected_sentence": "妈妈每天都管好家里的鸡。", "error_description": "副词位置错误：“很”不能直接修饰动词“管好”，应去掉“很”，说“妈妈每天都管好家里的鸡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6303c19c-f6ae-4cee-974f-5fd72e396792') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
