INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (34972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人叫你的那个词。", "primary_collocate": null, "pronunciation": "míng zi", "ipa": "miŋ˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "你叫什么名字？", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的名字是小明。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师记住了我的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的名字很好听。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请在这里写上你的名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道他的名字。", "target_word": "名字", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给我起了这个名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一叫我的名字，我就回头了。", "target_word": "名字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子还没有名字。", "target_word": "名字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能告诉我你朋友的名字吗？", "target_word": "名字", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个名字", "label": "量词"}], "register": "中性", "sense_fingerprint": "别人称呼你的词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
